app/assistant.py:
"""The rule-based assistant's brain: question text -> intent + parameters. PURE: no database, no network, integer paise.

This is not a language model. It looks for words and patterns, in a fixed order, and says so when it doesn't understand.
The service (assistant_service) answers by calling the same functions the screens use.

Periods: weeks start on Monday; "month" means your budget month (it starts on your month start day); a month NAME
("in March") means that calendar month. Amounts: "₹1,500", "Rs 1500", "1.5k", "2 lakh", "1 crore".
"""
import calendar
import re
from dataclasses import dataclass, field
from datetime import date, timedelta
from decimal import Decimal

from .insights import budget_months, week_start

MONTHS = {m.lower(): i for i, m in enumerate(calendar.month_name) if m}
MONTHS.update({m.lower(): i for i, m in enumerate(calendar.month_abbr) if m and m != "May"})
MAX_QUESTION = 300

_UNITS = {"k": 1_000, "thousand": 1_000, "l": 100_000, "lac": 100_000, "lakh": 100_000, "lakhs": 100_000, "lacs": 100_000,
          "cr": 10_000_000, "crore": 10_000_000, "crores": 10_000_000}
_AMOUNT = re.compile(r"(?:₹|rs\.?|inr)?\s*(\d[\d,]*(?:\.\d+)?)\s*(k|thousand|lakhs?|lacs?|l|crores?|cr)?\b", re.I)


@dataclass
class Period:
    start: date
    end: date                   # may be after today for a whole month/week; the service clips to today
    label: str
    kind: str                   # day | week | month | year | days | named_month
    defaulted: bool = False
    previous: tuple[date, date] | None = None


@dataclass
class Parsed:
    intent: str
    question: str
    period: Period | None = None
    category: str | None = None         # a tag name, or "untagged"
    merchant: str | None = None
    amount: int | None = None           # paise
    limit: int = 5
    notes: list[str] = field(default_factory=list)


def parse_amount(text: str) -> int | None:
    """The first amount in the text, in paise, or None. '1.5k' = ₹1,500; '2 lakh' = ₹2,00,000. A bare year like 2026 is not an amount."""
    for m in _AMOUNT.finditer(text):
        num, unit = m.group(1), (m.group(2) or "").lower()
        has_symbol = bool(re.match(r"\s*(₹|rs|inr)", text[m.start():m.start() + 6], re.I))
        value = Decimal(num.replace(",", ""))
        if not unit and not has_symbol and re.fullmatch(r"(19|20)\d\d", num):
            continue
        if not unit and not has_symbol and value < 1:
            continue
        if unit:
            value *= _UNITS[unit]
        paise = int((value * 100).to_integral_value())
        if paise > 0:
            return paise
    return None


def _month_range(y: int, m: int) -> tuple[date, date]:
    return date(y, m, 1), date(y, m, calendar.monthrange(y, m)[1])


def parse_period(text: str, today: date, month_start_day: int = 1) -> Period | None:
    t = text.lower()
    months = budget_months(today, month_start_day, 14)
    cur, prev = months[-1], months[-2]
    if re.search(r"\byesterday\b", t):
        d = today - timedelta(days=1)
        return Period(d, d, "yesterday", "day", previous=(d - timedelta(days=1), d - timedelta(days=1)))
    if re.search(r"\btoday\b", t):
        return Period(today, today, "today", "day", previous=(today - timedelta(days=1), today - timedelta(days=1)))
    m = re.search(r"\b(?:last|past|previous)\s+(\d{1,3})\s+(day|week|month)s?\b", t)
    if m:
        n, unit = int(m.group(1)), m.group(2)
        days = n * {"day": 1, "week": 7, "month": 30}[unit]
        s = today - timedelta(days=days - 1)
        return Period(s, today, f"the last {n} {unit}{'s' if n != 1 else ''}", "days", previous=(s - timedelta(days=days), s - timedelta(days=1)))
    if re.search(r"\blast\s+week\b|\bprevious\s+week\b", t):
        s = week_start(today) - timedelta(days=7)
        return Period(s, s + timedelta(days=6), "last week (Monday to Sunday)", "week", previous=(s - timedelta(days=7), s - timedelta(days=1)))
    if re.search(r"\bthis\s+week\b|\bweek\s+so\s+far\b", t):
        s = week_start(today)
        return Period(s, s + timedelta(days=6), "this week (from Monday)", "week", previous=(s - timedelta(days=7), s - timedelta(days=7) + (today - s)))
    if re.search(r"\blast\s+month\b|\bprevious\s+month\b", t):
        return Period(prev["start"], prev["end"], f"last month ({prev['start'].isoformat()} to {prev['end'].isoformat()})", "month",
                      previous=(months[-3]["start"], months[-3]["end"]))
    if re.search(r"\bthis\s+month\b|\bmonth\s+so\s+far\b|\bthis\s+budget\s+month\b", t):
        return Period(cur["start"], cur["end"], f"this month (from {cur['start'].isoformat()})", "month",
                      previous=(prev["start"], min(prev["end"], prev["start"] + (today - cur["start"]))))
    if re.search(r"\blast\s+year\b", t):
        return Period(date(today.year - 1, 1, 1), date(today.year - 1, 12, 31), f"{today.year - 1}", "year")
    if re.search(r"\bthis\s+year\b|\byear\s+so\s+far\b", t):
        return Period(date(today.year, 1, 1), date(today.year, 12, 31), f"{today.year} so far", "year", previous=(date(today.year - 1, 1, 1), date(today.year - 1, today.month, min(today.day, 28))))
    m = re.search(r"\b(?:in|during|for|of)\s+(" + "|".join(sorted(MONTHS, key=len, reverse=True)) + r")\b(?:\s+(\d{4}))?", t)
    if m:
        mo = MONTHS[m.group(1)]
        y = int(m.group(2)) if m.group(2) else (today.year if mo <= today.month else today.year - 1)
        s, e = _month_range(y, mo)
        py, pm = (y, mo - 1) if mo > 1 else (y - 1, 12)
        return Period(s, e, f"{calendar.month_name[mo]} {y} (calendar month)", "named_month", previous=_month_range(py, pm))
    return None


def _word(text: str, name: str) -> bool:
    return bool(re.search(r"(?<![\w])" + re.escape(name.lower()) + r"(?![\w])", text))


def find_name(text: str, names: list[str]) -> str | None:
    """The longest known name that appears as whole words in the text."""
    t = text.lower()
    hits = [n for n in names if n and len(n) >= 2 and _word(t, n)]
    return max(hits, key=len) if hits else None


# intent rules, tried in order; the first that matches wins
RULES: list[tuple[str, str]] = [
    ("afford", r"\bafford\b|\bcan i (?:buy|spend|pay|get)\b|\bis it ok to (?:buy|spend)\b|\bshould i (?:buy|spend)\b"),
    ("safe", r"safe[\s-]*to[\s-]*spend|\bhow much can i (?:still )?spend\b|\bleft to spend\b|\bspendable\b|\bhow much (?:do i have|is left)\b"),
    ("bills", r"\bbills?\b|\bdue\b|\bupcoming\b|\bwhat do i (?:have to )?pay\b|\bemi\b"),
    ("recurring", r"\bsubscriptions?\b|\brecurring\b|\bregular payments?\b|\bautopay\b"),
    ("budget", r"\bbudgets?\b|\bover budget\b|\blimit\b"),
    ("compare", r"\bcompare\b|\bcompared\b|\bversus\b|\bvs\.?\b|\bmore than\b|\bless than\b|\bdid i spend (?:more|less)\b|\bchange\b|\bcompared to\b"),
    ("top_category", r"\b(?:most|biggest|largest|highest|top)\b.{0,25}\bcategor|\bwhere (?:did|does) (?:my|the) money go\b|\bspend (?:the )?most on\b|\bmost on\b|\bby category\b|\bbreak ?down\b"),
    ("largest", r"\b(?:biggest|largest|highest|top|costliest|most expensive)\b"),
    ("income", r"\bearn(?:ed|ings)?\b|\bincome\b|\breceived?\b|\bsalary\b|\bcredited\b|\bgot paid\b|\bmoney in\b"),
    ("untagged", r"\buntagged\b|\buncategori[sz]ed\b|\bno tag\b"),
    ("review", r"\bneeds? (?:my )?(?:review|attention|a look)\b|\btrustledger\b|\bduplicates?\b|\breconcil|\bdoesn'?t add up\b|\bunmatched\b|\bflagged\b|\bissues?\b"),
    ("count", r"\bhow many\b|\bnumber of\b|\bcount\b"),
    ("spend", r"\bspen[dt]\b|\bexpenses?\b|\bpaid\b|\bcost\b|\bhow much\b|\bspending\b"),
    ("help", r"\bhelp\b|\bwhat can you\b|\bhow do you work\b|\bwho are you\b|\bwhat are you\b"),
]


def parse(question: str, today: date, *, month_start_day: int = 1, categories: list[str] = (), merchants: list[str] = ()) -> Parsed:
    q = (question or "").strip()[:MAX_QUESTION]
    t = q.lower()
    intent = "unknown"
    for name, pattern in RULES:
        if re.search(pattern, t):
            intent = name
            break
    if intent == "afford" and parse_amount(q) is None:
        intent = "unknown_afford"
    p = Parsed(intent, q)
    p.period = parse_period(q, today, month_start_day)
    if intent == "compare":                     # "this month with last month": the first named is the one being judged
        for unit in ("month", "week"):
            if re.search(rf"this\s+{unit}", t) and re.search(rf"last\s+{unit}", t):
                p.period = parse_period(f"this {unit}", today, month_start_day)
    p.amount = parse_amount(q)
    if "untagged" in t or "uncategori" in t:
        p.category = "untagged"
    else:
        p.merchant = find_name(t, list(merchants))
        if not p.merchant:
            p.category = find_name(t, list(categories))
    m = re.search(r"\b(?:top|biggest|largest)\s+(\d{1,2})\b", t)
    if m:
        p.limit = max(1, min(int(m.group(1)), 20))
    if p.period is None and intent in ("spend", "income", "count", "top_category", "largest", "compare", "untagged"):
        s = budget_months(today, month_start_day, 2)[-1]
        p.period = Period(s["start"], s["end"], f"this month (from {s['start'].isoformat()})", "month", defaulted=True,
                          previous=None)
        pm = budget_months(today, month_start_day, 2)[-2]
        p.period.previous = (pm["start"], min(pm["end"], pm["start"] + (today - s["start"])))
        p.notes.append("You didn't name a period, so I used this month.")
    return p


CHIPS = [
    "How much did I spend this month?",
    "How much did I spend last week?",
    "What did I spend the most on this month?",
    "Compare this month with last month",
    "What is my safe to spend?",
    "Can I afford ₹1,500?",
    "What bills are coming up?",
    "Which subscriptions do I have?",
    "Am I over budget?",
    "What are my biggest expenses this month?",
    "How many untagged transactions are there?",
    "What needs my review?",
]

app/assistant_service.py:
"""Answers the rule-based assistant's questions using the SAME functions the screens use, so a number in chat always matches its screen.

Spending is refund-netted (insights_service.spend / storage.amount_sql); Safe-to-Spend comes from sts_service.estimate; budgets from the
budgets router's own function; recurring items from the plan. Nothing here computes its own money rules. Every answer says which period it
used and offers a "View transactions" filter (carried in router state, never a URL).
"""
import sqlite3
from datetime import date

from . import assistant as asst
from . import insights_service, recon_service, recurring_service, sts_service, trust_service
from .insights import budget_months
from .routers.budgets import budget_items
from .routers.plan import _next_occurrence
from .storage import COUNTS_IN_REPORTS, amount_sql, counts_sql, get_settings
from .trustledger import inr

PROVIDER = "Demo assistant (rule-based, runs on your device)"


def _names(conn: sqlite3.Connection) -> tuple[list[str], list[str]]:
    cats = [r["name"] for r in conn.execute("SELECT name FROM tags ORDER BY name")]
    merchants = [r["m"] for r in conn.execute(
        f"SELECT COALESCE(NULLIF(t.merchant_clean, ''), t.payee) AS m, COUNT(*) AS n FROM transactions t WHERE {COUNTS_IN_REPORTS} "
        "GROUP BY lower(COALESCE(NULLIF(t.merchant_clean, ''), t.payee)) ORDER BY n DESC LIMIT 400")]
    return cats, merchants


def _tag_id(conn: sqlite3.Connection, name: str) -> int | None:
    r = conn.execute("SELECT id FROM tags WHERE lower(name) = lower(?)", (name,)).fetchone()
    return r["id"] if r else None


def _scope_sql(conn, tag: str | None, merchant: str | None) -> tuple[str, list, str]:
    """WHERE fragment, args and a human description of the extra filter."""
    sql, args, desc = "", [], ""
    if tag == "untagged":
        sql, desc = " AND t.tag_id IS NULL", " that are untagged"
    elif tag:
        sql, args, desc = " AND t.tag_id = ?", [_tag_id(conn, tag)], f" on {tag}"
    if merchant:
        like = "%" + merchant.lower().replace("\\", "\\\\").replace("%", "\\%").replace("_", "\\_") + "%"
        sql += " AND (lower(t.payee) LIKE ? ESCAPE '\\' OR lower(COALESCE(t.merchant_clean, '')) LIKE ? ESCAPE '\\')"
        args += [like, like]
        desc += f" at {merchant}"
    return sql, args, desc


def total(conn, kind: str, start: date, end: date, tag=None, merchant=None) -> tuple[int, int]:
    """(paise, count) of debits (refund-netted) or credits (matched refunds left out) in [start, end]."""
    sql, args, _ = _scope_sql(conn, tag, merchant)
    r = conn.execute(f"SELECT COALESCE(SUM({amount_sql(False)}), 0) AS s, COUNT(*) AS n FROM transactions t WHERE {counts_sql(False)} AND t.type = ?"
                     f" AND substr(t.date_time, 1, 10) BETWEEN ? AND ?{sql}", [kind, start.isoformat(), end.isoformat(), *args]).fetchone()
    return r["s"], r["n"]


def _filters(conn, p: asst.Parsed, start: date, end: date, kind="debit") -> dict:
    f = {"date_from": start.isoformat(), "date_to": end.isoformat(), "type": kind}
    if p.category:
        tid = "untagged" if p.category == "untagged" else _tag_id(conn, p.category)
        if tid:
            f["tag"] = str(tid) if tid != "untagged" else tid
    if p.merchant:
        f["payee"] = p.merchant
    return f


def _in(label: str) -> str:
    return label if label in ("today", "yesterday") else f"in {label}"


def _clip(per: asst.Period, today: date) -> tuple[date, date]:
    return per.start, min(per.end, today)


def _reply(text, p, *, figures=None, filters=None, link=None, how=None, intent=None, extra=None):
    out = {"answer": text, "intent": intent or p.intent, "provider": PROVIDER, "figures": figures or [], "filters": filters, "link": link,
           "how": how or [], "notes": p.notes, "period": None}
    if p.period:
        out["period"] = {"start": p.period.start.isoformat(), "end": p.period.end.isoformat(), "label": p.period.label, "defaulted": p.period.defaulted}
    if extra:
        out.update(extra)
    return out


def answer(conn: sqlite3.Connection, question: str, today: date) -> dict:
    raw = get_settings(conn)
    cats, merchants = _names(conn)
    p = asst.parse(question, today, month_start_day=raw["month_start_day"], categories=cats, merchants=merchants)
    fn = HANDLERS.get(p.intent, _unknown)
    return fn(conn, p, today, raw)


# ---- handlers ----------------------------------------------------------------------------------------------------------

def _spend(conn, p, today, raw):
    s, e = _clip(p.period, today)
    amt, n = total(conn, "debit", s, e, p.category, p.merchant)
    _, _, desc = _scope_sql(conn, p.category, p.merchant)
    if n == 0:
        return _reply(f"I found no spending{desc} {_in(p.period.label)}.", p, filters=_filters(conn, p, s, e), how=["Net of matched refunds; failed, reversed and pending payments are left out."])
    return _reply(f"You spent {inr(amt)}{desc} {_in(p.period.label)}, across {n} payment{'s' if n != 1 else ''}.", p,
                  figures=[{"label": "Spent", "paise": amt}], filters=_filters(conn, p, s, e),
                  how=["Net of matched refunds; failed, reversed and pending payments are left out.", f"Counted {s.isoformat()} to {e.isoformat()}."])


def _income(conn, p, today, raw):
    s, e = _clip(p.period, today)
    amt, n = total(conn, "credit", s, e, p.category, p.merchant)
    if n == 0:
        return _reply(f"I found no money received {_in(p.period.label)}.", p, filters=_filters(conn, p, s, e, "credit"))
    return _reply(f"You received {inr(amt)} {_in(p.period.label)}, across {n} credit{'s' if n != 1 else ''}.", p, figures=[{"label": "Received", "paise": amt}],
                  filters=_filters(conn, p, s, e, "credit"), how=["Refunds already matched to a purchase are not counted as income."])


def _count(conn, p, today, raw):
    s, e = _clip(p.period, today)
    if p.category == "untagged" and p.period.defaulted:
        n = conn.execute(f"SELECT COUNT(*) FROM transactions t WHERE {COUNTS_IN_REPORTS} AND t.tag_id IS NULL").fetchone()[0]
        return _reply(f"{n} transaction{'s are' if n != 1 else ' is'} untagged in total.", p, filters={"tag": "untagged"}, link="/inbox")
    sql, args, desc = _scope_sql(conn, p.category, p.merchant)
    n = conn.execute(f"SELECT COUNT(*) FROM transactions t WHERE {COUNTS_IN_REPORTS} AND substr(t.date_time, 1, 10) BETWEEN ? AND ?{sql}",
                     [s.isoformat(), e.isoformat(), *args]).fetchone()[0]
    return _reply(f"{n} transaction{'s' if n != 1 else ''}{desc} {_in(p.period.label)}.", p, filters={k: v for k, v in _filters(conn, p, s, e).items() if k != "type"})


def _untagged(conn, p, today, raw):
    n = conn.execute(f"SELECT COUNT(*) FROM transactions t WHERE {COUNTS_IN_REPORTS} AND t.tag_id IS NULL").fetchone()[0]
    return _reply(f"{n} transaction{'s are' if n != 1 else ' is'} untagged." + (" Tagging them makes your category figures more complete." if n else ""),
                  p, filters={"tag": "untagged"}, link="/inbox", intent="untagged")


def _top_category(conn, p, today, raw):
    s, e = _clip(p.period, today)
    sp = insights_service.spend(conn, s, e)
    rows = sorted(sp["by_tag"].values(), key=lambda c: -c["total_paise"])[:5]
    if not rows:
        return _reply(f"I found no spending {_in(p.period.label)}.", p)
    top = rows[0]
    lines = [f"{c['tag']}: {inr(c['total_paise'])}" for c in rows]
    f = {"date_from": s.isoformat(), "date_to": e.isoformat(), "type": "debit", "tag": "untagged" if top["tag_id"] is None else str(top["tag_id"])}
    return _reply(f"Your biggest category {_in(p.period.label)} was {top['tag']} at {inr(top['total_paise'])} ({round(top['total_paise'] / sp['total_paise'] * 100)}% of {inr(sp['total_paise'])}). "
                  f"Top {len(rows)}: " + "; ".join(lines) + ".", p, figures=[{"label": c["tag"], "paise": c["total_paise"]} for c in rows], filters=f,
                  how=["Net of matched refunds; failed, reversed and pending payments are left out."])


def _largest(conn, p, today, raw):
    s, e = _clip(p.period, today)
    sql, args, desc = _scope_sql(conn, p.category, p.merchant)
    rows = conn.execute(f"SELECT t.id, t.date_time, t.payee, {amount_sql(False)} AS amt FROM transactions t WHERE {counts_sql(False)} AND t.type = 'debit' "
                        f"AND substr(t.date_time, 1, 10) BETWEEN ? AND ?{sql} ORDER BY amt DESC, t.id LIMIT ?", [s.isoformat(), e.isoformat(), *args, p.limit]).fetchall()
    rows = [r for r in rows if r["amt"] > 0]
    if not rows:
        return _reply(f"I found no spending{desc} {_in(p.period.label)}.", p)
    lines = [f"{r['payee']} {inr(r['amt'])} on {r['date_time'][:10]}" for r in rows]
    return _reply(f"Your {len(rows)} biggest payment{'s' if len(rows) != 1 else ''}{desc} {_in(p.period.label)}: " + "; ".join(lines) + ".", p,
                  figures=[{"label": r["payee"], "paise": r["amt"]} for r in rows], filters=_filters(conn, p, s, e),
                  how=["Net of matched refunds."], extra={"tx_ids": [r["id"] for r in rows]})


def _compare(conn, p, today, raw):
    per = p.period
    if not per.previous:
        return _reply("I need a month, week or day to compare. Try “Compare this month with last month”.", p)
    s, e = _clip(per, today)
    ps, pe = per.previous
    now, n1 = total(conn, "debit", s, e, p.category, p.merchant)
    before, n0 = total(conn, "debit", ps, pe, p.category, p.merchant)
    _, _, desc = _scope_sql(conn, p.category, p.merchant)
    if n0 == 0:
        return _reply(f"Not enough history yet: nothing{desc} between {ps.isoformat()} and {pe.isoformat()} to compare with. {inr(now)} so far {_in(per.label)}.", p,
                      figures=[{"label": "Now", "paise": now}], filters=_filters(conn, p, s, e))
    diff = now - before
    word = "more" if diff > 0 else "less" if diff < 0 else "the same"
    pct = f" ({diff / before * 100:+.0f}%)" if before else ""
    txt = (f"{_in(per.label).capitalize()} you spent {inr(now)}{desc}, against {inr(before)} for {ps.isoformat()} to {pe.isoformat()}: " +
           (f"{inr(abs(diff))} {word}{pct}." if diff else "the same."))
    return _reply(txt, p, figures=[{"label": "Now", "paise": now}, {"label": "Before", "paise": before}, {"label": "Difference", "paise": diff}],
                  filters=_filters(conn, p, s, e), how=["Both periods are net of matched refunds."], link="/insights")


def _safe(conn, p, today, raw):
    e = sts_service.estimate(conn, today)
    if not e.get("has_balance"):
        return _reply("I can't estimate that yet: Safe to spend needs a starting balance. You can enter one in Budgets → Safe to spend.", p, link="/budgets")
    w = e["windows"]
    parts = [f"{k}: {inr(w[k]['safe_paise'])}" for k in ("today", "week", "month") if k in w]
    short = w["month"]["shortfall_paise"]
    txt = "Your estimated safe-to-spend is " + "; ".join(parts) + "." + (f" The month is short by {inr(short)}." if short else "")
    conf = e.get("confidence") or {}
    return _reply(txt, p, figures=[{"label": k, "paise": w[k]["safe_paise"]} for k in ("today", "week", "month") if k in w], link="/budgets",
                  how=["It is an estimate, not your bank balance.", f"Confidence: {conf.get('level', conf.get('label', 'not rated'))}."])


def _afford(conn, p, today, raw):
    r = sts_service.afford_check(conn, p.amount, today)
    return _reply(f"{r.get('message', '')}".strip() or "I couldn't work that out.", p, figures=[{"label": "Amount", "paise": p.amount}], link="/budgets",
                  how=["Uses your Safe to spend estimate; it is not a bank balance."], extra={"verdict": r.get("verdict")})


def _bills(conn, p, today, raw):
    rows = conn.execute("SELECT * FROM recurring_items WHERE active = 1 AND kind IN ('bill', 'subscription')").fetchall()
    due = sorted(((_next_occurrence(r, today), r) for r in rows), key=lambda x: x[0] or "9999")
    due = [(d, r) for d, r in due if d][:6]
    if not due:
        return _reply("You have no bills or subscriptions in your plan yet. Add them in Budgets → Bills.", p, link="/budgets")
    lines = [f"{r['name']} {inr(r['amount'])} on {d}" for d, r in due]
    return _reply("Coming up: " + "; ".join(lines) + ".", p, figures=[{"label": r["name"], "paise": r["amount"]} for _, r in due], link="/budgets")


def _recurring(conn, p, today, raw):
    rows = conn.execute("SELECT * FROM recurring_items WHERE active = 1 AND kind = 'subscription' ORDER BY amount DESC").fetchall()
    cands = recurring_service.candidates(conn, today)["items"]
    if not rows and not cands:
        return _reply("No subscriptions in your plan, and nothing new looks recurring.", p, link="/budgets")
    txt = ("Subscriptions in your plan: " + "; ".join(f"{r['name']} {inr(r['amount'])} ({r['cadence']})" for r in rows) + "." if rows else "No subscriptions in your plan.")
    if cands:
        txt += f" {len(cands)} payment pattern{'s' if len(cands) != 1 else ''} look recurring and are waiting for you to confirm in Insights."
    return _reply(txt, p, figures=[{"label": r["name"], "paise": r["amount"]} for r in rows], link="/insights")


def _budget(conn, p, today, raw):
    items = budget_items(conn, today.isoformat()[:7], raw["budget_alert_pct"])["items"]
    if p.category and p.category != "untagged":
        items = [b for b in items if b["tag_name"].lower() == p.category.lower()]
    if not items:
        return _reply("You haven't set a budget" + (f" for {p.category}" if p.category else "") + " yet. You can in Budgets.", p, link="/budgets")
    word = {"ok": "on track", "warning": "close to the limit", "over": "over budget"}
    lines = [f"{b['tag_name']}: {inr(round(b['spent'] * 100))} of {inr(round(b['limit'] * 100))} ({word[b['level']]})" for b in items]
    return _reply("This month (calendar month, like the Budgets screen): " + "; ".join(lines) + ".", p, link="/budgets",
                  figures=[{"label": b["tag_name"], "paise": round(b["spent"] * 100)} for b in items])


def _review(conn, p, today, raw):
    t, r = trust_service.summary(conn), recon_service.summary(conn)
    n1, n2 = t.get("open_issue_count", 0), r.get("open", 0)
    if not n1 and not n2:
        return _reply("Nothing is waiting for review in TrustLedger or Reconciliation.", p)
    return _reply(f"{n1} item{'s' if n1 != 1 else ''} in TrustLedger and {n2} in Reconciliation could use a look. Neither means anything is wrong; they are things Paisa can't confirm on its own.", p,
                  link="/trust", figures=[])


def _help(conn, p, today, raw):
    return _reply("I'm a simple rule-based helper that runs on your device. I can answer questions about spending (by period, category or merchant), income, "
                  "biggest payments, comparisons, Safe to spend, whether you can afford something, bills, subscriptions, budgets, untagged items and what needs review. "
                  "Every number comes from the same place as the screens.", p, extra={"examples": asst.CHIPS[:6]})


def _unknown(conn, p, today, raw):
    if p.intent == "unknown_afford":
        return _reply("To check what you can afford I need an amount, like “Can I afford ₹1,500?”.", p, extra={"examples": ["Can I afford ₹1,500?"]})
    return _reply("I can't answer that yet. I'm a simple rule-based helper, not a language model, so I only understand a set of money questions.", p, intent="unknown",
                  extra={"examples": asst.CHIPS[:6]})


HANDLERS = {"spend": _spend, "income": _income, "count": _count, "untagged": _untagged, "top_category": _top_category, "largest": _largest,
            "compare": _compare, "safe": _safe, "afford": _afford, "bills": _bills, "recurring": _recurring, "budget": _budget, "review": _review, "help": _help}

app/autotag.py:
"""Auto-tag rules: "if payee contains X, tag as Y".

Kept free of FastAPI so it is easy to test and reuse from seeding and import.
"""
import sqlite3


def match_tag(payee: str, rules: list[tuple[str, int]]) -> int | None:
    """Return the tag id of the first matching rule, or None.

    `rules` is a list of (pattern, tag_id), already ordered best-first.
    Matching is a case-insensitive substring test; blank patterns never match.
    """
    text = payee.casefold()
    for pattern, tag_id in rules:
        pattern = pattern.strip().casefold()
        if pattern and pattern in text:
            return tag_id
    return None


def match_rule(payee: str, rules: list[tuple[str, int]]) -> tuple[int, str] | None:
    """Like match_tag, but also returns the pattern that matched, so the screen can say "Your rule: swiggy"."""
    text = payee.casefold()
    for pattern, tag_id in rules:
        p = pattern.strip().casefold()
        if p and p in text:
            return tag_id, pattern.strip()
    return None


def load_rules(conn: sqlite3.Connection) -> list[tuple[str, int]]:
    """Rules ordered by priority (high first), then newest first."""
    rows = conn.execute(
        "SELECT pattern, tag_id FROM tag_rules ORDER BY priority DESC, id DESC"
    ).fetchall()
    return [(r["pattern"], r["tag_id"]) for r in rows]


def tag_for_payee(conn: sqlite3.Connection, payee: str) -> int | None:
    return match_tag(payee, load_rules(conn))

app/backup.py:
"""Backup and restore. One versioned JSON file holding every table's rows, plain on this side of the API.

Encryption (optional) is done in the browser with WebCrypto, so a passphrase never reaches the backend; see frontend/src/backupCrypto.js.

Restore never edits your data in place. It builds the backup in a scratch in-memory database at the backup's OWN schema version, runs the
newer migrations there, checks constraints and foreign keys, and only then, after a safety snapshot, swaps the contents of the live database
inside one transaction. Any failure rolls back and leaves your data as it was.
"""
import json
import sqlite3
from datetime import datetime
from pathlib import Path

from . import db, migrations

FORMAT = "paisa-backup"
VERSION = 1                       # the file layout; the schema version is stored separately
SKIP = {"schema_migrations", "sqlite_sequence"}
MAX_ROWS = 2_000_000


class BackupError(Exception):
    def __init__(self, message: str, status: int = 400):
        super().__init__(message)
        self.status = status


def _tables(conn: sqlite3.Connection) -> list[str]:
    return [r[0] for r in conn.execute("SELECT name FROM sqlite_master WHERE type = 'table' AND name NOT LIKE 'sqlite_%' ORDER BY name") if r[0] not in SKIP]


def export(conn: sqlite3.Connection) -> dict:
    """Everything in the database as plain data. Rows are lists in column order (compact); `columns` names them."""
    out = {}
    for t in _tables(conn):
        cur = conn.execute(f"SELECT * FROM {t}")
        cols = [d[0] for d in cur.description]
        rows = [list(r) for r in cur.fetchall()]
        if t == "meta":                                   # the passcode hash belongs to this device, not to a backup file
            k = cols.index("key")
            rows = [r for r in rows if not str(r[k]).startswith("passcode")]
        out[t] = {"columns": cols, "rows": rows}
    return {"format": FORMAT, "version": VERSION, "schema_version": migrations.current_version(conn), "app_schema_latest": migrations.LATEST,
            "created_at": datetime.now().isoformat(timespec="seconds"), "mode": db.mode(), "tables": out,
            "counts": {t: len(v["rows"]) for t, v in out.items()}}


def mark_exported(conn: sqlite3.Connection) -> None:
    conn.execute("INSERT INTO settings (key, value) VALUES ('last_backup_at', ?) ON CONFLICT(key) DO UPDATE SET value = excluded.value, updated_at = datetime('now', 'localtime')",
                 (json.dumps(datetime.now().isoformat(timespec="seconds")),))
    conn.commit()


def validate(doc) -> dict:
    """Shape checks that need no database. Returns a short description, or raises BackupError with a plain reason."""
    if not isinstance(doc, dict) or doc.get("format") != FORMAT:
        raise BackupError("This is not a Paisa backup file.")
    if not isinstance(doc.get("version"), int) or doc["version"] > VERSION:
        raise BackupError("This backup was made by a newer version of Paisa than this one. Update Paisa first.")
    sv = doc.get("schema_version")
    if not isinstance(sv, int) or sv < 1:
        raise BackupError("The backup does not say which database version it came from, so it can't be read safely.")
    if sv > migrations.LATEST:
        raise BackupError(f"This backup is from a newer database version ({sv}) than this Paisa understands ({migrations.LATEST}). Update Paisa first.")
    tables = doc.get("tables")
    if not isinstance(tables, dict) or "transactions" not in tables:
        raise BackupError("The backup is missing its transactions, so it looks damaged.")
    total = 0
    for name, t in tables.items():
        if not isinstance(t, dict) or not isinstance(t.get("columns"), list) or not isinstance(t.get("rows"), list):
            raise BackupError(f"The “{name}” part of the backup is damaged.")
        n = len(t["columns"])
        if any(not isinstance(r, list) or len(r) != n for r in t["rows"]):
            raise BackupError(f"Some rows in “{name}” don't match its columns, so the file looks damaged.")
        total += len(t["rows"])
    if total > MAX_ROWS:
        raise BackupError("That backup is larger than this version can restore.")
    return {"schema_version": sv}


def _scratch(doc: dict) -> sqlite3.Connection:
    """The backup, loaded and migrated to the current schema in a scratch database. Raises BackupError if it doesn't hold together."""
    info = validate(doc)
    s = sqlite3.connect(":memory:")
    s.row_factory = sqlite3.Row
    try:
        migrations.migrate(s, upto=info["schema_version"])
        s.execute("PRAGMA foreign_keys = OFF")
        for name, t in doc["tables"].items():
            if name in SKIP:
                continue
            exists = s.execute("SELECT 1 FROM sqlite_master WHERE type = 'table' AND name = ?", (name,)).fetchone()
            if not exists:
                raise BackupError(f"The backup has a “{name}” part that Paisa version {info['schema_version']} does not know about.")
            have = {r[1] for r in s.execute(f"PRAGMA table_info({name})")}
            bad = [c for c in t["columns"] if c not in have]
            if bad:
                raise BackupError(f"The “{name}” part has unknown fields ({', '.join(map(str, bad[:3]))}), so the file looks damaged or altered.")
            cols = ", ".join(t["columns"])
            marks = ", ".join("?" for _ in t["columns"])
            try:
                s.executemany(f"INSERT INTO {name} ({cols}) VALUES ({marks})", t["rows"])
            except sqlite3.Error as e:
                raise BackupError(f"A row in “{name}” was refused ({e}), so the file looks damaged or altered.")
        s.commit()
        migrations.migrate(s)
        bad = s.execute("PRAGMA foreign_key_check").fetchall()
        if bad:
            raise BackupError(f"{len(bad)} entries point at things that aren't in the backup (for example in “{bad[0][0]}”), so it looks damaged.")
        return s
    except Exception:
        s.close()
        raise


def preview(conn: sqlite3.Connection, doc) -> dict:
    """What restoring WOULD do. Changes nothing."""
    s = _scratch(doc)
    try:
        n = s.execute("SELECT COUNT(*) FROM transactions").fetchone()[0]
        dates = s.execute("SELECT MIN(substr(date_time, 1, 10)), MAX(substr(date_time, 1, 10)) FROM transactions").fetchone()
        mine = conn.execute("SELECT COUNT(*) FROM transactions").fetchone()[0]
        return {"ok": True, "created_at": doc.get("created_at"), "schema_version": doc["schema_version"], "current_schema_version": migrations.LATEST,
                "will_migrate": doc["schema_version"] < migrations.LATEST, "transactions": n, "first_date": dates[0], "last_date": dates[1],
                "counts": {k: len(v["rows"]) for k, v in doc["tables"].items() if len(v["rows"])},
                "replaces": {"transactions": mine}, "warning": "Restoring replaces everything currently in Paisa with the contents of this backup."}
    finally:
        s.close()


def snapshot(conn: sqlite3.Connection, reason: str = "before-restore") -> dict:
    """A consistent copy of the live database, kept next to it (computer mode) or in the browser's filesystem (app mode)."""
    path = db.db_path()
    dest_dir = path.parent / "backups"
    dest_dir.mkdir(parents=True, exist_ok=True)
    dest = dest_dir / f"paisa-{reason}-{datetime.now():%Y%m%d-%H%M%S}.db"
    out = sqlite3.connect(dest)
    try:
        conn.backup(out)
    finally:
        out.close()
    return {"path": str(dest), "where": "in the browser's storage for this app" if db.mode() == "app" else "next to your database", "size": Path(dest).stat().st_size}


def restore(conn: sqlite3.Connection, doc) -> dict:
    """Replace the live data with the backup. All or nothing."""
    s = _scratch(doc)
    try:
        snap = snapshot(conn)
        conn.commit()
        conn.execute("PRAGMA foreign_keys = OFF")
        conn.execute("BEGIN")
        live = set(_tables(conn))
        mine = [r[0] for r in s.execute("SELECT name FROM sqlite_master WHERE type = 'table' AND name NOT LIKE 'sqlite_%'") if r[0] not in SKIP]
        stamps = {r[0]: r[1] for r in s.execute("SELECT id, updated_at FROM transactions")}
        keep = conn.execute("SELECT key, value FROM meta WHERE key LIKE 'passcode%'").fetchall()
        for t in live:
            conn.execute(f"DELETE FROM {t}")
        for k, v in keep:
            conn.execute("INSERT INTO meta (key, value) VALUES (?, ?)", (k, v))
        for t in mine:
            if t not in live:
                continue
            cur = s.execute(f"SELECT * FROM {t}" + (" WHERE key NOT LIKE 'passcode%'" if t == "meta" else ""))
            cols = [d[0] for d in cur.description]
            conn.executemany(f"INSERT INTO {t} ({', '.join(cols)}) VALUES ({', '.join('?' for _ in cols)})", [tuple(r) for r in cur.fetchall()])
        for tid, ts in stamps.items():                       # the insert trigger stamps updated_at; put the backed-up value back
            conn.execute("UPDATE transactions SET updated_at = ? WHERE id = ? AND updated_at IS NOT ?", (ts, tid, ts))
        conn.execute("INSERT INTO meta (key, value) VALUES ('last_restore', ?) ON CONFLICT(key) DO UPDATE SET value = excluded.value",
                     (json.dumps({"at": datetime.now().isoformat(timespec="seconds"), "from_schema": doc["schema_version"], "snapshot": snap["path"]}),))
        if conn.execute("PRAGMA foreign_key_check").fetchall():
            raise BackupError("The restored data didn't hold together, so nothing was changed.")
        conn.commit()
    except Exception:
        conn.rollback()
        raise
    finally:
        conn.execute("PRAGMA foreign_keys = ON")
        s.close()
    from . import trust_service
    trust_service.refresh(conn, "Backup restored")
    return {"restored": True, "snapshot": snap, "counts": {k: len(v["rows"]) for k, v in doc["tables"].items() if len(v["rows"])},
            "migrated_from": doc["schema_version"] if doc["schema_version"] < migrations.LATEST else None}

app/llm_provider.py:
"""Optional language-model provider for the assistant: a DISABLED STUB.

There is no implementation, no network code and no API key handling here on purpose. The rule-based assistant is the only provider.
If a real provider is ever added it must (see docs/ASSISTANT.md): be off unless the user switched on `assistant_llm_consent`, never be
available in app mode, receive only the question and aggregate figures already shown on screen (never raw transactions), and keep
nothing. Until then every call says it is unavailable.
"""
from . import db


class ProviderUnavailable(Exception):
    pass


def status(consent: bool) -> dict:
    mode = db.mode()
    if mode == "app":
