app/merchant.py:
"""Merchant names: cleaning bank narrations, matching the built-in list, and spotting payments to people.

Pure functions (no database), so they work the same on a computer and in the browser.

* `clean_merchant("UPI/DR/412345678901/SWIGGY/okaxis/Payment")` -> "Swiggy". The original text is always kept
  separately as `merchant_raw`, so cleaning is reversible.
* `DictionaryMatcher` finds a built-in merchant inside a name using WHOLE WORDS only.
* `looks_like_person` is a hint, never a decision: payments to individuals are not guessed into a spending
  category (they stay Untagged, with a one-tap "Transfers" suggestion).
"""
import re

from .merchant_dictionary import DICTIONARY

# ---- cleaning narrations ------------------------------------------------------

# Payment-rail words that start a structured narration: UPI/DR/..., IMPS-..., NEFT-..., RTGS/...
_RAIL = re.compile(r"^(upi|imps|neft|rtgs|nach|ach|ecs|mmt|inf|ift|bil|billpay|pos|ecom)\b", re.I)
# Parts of a narration that are not the merchant.
_FILLER = {"upi", "imps", "neft", "rtgs", "nach", "ach", "ecs", "mmt", "inf", "ift", "bil", "billpay", "dr", "cr",
           "p2a", "p2p", "p2m", "p2b", "payment", "payments", "pay", "paid", "transfer", "trf", "to", "from", "by",
           "via", "upi payment", "payment from phonepe", "payment to", "sent using paytm", "sent via upi", "ref",
           "refno", "txn", "debit", "credit", "attn", "ibft", "mob", "mobile banking"}
# Bank/app handles that appear after the merchant name in UPI narrations.
_HANDLES = {"okaxis", "okicici", "okhdfcbank", "oksbi", "ybl", "ibl", "axl", "paytm", "apl", "sbi", "hdfc", "hdfcbank",
            "icici", "axis", "axisbank", "kotak", "yesbank", "pnb", "boi", "idfc", "idfcfirst", "fbl", "indus", "rbl",
            "hsbc", "citi", "bank", "upi", "okbizaxis", "phonepe", "gpay", "freecharge", "airtel", "jio", "dbs", "sc",
            "unionbank", "canara", "barodampay", "aubank", "ezetap", "razorpay", "payu", "cashfree", "billdesk"}
_IFSC = re.compile(r"^[A-Za-z]{4}0[A-Za-z0-9]{6}$")
_CARD = re.compile(r"\b\d{4}[Xx*]+\d{4}\b")


def _is_reference(part: str) -> bool:
    """ID-looking parts: 412345678901, HDFCN52026031412345, HDFCR52026 (a long single token mixing letters and digits)."""
    mixed = " " not in part and len(part) >= 9 and any(c.isdigit() for c in part) and any(c.isalpha() for c in part)
    return sum(c.isdigit() for c in part) >= 6 or bool(_IFSC.match(part)) or mixed


def _titled(text: str) -> str:
    text = re.sub(r"\s+", " ", text).strip(" -/.:,")
    return text.title() if text.isupper() else text


def _from_vpa(part: str) -> str:
    """'rohan.sharma@oksbi' -> 'Rohan Sharma', '9876543210@ybl' -> '9876543210'."""
    local = part.split("@", 1)[0]
    return re.sub(r"[._]+", " ", local).strip().title()


def clean_merchant(narration: str) -> str:
    """Pull the merchant out of a UPI / IMPS / NEFT / RTGS / card narration. Plain names are only tidied."""
    s = _CARD.sub("", narration or "")                       # masked card number: 4567XXXXXXXX1234
    s = re.sub(r"\s+", " ", s).strip()
    if re.match(r"^(atm|nfs|cash)\s*(wdl|withdrawal|cash)?\b", s, re.I) and not _RAIL.match(s):
        return "Cash withdrawal"
    if not _RAIL.match(s):
        return _titled(s)[:120] or "Unknown"
    s = re.sub(r"^\s*(POS|ECOM)\b", "", s, flags=re.I).strip()
    if not re.match(r"^(upi|imps|neft|rtgs|nach|ach|ecs|mmt|inf|ift|bil|billpay)\b", s, re.I):
        return _titled(s)[:120] or "Unknown"                 # card terminal text such as "POS AMAZON PAY"

    vpa = None
    for part in re.split(r"[/\-|:]", s):
        part = part.strip()
        if not part:
            continue
        if "@" in part:
            vpa = vpa or part
            continue
        low = part.casefold()
        if low in _FILLER or low in _HANDLES or _is_reference(part) or not re.search(r"[A-Za-z]{2}", part):
            continue
        return _titled(part)[:120]
    return (_from_vpa(vpa)[:120] if vpa else "") or _titled(s)[:120] or "Unknown"


# ---- the built-in list --------------------------------------------------------

def tokens(text: str) -> list[str]:
    """Lower-case alphanumeric words: "Cult.fit" -> ['cult', 'fit'], "Hola!" -> ['hola']."""
    return re.findall(r"[a-z0-9]+", (text or "").casefold())


class DictionaryMatcher:
    """Matches built-in merchant names inside a transaction's name as WHOLE WORDS.

    "Ola" matches "Ola Cabs" and "UPI-OLA-ola@axis" but not "Hola" or "Gola". An entry made of several words
    ("Swiggy Instamart") must appear as those words next to each other. The entry with the most words wins."""

    def __init__(self, dictionary: dict[str, list[str]] = DICTIONARY):
        self._by_first: dict[str, list[tuple[tuple[str, ...], str, str]]] = {}
        for key, entries in dictionary.items():
            for entry in entries:
                names = [n.strip() for n in entry.split("|") if n.strip()]
                for alias in names:
                    toks = tuple(tokens(alias))
                    if toks:
                        self._by_first.setdefault(toks[0], []).append((toks, key, names[0]))
        for lst in self._by_first.values():
            lst.sort(key=lambda e: -len(e[0]))               # longest entry first

    def match(self, *texts: str | None) -> tuple[str, str] | None:
        """(category key, entry name) for the best match across the given names, or None."""
        best: tuple[int, str, str] | None = None
        for text in texts:
            toks = tokens(text or "")
            for i, tok in enumerate(toks):
                for ptoks, key, name in self._by_first.get(tok, ()):
                    if tuple(toks[i:i + len(ptoks)]) == ptoks and (best is None or len(ptoks) > best[0]):
                        best = (len(ptoks), key, name)
        return (best[1], best[2]) if best else None


MATCHER = DictionaryMatcher()


# ---- payments to people --------------------------------------------------------

_BUSINESS_WORDS = set("""store stores mart traders trading enterprises enterprise services service pharmacy medical cafe restaurant hotel
bakery foods food kitchen tea stall auto garage salon school college hospital clinic labs lab ltd pvt limited llp inc company co
bank general supermarket fresh mobile mobiles electronics hardware fuel petrol pump gas travels tours agency shop centre center
studio gym fitness laundry cleaners juice dhaba sweets bakers provision kirana vegetables fruits dairy milk books stationery
optical opticals jewellers jewelers motors cabs cab taxi rides recharge broadband electricity board technologies solutions
systems india online payments pay rent landlord society maintenance club bar pub house tailor""".split())


def looks_like_person(name: str, payment_method: str = "upi", upi_id: str | None = None) -> bool:
    """A hint that this payee is an individual, not a business. Only UPI/bank transfers can be person-to-person.

    It never assigns a category. The Untagged inbox uses it to say "looks like a person" and offer one tap to
    file the payee under Transfers. Known merchants (the built-in list) are never people."""
    if payment_method not in ("upi", "bank_transfer"):
        return False
    if MATCHER.match(name):
        return False
    if upi_id and re.match(r"^\d{10}@", upi_id):
        return True
    words = tokens(name)
    if not words or len(words) > 4:
        return False
    if any(w in _BUSINESS_WORDS or any(c.isdigit() for c in w) for w in words):
        return False
    if "@" in name:
        return not _is_reference(name.split("@", 1)[0])
    return all(len(w) >= 2 for w in words)

app/merchant_service.py:
"""Correcting a merchant name or category, one transaction or every transaction from that merchant.

Safe by design:
* `merchant_raw` (the bank's own text) is never touched, and `merchant_clean` keeps Paisa's first tidy-up, so
  "reset to original" always has something to go back to.
* Nothing changes until you have seen the EXACT count and a sample of affected transactions (`plan`), then confirmed.
* Every bulk change is written to `change_log` with before/after values, so it can be undone.
* "Apply to all" never overrides a tag you picked by hand on ANOTHER transaction unless you say so.
* Remembering as a rule never creates a duplicate rule; remembering a name never creates a duplicate rename.
* TrustLedger re-runs afterwards, because duplicate detection compares merchant names.
"""
import json
import sqlite3

from . import tagging, trust_service
from .autotag import match_rule


class CorrectionError(Exception):
    def __init__(self, message: str, status: int = 400):
        super().__init__(message)
        self.status = status


def _key(text: str | None) -> str:
    return (text or "").strip().casefold()


def _row(conn: sqlite3.Connection, tx_id: int) -> sqlite3.Row:
    r = conn.execute("SELECT * FROM transactions WHERE id = ?", (tx_id,)).fetchone()
    if not r:
        raise CorrectionError("Transaction not found", 404)
    return r


def _tag_name(conn: sqlite3.Connection, tag_id: int | None) -> str:
    if tag_id is None:
        return "Untagged"
    r = conn.execute("SELECT name FROM tags WHERE id = ?", (tag_id,)).fetchone()
    return r["name"] if r else "Untagged"


def _state(r: sqlite3.Row) -> dict:
    return {"payee": r["payee"], "tag_id": r["tag_id"], "tag_source": r["tag_source"], "tag_detail": r["tag_detail"]}


def plan(conn: sqlite3.Connection, tx_id: int, *, name: str | None = None, change_tag: bool = False,
         tag_id: int | None = None, apply_to_all: bool = False, remember: bool = False,
         include_hand_tagged: bool = False) -> dict:
    """Work out EXACTLY what would change, without changing anything. `apply` runs this same plan."""
    tapped = _row(conn, tx_id)
    name = name.strip()[:120] if name else None
    if name is not None and not name:
        raise CorrectionError("The merchant name can't be blank")
    if not name and not change_tag:
        raise CorrectionError("Choose a new name or a new category")
    if change_tag and tag_id is not None and not conn.execute("SELECT 1 FROM tags WHERE id = ?", (tag_id,)).fetchone():
        raise CorrectionError(f"Tag {tag_id} does not exist")

    merchant = tapped["merchant_clean"] or tapped["payee"]
    if apply_to_all:
        targets = conn.execute("SELECT * FROM transactions WHERE merged_into_id IS NULL AND lower(trim(coalesce(merchant_clean, payee))) = ?"
                               " ORDER BY date_time DESC, id DESC", (_key(merchant),)).fetchall()
        if tapped["id"] not in [t["id"] for t in targets]:
            targets = [tapped, *targets]
    else:
        targets = [tapped]

    rows, hand_left_alone = [], 0
    for t in targets:
        new_payee = name or t["payee"]
        new_tag, src, detail = t["tag_id"], t["tag_source"], t["tag_detail"]
        if change_tag:
            if t["id"] != tx_id and t["tag_source"] == "user" and t["tag_id"] != tag_id and not include_hand_tagged:
                hand_left_alone += 1                      # someone (you) chose this tag on purpose: leave it
            else:
                new_tag = tag_id
                src, detail = ("user", "Correction") if tag_id is not None else (None, None)
        before = _state(t)
        after = {"payee": new_payee, "tag_id": new_tag, "tag_source": src, "tag_detail": detail}
        if before != after:
            rows.append({"id": t["id"], "date_time": t["date_time"], "amount": t["amount"] / 100, "type": t["type"],
                         "before": before, "after": after,
                         "before_tag": _tag_name(conn, t["tag_id"]), "after_tag": _tag_name(conn, new_tag)})

    # Remembering: a rule for the ORIGINAL merchant (so future imports match), and/or the chosen name.
    rule = rename = None
    if remember and change_tag and tag_id is not None:
        same = conn.execute("SELECT id, tag_id FROM tag_rules WHERE pattern = ? COLLATE NOCASE", (merchant,)).fetchone()
        rules = [(r["pattern"], r["tag_id"]) for r in conn.execute("SELECT pattern, tag_id FROM tag_rules ORDER BY priority DESC, id DESC")]
        hit = match_rule(merchant, rules)
        if same and same["tag_id"] == tag_id:
            rule = {"action": "exists", "pattern": merchant, "note": f"A rule for “{merchant}” already exists, so no new rule is made."}
        elif same:
            rule = {"action": "update", "pattern": merchant, "note": f"Your rule “{merchant}” currently tags as {_tag_name(conn, same['tag_id'])}; "
                                                                      f"it will change to {_tag_name(conn, tag_id)}."}
        elif hit and hit[0] == tag_id:
            rule = {"action": "covered", "pattern": merchant, "note": f"Your rule “{hit[1]}” already gives this tag, so no new rule is made."}
        else:
            rule = {"action": "create", "pattern": merchant, "note": f"A new rule will tag future “{merchant}” payments as {_tag_name(conn, tag_id)}."}
    if remember and name and name != merchant:
        have = conn.execute("SELECT name FROM merchant_renames WHERE key = ?", (_key(merchant),)).fetchone()
        rename = ({"action": "exists", "note": f"Future “{merchant}” payments are already shown as “{name}”."} if have and have["name"] == name
                  else {"action": "update" if have else "create",
                        "note": f"Future “{merchant}” payments will be shown as “{name}”."})
    return {"merchant": merchant, "matching": len(targets), "will_change": len(rows), "hand_tagged_left_alone": hand_left_alone,
            "sample": rows[:8], "rows": rows, "rule": rule, "rename": rename, "name": name,
            "change_tag": change_tag, "tag_id": tag_id}


def preview(conn: sqlite3.Connection, tx_id: int, **kw) -> dict:
    p = plan(conn, tx_id, **kw)
    return {k: v for k, v in p.items() if k != "rows"}


def apply(conn: sqlite3.Connection, tx_id: int, **kw) -> dict:
    """Make the planned changes, log them for Undo, and re-run TrustLedger."""
    p = plan(conn, tx_id, **kw)
    if not p["rows"] and not (p["rule"] and p["rule"]["action"] in ("create", "update")) \
            and not (p["rename"] and p["rename"]["action"] in ("create", "update")):
        raise CorrectionError("Nothing would change")
    for r in p["rows"]:
        a = r["after"]
        conn.execute("UPDATE transactions SET payee = ?, tag_id = ?, tag_source = ?, tag_detail = ? WHERE id = ?",
                     (a["payee"], a["tag_id"], a["tag_source"], a["tag_detail"], r["id"]))
    payload = {"rows": [{"id": r["id"], "before": r["before"], "after": r["after"]} for r in p["rows"]]}
    merchant = p["merchant"]
    if p["rule"] and p["rule"]["action"] in ("create", "update"):
        res = tagging.add_rule(conn, merchant, p["tag_id"], update_if_conflict=True)
        payload["rule"] = {"status": res["status"], "rule_id": res["rule_id"], "old_tag_id": res.get("old_tag_id")}
    if p["rename"] and p["rename"]["action"] in ("create", "update"):
        old = conn.execute("SELECT name FROM merchant_renames WHERE key = ?", (_key(merchant),)).fetchone()
        conn.execute("INSERT INTO merchant_renames (key, name) VALUES (?, ?) ON CONFLICT(key) DO UPDATE SET name = excluded.name",
                     (_key(merchant), p["name"]))
        payload["rename"] = {"key": _key(merchant), "old": old["name"] if old else None}
    bits = ([f"renamed to “{p['name']}”"] if p["name"] else []) + \
           ([f"category set to {_tag_name(conn, p['tag_id'])}"] if p["change_tag"] else [])
    lead = " and ".join(bits)
    desc = f"{lead[:1].upper()}{lead[1:]} for {len(p['rows'])} transaction{'s' if len(p['rows']) != 1 else ''} from “{merchant}”"
    change_id = conn.execute("INSERT INTO change_log (kind, description, payload) VALUES ('correction', ?, ?)",
                             (desc, json.dumps(payload))).lastrowid
    conn.commit()
    trust_service.refresh(conn, "You corrected a merchant")
    return {"change_id": change_id, "changed": len(p["rows"]), "description": desc,
            "rule": p["rule"], "rename": p["rename"], "hand_tagged_left_alone": p["hand_tagged_left_alone"]}


def reset_merchant(conn: sqlite3.Connection, tx_id: int) -> dict:
    """Put this transaction's name back to Paisa's original tidy-up (merchant_clean). Logged, so undoable."""
    t = _row(conn, tx_id)
    original = t["merchant_clean"] or t["payee"]
    if t["payee"] == original:
        raise CorrectionError("This transaction already shows its original name")
    before, after = _state(t), {**_state(t), "payee": original}
    conn.execute("UPDATE transactions SET payee = ? WHERE id = ?", (original, tx_id))
    desc = f"Reset the name to its original “{original}”"
    cid = conn.execute("INSERT INTO change_log (kind, description, payload) VALUES ('reset', ?, ?)",
                       (desc, json.dumps({"rows": [{"id": tx_id, "before": before, "after": after}]}))).lastrowid
    conn.commit()
    trust_service.refresh(conn, "You reset a merchant name")
    return {"change_id": cid, "description": desc}


def undo(conn: sqlite3.Connection, change_id: int) -> dict:
    """Reverse a logged change. A transaction you edited again since is left alone and counted as skipped."""
    c = conn.execute("SELECT * FROM change_log WHERE id = ?", (change_id,)).fetchone()
    if not c:
        raise CorrectionError("Change not found", 404)
    if c["undone"]:
        raise CorrectionError("This change was already undone")
    payload = json.loads(c["payload"])
    restored = skipped = 0
    for r in payload["rows"]:
        cur = conn.execute("SELECT payee, tag_id, tag_source, tag_detail FROM transactions WHERE id = ?", (r["id"],)).fetchone()
        if cur is None or dict(cur) != r["after"]:
            skipped += 1
            continue
        b = r["before"]
        conn.execute("UPDATE transactions SET payee = ?, tag_id = ?, tag_source = ?, tag_detail = ? WHERE id = ?",
                     (b["payee"], b["tag_id"], b["tag_source"], b["tag_detail"], r["id"]))
        restored += 1
    rule = payload.get("rule")
    if rule:
        if rule["status"] == "created" and rule["rule_id"]:
            conn.execute("DELETE FROM tag_rules WHERE id = ?", (rule["rule_id"],))
        elif rule["status"] == "updated" and rule["rule_id"]:
            conn.execute("UPDATE tag_rules SET tag_id = ? WHERE id = ?", (rule["old_tag_id"], rule["rule_id"]))
    rn = payload.get("rename")
    if rn:
        if rn["old"] is None:
            conn.execute("DELETE FROM merchant_renames WHERE key = ?", (rn["key"],))
        else:
            conn.execute("UPDATE merchant_renames SET name = ? WHERE key = ?", (rn["old"], rn["key"]))
    conn.execute("UPDATE change_log SET undone = 1 WHERE id = ?", (change_id,))
    conn.commit()
    trust_service.refresh(conn, "You undid a correction")
    return {"restored": restored, "skipped": skipped}


def list_changes(conn: sqlite3.Connection, limit: int = 10) -> list[dict]:
    return [{"id": r["id"], "at": r["at"], "kind": r["kind"], "description": r["description"], "undone": bool(r["undone"]),
             "rows": len(json.loads(r["payload"])["rows"])}
            for r in conn.execute("SELECT * FROM change_log ORDER BY id DESC LIMIT ?", (limit,))]

