"""Request bodies (Pydantic validates them before our code runs)."""
from datetime import datetime
from typing import Literal

from pydantic import BaseModel, Field, field_validator

PaymentMethod = Literal["upi", "card", "cash", "bank_transfer", "other"]


class TagIn(BaseModel):
    name: str = Field(min_length=1, max_length=40)
    color: str = Field(default="#6366f1", pattern=r"^#[0-9a-fA-F]{6}$")

    @field_validator("name")
    @classmethod
    def strip_name(cls, v: str) -> str:
        v = v.strip()
        if not v:
            raise ValueError("name cannot be blank")
        return v


class RuleIn(BaseModel):
    pattern: str = Field(min_length=1, max_length=80)
    tag_id: int
    priority: int = 0

    @field_validator("pattern")
    @classmethod
    def strip_pattern(cls, v: str) -> str:
        v = v.strip()
        if not v:
            raise ValueError("pattern cannot be blank")
        return v


class TransactionIn(BaseModel):
    date_time: datetime | None = None  # defaults to "now" for Quick Add
    amount: float = Field(gt=0, description="Rupees, e.g. 249.50")
    type: Literal["debit", "credit"] = "debit"
    payee: str = Field(min_length=1, max_length=120)
    payment_method: PaymentMethod = "upi"
    tag_id: int | None = None  # None -> auto-tag rules decide (else stays untagged)
    note: str = Field(default="", max_length=500)
    status: Literal["completed", "pending"] = "completed"
    upi_id: str | None = Field(default=None, max_length=100)

    @field_validator("payee")
    @classmethod
    def strip_payee(cls, v: str) -> str:
        v = v.strip()
        if not v:
            raise ValueError("payee cannot be blank")
        return v

app/passcode.py:
"""Optional app passcode. A SCREEN LOCK, not encryption: it keeps someone who picks up your unlocked phone or laptop out of the app screens.
Anyone who can open the database file (or call the local API) can still read your data. There is no recovery: if you forget it, the only way
back in is erasing the data (typed confirmation) or restoring a backup.

The passcode is stored as a salted PBKDF2-SHA256 hash (hashlib, standard library; works unchanged in the browser build). Wrong tries are
counted by the app itself: after 3 in a row the next try must wait 30 s, doubling each time up to 1 hour.
"""
import hashlib
import hmac
import json
import os
import sqlite3
import time

ITERATIONS = 120_000
MIN_LENGTH = 4
FREE_TRIES = 3
BASE_DELAY, MAX_DELAY = 30, 3600
KEY = "passcode"


class PasscodeError(Exception):
    def __init__(self, message: str, status: int = 400, wait: int = 0):
        super().__init__(message)
        self.status, self.wait = status, wait


def _pbkdf2_py(pw: bytes, salt: bytes, iterations: int) -> bytes:
    """PBKDF2-HMAC-SHA256 in plain Python, same output as hashlib.pbkdf2_hmac. Used where hashlib lacks it (the in-browser Pyodide build)."""
    prf = hmac.new(pw, digestmod=hashlib.sha256)
    h = prf.copy()
    h.update(salt + (1).to_bytes(4, "big"))
    u = h.digest()
    t = int.from_bytes(u, "big")
    for _ in range(iterations - 1):
        h = prf.copy()
        h.update(u)
        u = h.digest()
        t ^= int.from_bytes(u, "big")
    return t.to_bytes(32, "big")


def _hash(pw: str, salt: bytes, iterations: int) -> str:
    raw = pw.encode("utf-8")
    if hasattr(hashlib, "pbkdf2_hmac"):
        return hashlib.pbkdf2_hmac("sha256", raw, salt, iterations).hex()
    return _pbkdf2_py(raw, salt, iterations).hex()


def delay_for(fails: int) -> int:
    """Seconds to wait before the next try after `fails` wrong tries in a row."""
    if fails < FREE_TRIES:
        return 0
    return min(MAX_DELAY, BASE_DELAY * 2 ** (fails - FREE_TRIES))


def _load(conn: sqlite3.Connection) -> dict | None:
    r = conn.execute("SELECT value FROM meta WHERE key = ?", (KEY,)).fetchone()
    return json.loads(r[0]) if r else None


def _save(conn: sqlite3.Connection, d: dict | None) -> None:
    if d is None:
        conn.execute("DELETE FROM meta WHERE key = ?", (KEY,))
    else:
        conn.execute("INSERT INTO meta (key, value) VALUES (?, ?) ON CONFLICT(key) DO UPDATE SET value = excluded.value", (KEY, json.dumps(d)))
    conn.commit()


def status(conn: sqlite3.Connection, now: float | None = None) -> dict:
    d = _load(conn)
    now = time.time() if now is None else now
    wait = max(0, int(d["locked_until"] - now + 0.999)) if d else 0
    return {"enabled": d is not None, "wait_seconds": wait, "failed_tries": d["fails"] if d else 0, "min_length": MIN_LENGTH,
            "is_encryption": False, "recoverable": False}


def check_new(pw: str) -> None:
    if not isinstance(pw, str) or len(pw) < MIN_LENGTH:
        raise PasscodeError(f"Use at least {MIN_LENGTH} characters.")
    if len(pw) > 128:
        raise PasscodeError("That passcode is too long.")


def verify(conn: sqlite3.Connection, pw: str, now: float | None = None) -> bool:
    """True if right. Raises PasscodeError (429) while locked out. A wrong try is counted and lengthens the wait."""
    d = _load(conn)
    if d is None:
        return True
    now = time.time() if now is None else now
    if now < d["locked_until"]:
        wait = int(d["locked_until"] - now + 0.999)
        raise PasscodeError(f"Too many wrong tries. Wait {wait} seconds.", 429, wait)
    ok = isinstance(pw, str) and hmac.compare_digest(_hash(pw, bytes.fromhex(d["salt"]), d["iterations"]), d["hash"])
    if ok:
        if d["fails"]:
            d.update(fails=0, locked_until=0)
            _save(conn, d)
        return True
    d["fails"] += 1
    d["locked_until"] = now + delay_for(d["fails"])
    _save(conn, d)
    return False


def set_passcode(conn: sqlite3.Connection, new: str, current: str | None = None, now: float | None = None) -> None:
    check_new(new)
    if _load(conn) is not None and not verify(conn, current or "", now):
        raise PasscodeError("The current passcode is not right.", 403)
    salt = os.urandom(16)
    _save(conn, {"salt": salt.hex(), "hash": _hash(new, salt, ITERATIONS), "iterations": ITERATIONS, "fails": 0, "locked_until": 0})


def remove(conn: sqlite3.Connection, current: str, now: float | None = None) -> None:
    if _load(conn) is None:
        return
    if not verify(conn, current or "", now):
        raise PasscodeError("The passcode is not right.", 403)
    _save(conn, None)


def clear(conn: sqlite3.Connection) -> None:
    """Used only by 'erase everything'."""
    _save(conn, None)

app/reconcile.py:
"""Reconciliation: pure functions that compare sources and check balance trails. No database, integer paise only.

Wording matters: nothing here knows your bank balance. Every balance statement is "according to this imported file";
an unmatched row is "not found in" the other source, never "lost" or "missing money" as a verdict.

* `compare(a, b)`        match two sources over the dates BOTH cover. Reference ID first, else direction + amount +
                         date window + similar merchant (never amount alone). Each row matches at most once.
                         Results: matched, only in A, only in B, ambiguous (for the user to decide), outside the dates.
* `balance_trail(rows)`  check balance after each row = previous balance + movement. Reports where it first stops adding
                         up, the gap and the date range; copes with ascending/descending files and date-only same-day rows.
* `explain_gap(...)`     labelled possibilities for a gap, from ledger entries not in the statement (capped search).
* `opening_check(...)`   compare the balance you entered with an imported balance near the same date.
"""
from dataclasses import dataclass, field
from datetime import date, timedelta
from itertools import combinations

from .trustledger import _norm, _sim, inr

DATE_WINDOW_DAYS = 2        # rows match if their dates are at most this far apart (statements often carry only a date)
MIN_MERCHANT_SIMILARITY = 0.6
GAP_SEARCH_CAP = 20_000     # most combinations explain_gap will try
GAP_CANDIDATE_LIMIT = 25    # most ledger entries considered for a combination
NOT_MOVING = ("failed", "reversed", "pending")      # statuses assumed not to change a statement's balance


@dataclass(frozen=True)
class Row:
    """One transaction as seen by a reconciliation. `order` is its position in its source (file order)."""
    id: int
    day: date
    amount: int
    type: str                      # debit | credit
    payee: str
    reference: str | None = None
    order: int = 0
    has_time: bool = False         # False when the source only gave a date (midnight)
    balance: int | None = None     # balance printed after this row, according to the file
    status: str = "success"        # success | pending | failed | reversed
    clean: str | None = None
    batch: int | None = None

    @property
    def names(self) -> frozenset[str]:
        return frozenset(n for n in (_norm(self.payee), _norm(self.clean or "")) if n)

    @property
    def signed(self) -> int:
        return self.amount if self.type == "credit" else -self.amount

    @property
    def moves(self) -> int:
        """How much this row moves a statement balance (0 for failed, reversed and pending rows)."""
        return 0 if self.status in NOT_MOVING else self.signed


# ---- comparing two sources ------------------------------------------------------------------------

@dataclass
class Pair:
    a: int
    b: int
    how: str                       # reference | details | identical-in-order | you
    note: str = ""


@dataclass
class Unmatched:
    id: int
    note: str = ""


@dataclass
class Ambiguous:
    a_ids: list[int]
    b_ids: list[int]
    reason: str


@dataclass
class CompareResult:
    matched: list[Pair] = field(default_factory=list)
    only_a: list[Unmatched] = field(default_factory=list)
    only_b: list[Unmatched] = field(default_factory=list)
    ambiguous: list[Ambiguous] = field(default_factory=list)
    outside_a: list[int] = field(default_factory=list)       # A rows outside the dates B covers
    outside_b: list[int] = field(default_factory=list)
    range_a: tuple[date, date] | None = None
    range_b: tuple[date, date] | None = None
    overlap: tuple[date, date] | None = None
    not_compared: int = 0                                     # failed/reversed rows left out
    notes: list[str] = field(default_factory=list)


def _span(rows: list[Row]) -> tuple[date, date] | None:
    return (min(r.day for r in rows), max(r.day for r in rows)) if rows else None


def _candidate(a: Row, b: Row) -> bool:
    """Could these two rows be the same payment? Never on amount alone."""
    if a.type != b.type or a.amount != b.amount:
        return False
    if a.reference and b.reference:
        return False                                          # two different references = two different payments
    if abs((a.day - b.day).days) > DATE_WINDOW_DAYS:
        return False
    return _sim(a.names, b.names) >= MIN_MERCHANT_SIMILARITY


def compare(a_rows: list[Row], b_rows: list[Row], *, forced: set[tuple[int, int]] = frozenset(),
            forbidden: set[tuple[int, int]] = frozenset()) -> CompareResult:
    """Match two sources over the date range both cover. `forced` / `forbidden` are the user's own decisions
    ((a id, b id) pairs): a forced pair is matched whatever the data says, a forbidden pair is never matched."""
    res = CompareResult()
    keep = lambda r: r.status in ("success", "pending")        # noqa: E731
    res.not_compared = sum(1 for r in a_rows + b_rows if not keep(r))
    A = sorted((r for r in a_rows if keep(r)), key=lambda r: (r.day, r.order, r.id))
    B = sorted((r for r in b_rows if keep(r)), key=lambda r: (r.day, r.order, r.id))
    res.range_a, res.range_b = _span(A), _span(B)
    if not A or not B:
        res.notes.append("One of the sources has no rows to compare.")
        res.outside_a, res.outside_b = [r.id for r in A], [r.id for r in B]
        return res
    lo, hi = max(res.range_a[0], res.range_b[0]), min(res.range_a[1], res.range_b[1])
    if lo > hi:
        res.notes.append("These two sources do not cover any of the same dates, so there is nothing to compare.")
        res.outside_a, res.outside_b = [r.id for r in A], [r.id for r in B]
        return res
    res.overlap = (lo, hi)
    inside = lambda r: lo <= r.day <= hi                      # noqa: E731
    poolA = [r for r in A if inside(r)]
    poolB = [r for r in B if inside(r)]
    res.outside_a = [r.id for r in A if not inside(r)]
    res.outside_b = [r.id for r in B if not inside(r)]
    byA, byB = {r.id: r for r in A}, {r.id: r for r in B}

    # 0. the user's own decisions
    for ai, bi in sorted(forced):
        if ai in byA and bi in byB and byA[ai] in poolA + A and byB[bi] in poolB + B:
            res.matched.append(Pair(ai, bi, "you", "You said these are the same payment."))
            poolA = [r for r in poolA if r.id != ai]
            poolB = [r for r in poolB if r.id != bi]
            res.outside_a = [i for i in res.outside_a if i != ai]
            res.outside_b = [i for i in res.outside_b if i != bi]

    # 1. reference ID first
    refs_a, refs_b = {}, {}
    for r in poolA:
        if r.reference:
            refs_a.setdefault(r.reference, []).append(r)
    for r in poolB:
        if r.reference:
            refs_b.setdefault(r.reference, []).append(r)
    taken_a, taken_b, amb_refs = set(), set(), []
    for ref in sorted(set(refs_a) & set(refs_b)):
        la, lb = refs_a[ref], refs_b[ref]
        for ra, rb in zip(la, lb):
            if (ra.id, rb.id) in forbidden:
                continue
            taken_a.add(ra.id)
            taken_b.add(rb.id)
            if ra.type == rb.type and ra.amount == rb.amount:
                res.matched.append(Pair(ra.id, rb.id, "reference", f"Same reference ID {ref[:4]}…"))
            else:
                res.ambiguous.append(Ambiguous([ra.id], [rb.id], f"Same reference ID {ref[:4]}… but different "
                                               f"{'direction' if ra.type != rb.type else 'amount'} ({inr(ra.amount)} and {inr(rb.amount)})."))
        if len(la) != len(lb):                                # the extras share a reference that the other side used up
            extra = la[len(lb):] if len(la) > len(lb) else lb[len(la):]
            for r in extra:
                (taken_a if r in la else taken_b).add(r.id)
                note = f"Reference ID {ref[:4]}… appears more often here than in the other source."
                (res.only_a if r in la else res.only_b).append(Unmatched(r.id, note))
    poolA = [r for r in poolA if r.id not in taken_a]
    poolB = [r for r in poolB if r.id not in taken_b]

    # 2. no reference to go on: direction + amount + date window + similar merchant
    edges = {r.id: [b for b in poolB if _candidate(r, b) and (r.id, b.id) not in forbidden] for r in poolA}
    parent: dict[tuple[str, int], tuple[str, int]] = {}

    def find(x):
        parent.setdefault(x, x)
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    for ai, bs in edges.items():
        for b in bs:
            parent[find(("a", ai))] = find(("b", b.id))
    comps: dict[tuple[str, int], tuple[list[Row], list[Row]]] = {}
    for r in poolA:
        if edges[r.id]:
            comps.setdefault(find(("a", r.id)), ([], []))[0].append(r)
    for b in poolB:
        key = find(("b", b.id))
        if key in comps and any(b in edges[a.id] for a in comps[key][0]):
            comps[key][1].append(b)
    matched_a, matched_b = set(), set()
    for _, (ca, cb) in sorted(comps.items(), key=lambda kv: min(r.id for r in kv[1][0])):
        complete = all(set(x.id for x in edges[a.id]) == {b.id for b in cb} for a in ca)
        if len(ca) == 1 and len(cb) == 1:
            res.matched.append(Pair(ca[0].id, cb[0].id, "details", "Same direction and amount, close dates, similar merchant."))
            matched_a.add(ca[0].id)
            matched_b.add(cb[0].id)
        elif complete:
            # identical-looking purchases (e.g. two cups of chai): pair them in date/file order, each row at most once
            for ra, rb in zip(sorted(ca, key=lambda r: (r.day, r.order, r.id)), sorted(cb, key=lambda r: (r.day, r.order, r.id))):
                res.matched.append(Pair(ra.id, rb.id, "identical-in-order", "Identical purchases, paired in date and file order."))
                matched_a.add(ra.id)
                matched_b.add(rb.id)
            for r in ca:
                if r.id not in matched_a:
                    res.only_a.append(Unmatched(r.id, "Looks the same as a purchase that did match; it could be a genuine extra purchase."))
                    matched_a.add(r.id)
            for r in cb:
                if r.id not in matched_b:
                    res.only_b.append(Unmatched(r.id, "Looks the same as a purchase that did match; it could be a genuine extra purchase."))
                    matched_b.add(r.id)
        else:
            res.ambiguous.append(Ambiguous(sorted(r.id for r in ca), sorted(r.id for r in cb),
                                           "More than one row could be the match. Choose which belong together."))
            matched_a |= {r.id for r in ca}
            matched_b |= {r.id for r in cb}
    for r in poolA:
        if r.id not in matched_a:
            res.only_a.append(Unmatched(r.id, "Not found in the other source."))
    for r in poolB:
        if r.id not in matched_b:
            res.only_b.append(Unmatched(r.id, "Not found in the other source."))
    res.matched.sort(key=lambda p: (p.a, p.b))
    res.only_a.sort(key=lambda u: u.id)
    res.only_b.sort(key=lambda u: u.id)
    res.ambiguous.sort(key=lambda g: g.a_ids[0])
    return res


# ---- balance trail within one imported file ------------------------------------------------------------

@dataclass
class TrailRow:
    id: int
    day: date
    balance: int | None
    expected: int | None = None
    gap: int | None = None
    check: str = "unchecked"       # ok | gap | order | unchecked
    note: str = ""


@dataclass
class Gap:
    row_id: int
    prev_id: int
    amount: int                    # actual - expected, signed paise (negative: the balance fell by more than the rows explain)
    from_day: date
    to_day: date
    order_uncertain: bool = False


@dataclass
class Trail:
    rows: list[TrailRow]
    orientation: str               # ascending | descending | same-day
    gaps: list[Gap]
    checked: int
    unchecked: int
    notes: list[str]

    @property
    def clean(self) -> bool:
        return self.checked > 0 and not self.gaps


def _chain_possible(start: int, rows: list[Row]) -> bool:
    """Is there ANY order of these date-only rows in which each printed balance = previous balance + movement?"""
    if len(rows) > 8:
        return False
    def go(bal: int, left: tuple[Row, ...]) -> bool:
        if not left:
            return True
        for i, r in enumerate(left):
            if r.balance == bal + r.moves and go(r.balance, left[:i] + left[i + 1:]):
                return True
        return False
    return go(start, tuple(rows))


def balance_trail(rows_in_file_order: list[Row]) -> Trail:
    """Check opening + in - out = closing, row by row, according to this imported file.

    The file's order is used (a file listing newest first is reversed). Rows on the same day that only carry a date have
    no certain order: a gap there is reported only if NO ordering of that day's rows makes the balances add up."""
    rows = list(rows_in_file_order)
    notes: list[str] = []
    if not rows:
        return Trail([], "ascending", [], 0, 0, ["No rows."])
    first, last = rows[0].day, rows[-1].day
    orientation = "descending" if first > last else "ascending" if first < last else "same-day"
    if orientation == "descending":
        rows.reverse()
        notes.append("This file lists the newest rows first, so it was read from the bottom up.")
    if sum(1 for r in rows if r.balance is not None) < 2:
        return Trail([TrailRow(r.id, r.day, r.balance, check="unchecked", note="No balance to check") for r in rows], orientation, [], 0, len(rows),
                     notes + ["Fewer than two rows carry a balance, so this file's balances can't be checked."])

    # blocks: consecutive rows on one day with no times can't be put in a certain order
    blocks: list[list[Row]] = []
    for r in rows:
        if blocks and not r.has_time and not blocks[-1][0].has_time and blocks[-1][0].day == r.day:
            blocks[-1].append(r)
        else:
            blocks.append([r])
    out, gaps, checked, unchecked = [], [], 0, 0
    prev: Row | None = None
    ambiguous_days: list[date] = []
    for blk in blocks:
        def pairwise(start_row: Row | None, seq: list[Row]):
            """(row, expected, gap) for every row of `seq` that can be checked against the one before it."""
            res, p = [], start_row
            for r in seq:
                if p is not None and p.balance is not None and r.balance is not None:
                    exp = p.balance + r.moves
                    res.append((r, exp, r.balance - exp))
                else:
                    res.append((r, None, None))
                p = r
            return res
        results = pairwise(prev, blk)
        bad = [x for x in results if x[2]]
        order_note = ""
        if bad and len(blk) > 1 and all(r.balance is not None for r in blk):
            start = prev.balance if prev is not None and prev.balance is not None else blk[0].balance - blk[0].moves
            if _chain_possible(start, blk):
                bad = []
                order_note = f"Rows on {blk[0].day.isoformat()} have no times, so their order can't be confirmed; the balances add up in another order."
                ambiguous_days.append(blk[0].day)
                notes.append(order_note)
        for r, exp, gap in results:
            if exp is None:
                unchecked += 1
                out.append(TrailRow(r.id, r.day, r.balance, check="unchecked", note="No balance on this row or the one before" if r.balance is None or prev is not None else "First row: nothing before it to check against"))
            elif gap and (r, exp, gap) in bad:
                checked += 1
                uncertain = len(blk) > 1
                out.append(TrailRow(r.id, r.day, r.balance, exp, gap, "gap"))
                pr = next((q for q in blk if q is not r and q.order < r.order), None)
                gaps.append(Gap(r.id, (pr or prev or r).id, gap, (pr or prev or r).day, r.day, uncertain))
            else:
                checked += 1
                out.append(TrailRow(r.id, r.day, r.balance, exp, 0, "order" if order_note and gap else "ok", order_note if gap else ""))
        prev = blk[-1]
    if any(g.order_uncertain for g in gaps):
        notes.append("Some rows on the same day have no times, so the gap is worked out in file order.")
    return Trail(out, orientation, gaps, checked, unchecked, notes)


# ---- what might explain a gap -------------------------------------------------------------------------------

@dataclass
class Explanation:
    ids: list[int]
    total: int
    label: str


def explain_gap(gap: int, candidates: list[Row], *, cap: int = GAP_SEARCH_CAP) -> dict:
    """Possibilities for a gap: a ledger entry that is not in the statement whose amount equals the gap, or a small
    combination (2 or 3 entries) that sums to it. Direction counts: debits subtract, credits add. The search is
    capped; `cap_hit` says when it stopped early. These are possibilities to look at, never conclusions."""
    cands = candidates[:GAP_CANDIDATE_LIMIT]
    found: list[Explanation] = []
    checked = 0
    cap_hit = False
    for size in (1, 2, 3):
        for combo in combinations(cands, size):
            checked += 1
            if checked > cap:
                cap_hit = True
                break
            if sum(r.signed for r in combo) == gap:
                found.append(Explanation([r.id for r in combo], gap,
                             "One entry that is not in the statement matches the gap exactly" if size == 1 else
                             f"{size} entries that are not in the statement add up to the gap"))
        if cap_hit:
            break
    return {"explanations": found[:10], "checked": checked, "cap_hit": cap_hit, "candidates": len(cands),
            "truncated": len(candidates) > GAP_CANDIDATE_LIMIT}


# ---- the balance you entered vs an imported one ------------------------------------------------------------------

def opening_check(entered: int, entered_on: date, imported: dict | None, movements_after: int = 0) -> dict:
    """Compare your balance with the nearest imported balance on or before your date, rolled forward by other entries.
    `imported` = {"balance": paise, "day": date, "source": str}. The imported figure is "according to that file"."""
    if imported is None:
        return {"status": "no_import", "message": "No imported statement has a balance near your balance date, so there is nothing to compare."}
    at_date = imported["balance"] + movements_after
    diff = entered - at_date
    return {"status": "match" if diff == 0 else "mismatch", "entered_paise": entered, "entered_on": entered_on.isoformat(),
            "imported_paise": imported["balance"], "imported_day": imported["day"].isoformat(), "imported_source": imported["source"],
            "rolled_forward_paise": movements_after, "imported_at_date_paise": at_date, "difference_paise": diff,
            "days_apart": (entered_on - imported["day"]).days}

app/recurring.py:
"""Recurring payment detection from your own history. PURE FUNCTIONS: no database, integer paise.

A series needs at least 3 payments to the same merchant (same direction) at a roughly regular interval and similar amounts.
The tolerances are stated, not hidden:

    weekly 7 days +-1 · fortnightly 14 +-2 · monthly 30 +-4 (26 to 35 days, so every month length fits) ·
    quarterly 91 +-8 · yearly 365 +-15

At least 80% of the gaps must fit (a series of 4+ gaps may have one odd gap; a skipped cycle, a gap of about twice the
interval, fits too and is noted). Amounts: at least 60% within 10% of the median, or the series splits into at most two price
levels (a price change). A merchant whose amounts vary a lot (food delivery, say) is never called recurring.

Nothing is created from a detection. The service only offers it; "Confirm as recurring" is the user's.
"""
import calendar
from dataclasses import dataclass, field
from datetime import date, timedelta
from statistics import median

# name -> (nominal days, tolerance days)
CADENCES: dict[str, tuple[int, int]] = {"weekly": (7, 1), "fortnightly": (14, 2), "monthly": (30, 4), "quarterly": (91, 8), "yearly": (365, 15)}
CADENCE_WORDS = {"weekly": "week", "fortnightly": "two weeks", "monthly": "month", "quarterly": "three months", "yearly": "year"}
MIN_OCCURRENCES = 3
AMOUNT_TOLERANCE_PCT = 10
PRICE_CHANGE_PCT = 5
ENDED_AFTER_CYCLES = 2


@dataclass(frozen=True)
class Occ:
    id: int
    day: date
    amount: int          # paise


@dataclass
class Series:
    merchant: str
    direction: str                      # debit | credit
    cadence: str
    occurrences: list[Occ]
    typical: int                        # paise: the latest price level
    last_day: date
    next_expected: date
    confidence: str                     # High | Medium | Low
    reasons: list[str]
    gaps: list[int]
    missed_cycles: int = 0
    price_change: dict | None = None
    possibly_ended: dict | None = None
    notes: list[str] = field(default_factory=list)


def _similar(a: int, b: int, pct: int = AMOUNT_TOLERANCE_PCT) -> bool:
    return abs(a - b) <= max(b * pct // 100, 1000)         # within pct%, or ₹10


def _add_months(d: date, months: int, dom: int | None = None) -> date:
    y, m = divmod(d.month - 1 + months, 12)
    y, m = d.year + y, m + 1
    return date(y, m, min(dom or d.day, calendar.monthrange(y, m)[1]))


def next_after(cadence: str, last: date, dom: int) -> date:
    """The next expected date after `last`. Monthly and longer keep the usual day of the month (clamped in short months)."""
    if cadence == "weekly":
        return last + timedelta(days=7)
    if cadence == "fortnightly":
        return last + timedelta(days=14)
    if cadence == "monthly":
        return _add_months(last, 1, dom)
    if cadence == "quarterly":
        return _add_months(last, 3, dom)
    return _add_months(last, 12, dom)


def _runs(amounts: list[int]) -> list[list[int]]:
    """Runs of consecutive payments whose amounts stay within the tolerance of the previous one (price levels)."""
    runs = [[amounts[0]]]
    for a in amounts[1:]:
        if _similar(a, runs[-1][-1]):
            runs[-1].append(a)
        else:
            runs.append([a])
    return runs


def detect(merchant: str, direction: str, occs: list[Occ], today: date) -> Series | None:
    """The best-fitting regular series for one merchant, or None. Several payments on one day count once."""
    by_day: dict[date, Occ] = {}
    for o in sorted(occs, key=lambda o: (o.day, o.id)):
        by_day.setdefault(o.day, o)
    series = list(by_day.values())
    if len(series) < MIN_OCCURRENCES:
        return None
    gaps = [(b.day - a.day).days for a, b in zip(series, series[1:])]

    best = None
    for name, (nominal, tol) in CADENCES.items():
        exact = sum(1 for g in gaps if abs(g - nominal) <= tol)
        missed = sum(1 for g in gaps if abs(g - nominal) > tol and any(abs(g - k * nominal) <= tol * k for k in (2, 3)))
        if missed > 1 or exact < 2:       # one skipped cycle is fine in an otherwise regular series; more means a different rhythm
            missed = 0
        score = (exact + missed, exact, nominal)
        if best is None or score > best[0]:
            best = (score, name, exact, missed)
    (fits, exact, _), cadence, exact, missed = best
    bad = len(gaps) - fits
    if not (bad == 0 or (len(gaps) >= 4 and bad <= max(1, len(gaps) // 5))):
        return None

    amounts = [o.amount for o in series]
    med = int(median(amounts))
    runs = _runs(amounts)
    within = sum(1 for a in amounts if _similar(a, med))
    if within / len(amounts) < 0.6 and len(runs) > 2:
        return None

    last = series[-1].day
    dom = int(median(o.day.day for o in series))
    typical = int(median(runs[-1]))
    price = None
    if len(runs) >= 2:
        before, now = int(median(runs[-2])), typical
        if abs(now - before) > max(before * PRICE_CHANGE_PCT // 100, 1000):
            first_new = series[len(amounts) - len(runs[-1])]
            price = {"from_paise": before, "to_paise": now, "on": first_new.day.isoformat(), "pct": round((now - before) / before * 100, 1)}
    nominal = CADENCES[cadence][0]
    cycles_ago = (today - last).days // nominal
    ended = {"cycles": cycles_ago, "last": last.isoformat()} if cycles_ago >= ENDED_AFTER_CYCLES else None

    notes = []
    if missed:
        notes.append(f"{missed} cycle{'s' if missed != 1 else ''} seem{'s' if missed == 1 else ''} to have been skipped (a gap of about twice the usual).")
    reasons = [f"{len(series)} payments, about once every {CADENCE_WORDS[cadence]}.",
               f"{fits} of {len(gaps)} gaps between payments fit that rhythm (allowed: {nominal} days, give or take {CADENCES[cadence][1]})."]
    stable = len(runs) == 1 and within == len(amounts)
    reasons.append("The amount is the same each time, within 10%." if stable else
                   "The amount changed from one level to another." if len(runs) == 2 else "Most amounts are within 10% of the usual.")
    reasons += notes
    if len(series) >= 6 and bad == 0 and stable and not missed:
        level = "High"
    elif len(series) == MIN_OCCURRENCES:
        level = "Low"
        reasons.append("Only 3 payments so far: a pattern is possible but not certain.")
    else:
        level = "Medium"
    return Series(merchant, direction, cadence, series, typical, last, next_after(cadence, last, dom), level, reasons, gaps, missed, price, ended, notes)

app/recurring_service.py:
"""Recurring payments service: offers what looks recurring in your history, creates items only when you confirm.

* `candidates()`    regular series found in your transactions (refund-netted spend is not involved: these are payments).
* `confirm()`       "Confirm as recurring": creates a `recurring_items` record (origin 'detected') that Safe-to-Spend and upcoming
                    bills then use. Never done silently.
* `dismiss()`       "Not recurring": remembered per merchant, undoable with `restore()`.
* `item_notices()`  for items you already track: a changed amount, or no payment seen for 2+ cycles (neutral wording).
"""
import json
import sqlite3
from collections import Counter, defaultdict
from datetime import date

from . import recurring as rec
from .merchant import MATCHER
from .safe_to_spend import names_match
from .storage import COUNTS_IN_REPORTS
from .trustledger import _norm, inr

KINDS = ("bill", "subscription", "income")


class RecurringError(Exception):
    def __init__(self, message: str, status: int = 400):
        super().__init__(message)
        self.status = status


def merchant_key(payee: str, clean: str | None) -> str:
    return _norm(clean or payee) or (payee or "").strip().casefold()


def _history(conn: sqlite3.Connection) -> dict[tuple[str, str], dict]:
    """Counted payments grouped by (direction, merchant). Matched refunds are not income, and merged copies are ignored."""
    groups: dict[tuple[str, str], dict] = defaultdict(lambda: {"names": Counter(), "tags": Counter(), "occ": []})
    for r in conn.execute(f"SELECT t.id, t.date_time, t.amount, t.type, t.payee, t.merchant_clean, t.tag_id FROM transactions t WHERE {COUNTS_IN_REPORTS}"
                          " AND (t.link_kind IS NULL OR t.link_kind != 'refund') ORDER BY t.date_time, t.id"):
        try:
            day = date.fromisoformat(r["date_time"][:10])
        except ValueError:
            continue
        g = groups[(r["type"], merchant_key(r["payee"], r["merchant_clean"]))]
        g["names"][r["payee"]] += 1
        if r["tag_id"]:
            g["tags"][r["tag_id"]] += 1
        g["occ"].append(rec.Occ(r["id"], day, r["amount"]))
    return groups


def _hidden(conn: sqlite3.Connection, kind: str) -> set[str]:
    return {r["insight_key"] for r in conn.execute("SELECT insight_key FROM dismissed_insights WHERE kind = ?", (kind,))}


def _items(conn: sqlite3.Connection) -> list[sqlite3.Row]:
    return conn.execute("SELECT * FROM recurring_items WHERE active = 1").fetchall()


def _covered(items: list[sqlite3.Row], name: str, direction: str) -> bool:
    for it in items:
        if (it["kind"] == "income") == (direction == "credit") and (names_match(it["merchant"] or it["name"], name) or names_match(it["name"], name)):
            return True
    return False


def _suggest_kind(direction: str, name: str, cadence: str, typical: int) -> dict:
    if direction == "credit":
        return {"kind": "income", "essential": False}
    found = MATCHER.match(name)
    if found and found[0] == "entertainment":
        return {"kind": "subscription", "essential": False}
    if found and found[0] == "bills":
        return {"kind": "bill", "essential": True}
    return {"kind": "bill", "essential": True}      # unknown: treated as a bill you must pay (the cautious choice)


def _view(conn: sqlite3.Connection, s: rec.Series, display: str, key: str, tag_id: int | None) -> dict:
    from . import trust_service
    latest = s.occurrences[-12:]
    return {
        "key": key, "merchant": display, "direction": s.direction, "cadence": s.cadence, "cadence_label": rec.CADENCE_WORDS[s.cadence],
        "typical_paise": s.typical, "typical": s.typical / 100, "last": s.last_day.isoformat(), "next_expected": s.next_expected.isoformat(),
        "count": len(s.occurrences), "confidence": s.confidence, "reasons": s.reasons, "notes": s.notes,
        "price_change": ({**s.price_change, "from": s.price_change["from_paise"] / 100, "to": s.price_change["to_paise"] / 100} if s.price_change else None),
        "possibly_ended": s.possibly_ended, "suggested": _suggest_kind(s.direction, display, s.cadence, s.typical), "tag_id": tag_id,
        "transactions": [trust_service.brief(conn, o.id) for o in reversed(latest)],
        "filters": {"payee": display, "type": "debit" if s.direction == "debit" else "credit"},
    }


def candidates(conn: sqlite3.Connection, today: date) -> dict:
    """Series found in your history that you haven't confirmed or ruled out, newest first."""
    hidden, items = _hidden(conn, "recurring"), _items(conn)
    out = []
    for (direction, key), g in _history(conn).items():
        if f"recurring:{direction}:{key}" in hidden:
            continue
        display = g["names"].most_common(1)[0][0]
        if _covered(items, display, direction):
            continue
        s = rec.detect(display, direction, g["occ"], today)
        if s:
            out.append(_view(conn, s, display, f"{direction}:{key}", g["tags"].most_common(1)[0][0] if g["tags"] else None))
    out.sort(key=lambda c: (c["possibly_ended"] is not None, {"High": 0, "Medium": 1, "Low": 2}[c["confidence"]], c["next_expected"]))
    return {"items": out, "rules": ("At least 3 payments to the same merchant at a regular interval (weekly +-1 day, fortnightly +-2, monthly +-4, quarterly +-8, "
                                    "yearly +-15) with similar amounts (within 10%). Varying amounts are never called recurring."),
            "hidden": len(hidden)}


def _find(conn: sqlite3.Connection, key: str, today: date) -> tuple[rec.Series, dict, str, int | None]:
    direction, _, mk = key.partition(":")
    g = _history(conn).get((direction, mk))
    if not g:
        raise RecurringError("No payments found for that merchant", 404)
    display = g["names"].most_common(1)[0][0]
    s = rec.detect(display, direction, g["occ"], today)
    if not s:
        raise RecurringError("That no longer looks like a regular pattern")
    return s, g, display, (g["tags"].most_common(1)[0][0] if g["tags"] else None)


def confirm(conn: sqlite3.Connection, key: str, today: date, *, kind: str | None = None, essential: bool | None = None,
            name: str | None = None, amount_paise: int | None = None) -> dict:
    """Create the recurring item from a detected series. What gets stored (schedule, next date) is re-detected here, not trusted from the client."""
    s, g, display, tag_id = _find(conn, key, today)
    sug = _suggest_kind(s.direction, display, s.cadence, s.typical)
    kind = kind or sug["kind"]
    if kind not in KINDS or (kind == "income") != (s.direction == "credit"):
        raise RecurringError("Payments you make are bills or subscriptions; money you receive is income")
    essential = sug["essential"] if essential is None else essential
    if amount_paise is not None and amount_paise <= 0:
        raise RecurringError("The amount must be above zero")
    # fortnightly/quarterly need migration 7's wider cadence list
    cur = conn.execute("INSERT INTO recurring_items (name, kind, amount, cadence, next_due, essential, tag_id, merchant, origin, active, include_in_estimate)"
                       " VALUES (?, ?, ?, ?, ?, ?, ?, ?, 'detected', 1, 0)",
                       ((name or display).strip()[:80], kind, amount_paise or s.typical, s.cadence, s.next_expected.isoformat(), int(essential and kind != "income"),
                        tag_id, display[:80]))
    conn.commit()
    return dict(conn.execute("SELECT * FROM recurring_items WHERE id = ?", (cur.lastrowid,)).fetchone())


def dismiss(conn: sqlite3.Connection, key: str) -> None:
    """'Not recurring': never offered again for this merchant (until restored)."""
    direction, _, mk = key.partition(":")
    if direction not in ("debit", "credit") or not mk:
        raise RecurringError("Not a recurring key")
    conn.execute("INSERT OR IGNORE INTO dismissed_insights (insight_key, kind) VALUES (?, 'recurring')", (f"recurring:{direction}:{mk}",))
    conn.commit()


def restore(conn: sqlite3.Connection, key: str | None = None) -> int:
    if key:
        direction, _, mk = key.partition(":")
        n = conn.execute("DELETE FROM dismissed_insights WHERE kind = 'recurring' AND insight_key = ?", (f"recurring:{direction}:{mk}",)).rowcount
    else:
        n = conn.execute("DELETE FROM dismissed_insights WHERE kind = 'recurring'").rowcount
    conn.commit()
    return n


def suppressed(conn: sqlite3.Connection) -> list[dict]:
    return [{"key": k.split(":", 1)[1], "merchant": k.split(":", 2)[2]} for k in sorted(_hidden(conn, "recurring"))]


def item_notices(conn: sqlite3.Connection, today: date) -> list[dict]:
    """For recurring items you already track: a changed amount, or no payment seen for 2+ cycles. Neutral, dismissible."""
    hist, gone, out = _history(conn), _hidden(conn, "notice"), []
    for it in _items(conn):
        direction = "credit" if it["kind"] == "income" else "debit"
        occ = []
        for (d, _key), g in hist.items():
            if d == direction:
                name = g["names"].most_common(1)[0][0]
                if names_match(it["merchant"] or it["name"], name) or names_match(it["name"], name):
                    occ += g["occ"]
        s = rec.detect(it["name"], direction, occ, today) if occ else None
        if not s:
            continue
        base = {"item_id": it["id"], "item": it["name"], "last": s.last_day.isoformat()}
        if abs(s.typical - it["amount"]) > max(it["amount"] * rec.PRICE_CHANGE_PCT // 100, 1000):
            key = f"notice:{it['id']}:price:{s.typical}"
            if key not in gone:
                out.append({**base, "key": key, "type": "price_change", "suggest_amount_paise": s.typical, "suggest_amount": s.typical / 100,
                            "text": f"The latest payments are {inr(s.typical)}, but {it['name']} is set to {inr(it['amount'])} in your plan.",
                            "why": f"Based on your {len(s.occurrences)} payments, the most recent on {s.last_day.isoformat()}."})
        if s.possibly_ended:
            key = f"notice:{it['id']}:ended:{s.last_day.isoformat()}"
            if key not in gone:
                out.append({**base, "key": key, "type": "possibly_ended", "cycles": s.possibly_ended["cycles"],
                            "text": f"No payment for {it['name']} has been seen for {s.possibly_ended['cycles']} cycles (the last was on {s.last_day.isoformat()}).",
                            "why": "It may have ended, moved to another account, or be paid in a way Paisa hasn't seen. Nothing is changed for you."})
    return out


def dismiss_notice(conn: sqlite3.Connection, key: str) -> None:
    if not key.startswith("notice:"):
        raise RecurringError("Not a notice key")
    conn.execute("INSERT OR IGNORE INTO dismissed_insights (insight_key, kind) VALUES (?, 'notice')", (key,))
    conn.commit()

