"""Data management: sample data, import batches, and erasing. (Backup/restore arrives in Stage 8.)

Every destructive route needs an explicit confirmation in the request body, so nothing can be
deleted by a stray click or a mistyped URL. The screens also ask the user first.
"""
import sqlite3

from fastapi import APIRouter, Depends, HTTPException
from pydantic import BaseModel

from .. import db, seed, storage, trust_service
from ..db import get_conn

router = APIRouter(prefix="/data", tags=["data"])

DELETE_PHRASE = "DELETE EVERYTHING"


