    c = storage.counts(conn)
    return {
        "mode": db.mode(),
        "schema_version": storage.schema_version(conn),
        **c,
        "only_samples": c["transactions"] > 0 and c["real_transactions"] == 0,
        "legacy_sample_candidates": len(seed.legacy_candidates(conn)),
        "migration_backup": storage.migration_backup_info(conn),
        "delete_phrase": DELETE_PHRASE,
    }


