def load_sample(conn: sqlite3.Connection = Depends(get_conn)):
    result = seed.load_sample_data(conn)
    trust_service.refresh(conn, "Sample data loaded")
    return result


@router.post("/sample/remove")
def remove_sample(body: Confirm, conn: sqlite3.Connection = Depends(get_conn)):
    """Delete only rows flagged as sample data."""
    if not body.confirm:
        raise HTTPException(400, "Confirmation required")
    removed = storage.remove_sample_data(conn)
    trust_service.refresh(conn, "Sample data removed")
    return removed


@router.get("/legacy-samples")
def legacy_samples(conn: sqlite3.Connection = Depends(get_conn)):
    """Rows that look like sample data added automatically by an older Paisa. Nothing is changed here."""
    return {"items": seed.legacy_candidates(conn)}


@router.post("/legacy-samples/flag")
def flag_legacy(body: FlagIds, conn: sqlite3.Connection = Depends(get_conn)):
    """The user reviewed the list and confirmed: flag these rows as sample data."""
    return seed.flag_legacy(conn, body.ids)


@router.post("/legacy-samples/dismiss")
def dismiss_legacy(conn: sqlite3.Connection = Depends(get_conn)):
    """'None of these are samples': leave everything unflagged and stop asking."""
    storage.dismiss_legacy_check(conn)
    return {"ok": True}


@router.get("/batches")
def batches(conn: sqlite3.Connection = Depends(get_conn)):
    return {"items": storage.list_batches(conn)}


@router.delete("/batches/{batch_id}")
def undo_batch(batch_id: int, conn: sqlite3.Connection = Depends(get_conn)):
    """Undo an import: removes that batch's transactions (and nothing else)."""
    deleted = storage.delete_batch(conn, batch_id)
    if deleted is None:
        raise HTTPException(404, "Import not found")
    trust_service.refresh(conn, "An import was undone")
    return {"deleted": deleted}


@router.post("/delete-all")
def delete_all(body: TypedConfirm, conn: sqlite3.Connection = Depends(get_conn)):
    """Erase everything. The caller must send the exact phrase the user typed."""
    if body.phrase != DELETE_PHRASE:
        raise HTTPException(400, f"Type {DELETE_PHRASE} exactly to confirm")
    return storage.delete_everything(conn)

app/routers/imports.py:
"""CSV import in three steps: inspect the file, preview with a mapping, commit."""
import sqlite3

from fastapi import APIRouter, Depends, File, Form, HTTPException, UploadFile
from pydantic import ValidationError

from ..db import get_conn
from ..importer import (MAX_BYTES, MAX_ROWS, ImportMapping, analyze, decode, guess_mapping,
                        insert_new, read_table)

router = APIRouter(prefix="/import", tags=["import"])


async def _load(file: UploadFile) -> tuple[list[str], list[list[str]], str]:
    data = await file.read(MAX_BYTES + 1)
    if len(data) > MAX_BYTES:
        raise HTTPException(413, "File is larger than 5 MB")
    headers, rows, delim = read_table(decode(data))
    if not headers or not rows:
        raise HTTPException(400, "This file doesn't look like a CSV with a header row and data")
    if len(rows) > MAX_ROWS:
        raise HTTPException(413, f"More than {MAX_ROWS} rows; split the file and import in parts")
    return headers, rows, delim


def _mapping(raw: str, headers: list[str]) -> ImportMapping:
    try:
        m = ImportMapping.model_validate_json(raw)
    except ValidationError as e:
        raise HTTPException(422, "Mapping is incomplete: " + "; ".join(
            f"{'.'.join(map(str, x['loc']))} {x['msg']}" for x in e.errors()))
    for col in (m.date, m.payee, m.amount, m.debit, m.credit, m.type, m.method, m.note,
                m.reference, m.balance, m.txn_status):
        if col and col not in headers:
            raise HTTPException(422, f"Column '{col}' is not in this file")
    needs = {"signed": [m.amount], "typed": [m.amount, m.type], "split": [m.debit, m.credit]}[m.amount_mode]
    if not all(needs):
        raise HTTPException(422, f"Choose the columns for amount mode '{m.amount_mode}'")
    return m


@router.post("/inspect")
async def inspect(file: UploadFile = File(...)):
    """Read the file's columns and suggest a mapping."""
    headers, rows, delim = await _load(file)
    return {"headers": headers, "sample": rows[:5], "row_count": len(rows),
            "delimiter": delim, "guess": guess_mapping(headers)}


@router.post("/preview")
async def preview(file: UploadFile = File(...), mapping: str = Form(...),
                  conn: sqlite3.Connection = Depends(get_conn)):
    """Dry run: how every row would be read, and which are duplicates. Writes nothing."""
    headers, rows, _ = await _load(file)
    results = analyze(conn, headers, rows, _mapping(mapping, headers))
    counts = {s: sum(1 for r in results if r["status"] == s) for s in ("new", "duplicate", "invalid")}
    # Show every problem row first, then a sample of the rest.
    shown = [r for r in results if r["status"] == "invalid"][:30] + \
            [r for r in results if r["status"] != "invalid"][:70]
    return {"counts": counts, "total": len(results), "rows": sorted(shown, key=lambda r: r["line"])}


@router.post("/commit")
async def commit(file: UploadFile = File(...), mapping: str = Form(...),
                 conn: sqlite3.Connection = Depends(get_conn)):
    """Import every new row. The file is parsed again here, so the result matches the preview."""
    headers, rows, _ = await _load(file)
    results = analyze(conn, headers, rows, _mapping(mapping, headers))
    return insert_new(conn, results, file.filename or "import.csv", _mapping(mapping, headers).clean_payee)

