app/routers/pay.py:
"""Pay screen: save a pending transaction, hand off to a UPI app, confirm afterwards.

Nothing here moves money. A upi://pay link only does something on a phone with a UPI app;
on a computer the screen shows the link and a QR code to scan with your phone.
"""
import re
import sqlite3
from urllib.parse import quote

from fastapi import APIRouter, Depends, HTTPException
from pydantic import BaseModel, Field, field_validator

from .. import trust_service
from ..tagging import TaggingContext
from ..db import get_conn, to_api, to_paise
from .tags import require_tag

router = APIRouter(prefix="/pay", tags=["pay"])

UPI_ID = re.compile(r"^[A-Za-z0-9._\-]{1,256}@[A-Za-z][A-Za-z0-9]{1,63}$")


def upi_link(upi_id: str, name: str, rupees: float, note: str = "") -> str:
    """Build the standard UPI deep link. Values are percent-encoded (spaces as %20)."""
    params = {"pa": upi_id, "pn": name or upi_id, "am": f"{rupees:.2f}", "cu": "INR"}
    if note:
        params["tn"] = note
    return "upi://pay?" + "&".join(f"{k}={quote(str(v), safe='@.')}" for k, v in params.items())


class PayIn(BaseModel):
    upi_id: str
    amount: float = Field(gt=0, le=1_00_00_000)
    payee_name: str = Field(default="", max_length=120)
    tag_id: int | None = None
    note: str = Field(default="", max_length=80)

    @field_validator("upi_id")
    @classmethod
    def valid_upi(cls, v: str) -> str:
        v = v.strip()
        if not UPI_ID.match(v):
            raise ValueError("That doesn't look like a UPI ID (expected name@bank)")
        return v


def _pending(conn: sqlite3.Connection, tx_id: int) -> sqlite3.Row:
    row = conn.execute("SELECT * FROM transactions WHERE id = ?", (tx_id,)).fetchone()
    if not row:
        raise HTTPException(404, "Transaction not found")
    if row["status"] != "pending":
        raise HTTPException(409, "This transaction is not pending")
    return row


@router.post("", status_code=201)
def start_payment(body: PayIn, conn: sqlite3.Connection = Depends(get_conn)):
    require_tag(conn, body.tag_id)
    payee = body.payee_name.strip() or body.upi_id
    if body.tag_id is not None:
        tag_id, tag_source, tag_detail = body.tag_id, "user", None
    else:
        d = TaggingContext(conn).decide(payee)
        tag_id, tag_source, tag_detail = d.tag_id, d.source, d.detail
    cur = conn.execute(
        "INSERT INTO transactions (date_time, amount, type, payee, payment_method, tag_id, tag_source, tag_detail, note,"
        " status, upi_id, source, txn_status, merchant_raw, merchant_clean)"
        " VALUES (datetime('now', 'localtime'), ?, 'debit', ?, 'upi', ?, ?, ?, ?, 'pending', ?, 'pay-flow', 'pending', ?, ?)",
        (to_paise(body.amount), payee, tag_id, tag_source, tag_detail, body.note, body.upi_id, payee, payee))
    conn.commit()
    trust_service.refresh(conn, "Payment started on the Pay screen")
    row = conn.execute("SELECT t.*, g.name AS tag_name, g.color AS tag_color FROM transactions t "
                       "LEFT JOIN tags g ON g.id = t.tag_id WHERE t.id = ?", (cur.lastrowid,)).fetchone()
    return {"transaction": to_api(row), "link": upi_link(body.upi_id, payee, body.amount, body.note)}


@router.get("/{tx_id}/link")
def link_for(tx_id: int, conn: sqlite3.Connection = Depends(get_conn)):
    """The link for a pending payment, so you can show the QR code again."""
    row = _pending(conn, tx_id)
    if not row["upi_id"]:
        raise HTTPException(400, "This pending transaction has no UPI ID")
    return {"link": upi_link(row["upi_id"], row["payee"], row["amount"] / 100, row["note"])}


@router.post("/{tx_id}/confirm")
def confirm(tx_id: int, conn: sqlite3.Connection = Depends(get_conn)):
    """"Yes, it went through": the payment becomes a normal completed transaction."""
    _pending(conn, tx_id)
    conn.execute("UPDATE transactions SET status = 'completed', txn_status = 'success' WHERE id = ?", (tx_id,))
    conn.commit()
    trust_service.refresh(conn, "You said the payment went through")
    return {"ok": True}


@router.post("/{tx_id}/cancel")
def cancel(tx_id: int, conn: sqlite3.Connection = Depends(get_conn)):
    """"No, it didn't": the pending record is removed so it never counts as spend."""
    _pending(conn, tx_id)
    conn.execute("DELETE FROM transactions WHERE id = ?", (tx_id,))
    conn.commit()
    trust_service.refresh(conn, "A pending payment was cancelled")
    return {"ok": True}

app/routers/plan.py:
"""The plan behind safe-to-spend: recurring bills / subscriptions / income, expected income, and savings goals.

Recurring items are designed so Stage 6 (detecting recurring payments) can create them: `origin` is 'manual' or
'detected', and a schedule is just (cadence, an anchor date). Amounts arrive in rupees and are stored as paise."""
import sqlite3
from datetime import date
from typing import Literal

from fastapi import APIRouter, Depends, HTTPException, Query
from pydantic import BaseModel, Field, field_validator

from .. import safe_to_spend as sts
from ..db import get_conn, to_api, to_paise
from .tags import require_tag

router = APIRouter(prefix="/plan", tags=["plan"])

Rupees = Field(gt=0, le=100_00_00_000)


def _date(v: str) -> str:
    try:
        return date.fromisoformat(v).isoformat()
    except (TypeError, ValueError):
        raise ValueError("must be a date like 2026-03-25")


class RecurringIn(BaseModel):
    name: str = Field(min_length=1, max_length=80)
    kind: Literal["bill", "subscription", "income"] = "bill"
    amount: float = Rupees
    cadence: Literal["weekly", "fortnightly", "monthly", "quarterly", "yearly"] = "monthly"
    next_due: str                                   # the schedule's anchor: a due date (day of month / weekday come from it)
    essential: bool = True
    tag_id: int | None = None
    merchant: str | None = Field(default=None, max_length=80)   # what to look for in your transactions to see if it is paid
    active: bool = True
    include_in_estimate: bool = False               # income only: count it in safe-to-spend (estimated)
    origin: Literal["manual", "detected"] = "manual"

    @field_validator("name", "merchant")
    @classmethod
    def strip(cls, v):
        return v.strip() if isinstance(v, str) else v

    @field_validator("next_due")
    @classmethod
    def valid_date(cls, v):
        return _date(v)


class IncomeIn(BaseModel):
    name: str = Field(min_length=1, max_length=80)
    amount: float = Rupees
    expected_date: str
    active: bool = True
    include_in_estimate: bool = False
    received_transaction_id: int | None = None

    @field_validator("expected_date")
    @classmethod
    def valid_date(cls, v):
        return _date(v)


class GoalIn(BaseModel):
    name: str = Field(min_length=1, max_length=80)
    target_amount: float = Rupees
    saved_amount: float = Field(default=0, ge=0, le=100_00_00_000)
    monthly_contribution: float = Field(default=0, ge=0, le=100_00_00_000)
    target_date: str | None = None
    active: bool = True

    @field_validator("target_date")
    @classmethod
    def valid_date(cls, v):
        return _date(v) if v else None


class IncludeIn(BaseModel):
    include: bool


class MarkIn(BaseModel):
    due_date: str
    state: Literal["paid", "unpaid", "auto"]       # auto = remove my mark and let Paisa match
    transaction_id: int | None = None

    @field_validator("due_date")
    @classmethod
    def valid_date(cls, v):
        return _date(v)


def _next_occurrence(row: sqlite3.Row, today: date) -> str | None:
    d = sts.occurrences(row["cadence"], date.fromisoformat(row["next_due"]), today, date(today.year + 2, today.month, 1))
    d = [x for x in d if x >= date.fromisoformat(row["next_due"])]
    return d[0].isoformat() if d else None


# ---- recurring bills / subscriptions / income ------------------------------------------------

REC_SQL = "SELECT r.*, g.name AS tag_name FROM recurring_items r LEFT JOIN tags g ON g.id = r.tag_id "


def _rec(conn, item_id: int, today: date | None = None) -> dict:
    r = conn.execute(REC_SQL + "WHERE r.id = ?", (item_id,)).fetchone()
    if not r:
        raise HTTPException(404, "Not found")
    d = to_api(r)
    d["next_occurrence"] = _next_occurrence(r, today or date.today())
    return d


@router.get("/recurring")
def list_recurring(kind: Literal["bills", "income", "all"] = "all", today: str | None = Query(None), conn: sqlite3.Connection = Depends(get_conn)):
    t = date.fromisoformat(today) if today else date.today()
    where = {"bills": "WHERE r.kind IN ('bill', 'subscription') ", "income": "WHERE r.kind = 'income' ", "all": ""}[kind]
    rows = conn.execute(REC_SQL + where + "ORDER BY r.active DESC, r.next_due, r.id").fetchall()
    return {"items": [{**to_api(r), "next_occurrence": _next_occurrence(r, t)} for r in rows]}


def _rec_values(conn, b: RecurringIn) -> tuple:
    require_tag(conn, b.tag_id)
    return (b.name, b.kind, to_paise(b.amount), b.cadence, b.next_due, int(b.essential), b.tag_id, b.merchant or None,
            b.origin, int(b.active), int(b.include_in_estimate and b.kind == "income"))


@router.post("/recurring", status_code=201)
def create_recurring(body: RecurringIn, conn: sqlite3.Connection = Depends(get_conn)):
    cur = conn.execute("INSERT INTO recurring_items (name, kind, amount, cadence, next_due, essential, tag_id, merchant, origin, active,"
                       " include_in_estimate) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)", _rec_values(conn, body))
    conn.commit()
    return _rec(conn, cur.lastrowid)


@router.put("/recurring/{item_id}")
def update_recurring(item_id: int, body: RecurringIn, conn: sqlite3.Connection = Depends(get_conn)):
    _rec(conn, item_id)
    conn.execute("UPDATE recurring_items SET name = ?, kind = ?, amount = ?, cadence = ?, next_due = ?, essential = ?, tag_id = ?,"
                 " merchant = ?, origin = ?, active = ?, include_in_estimate = ? WHERE id = ?", (*_rec_values(conn, body), item_id))
    conn.commit()
    return _rec(conn, item_id)


@router.delete("/recurring/{item_id}", status_code=204)
def delete_recurring(item_id: int, conn: sqlite3.Connection = Depends(get_conn)):
    if conn.execute("DELETE FROM recurring_items WHERE id = ?", (item_id,)).rowcount == 0:
        raise HTTPException(404, "Not found")
    conn.commit()


@router.post("/recurring/{item_id}/include")
def include_recurring(item_id: int, body: IncludeIn, conn: sqlite3.Connection = Depends(get_conn)):
    """Switch an INCOME item on or off in the estimate (off by default)."""
    r = _rec(conn, item_id)
    if r["kind"] != "income":
        raise HTTPException(400, "Only income can be included in the estimate")
    conn.execute("UPDATE recurring_items SET include_in_estimate = ? WHERE id = ?", (int(body.include), item_id))
    conn.commit()
    return _rec(conn, item_id)


@router.post("/recurring/{item_id}/mark")
def mark_bill(item_id: int, body: MarkIn, conn: sqlite3.Connection = Depends(get_conn)):
    """Say that one due date of a bill is paid or unpaid (overrides automatic matching), or clear your mark."""
    r = _rec(conn, item_id)
    if r["kind"] == "income":
        raise HTTPException(400, "Marks are for bills")
    if body.state == "auto":
        conn.execute("DELETE FROM bill_marks WHERE item_id = ? AND due_date = ?", (item_id, body.due_date))
    else:
        conn.execute("INSERT INTO bill_marks (item_id, due_date, state, transaction_id) VALUES (?, ?, ?, ?)"
                     " ON CONFLICT(item_id, due_date) DO UPDATE SET state = excluded.state, transaction_id = excluded.transaction_id",
                     (item_id, body.due_date, body.state, body.transaction_id))
    conn.commit()
    return {"item_id": item_id, "due_date": body.due_date, "state": body.state}


# ---- one-off expected income -------------------------------------------------------------------

def _income(conn, item_id: int) -> dict:
    r = conn.execute("SELECT * FROM expected_income WHERE id = ?", (item_id,)).fetchone()
    if not r:
        raise HTTPException(404, "Not found")
    return to_api(r)


@router.get("/income")
def list_income(conn: sqlite3.Connection = Depends(get_conn)):
    return {"items": [to_api(r) for r in conn.execute("SELECT * FROM expected_income ORDER BY active DESC, expected_date, id")]}


@router.post("/income", status_code=201)
def create_income(body: IncomeIn, conn: sqlite3.Connection = Depends(get_conn)):
    cur = conn.execute("INSERT INTO expected_income (name, amount, expected_date, active, include_in_estimate, received_transaction_id)"
                       " VALUES (?, ?, ?, ?, ?, ?)", (body.name.strip(), to_paise(body.amount), body.expected_date, int(body.active),
                                                      int(body.include_in_estimate), body.received_transaction_id))
    conn.commit()
    return _income(conn, cur.lastrowid)


@router.put("/income/{item_id}")
def update_income(item_id: int, body: IncomeIn, conn: sqlite3.Connection = Depends(get_conn)):
    _income(conn, item_id)
    conn.execute("UPDATE expected_income SET name = ?, amount = ?, expected_date = ?, active = ?, include_in_estimate = ?,"
                 " received_transaction_id = ? WHERE id = ?", (body.name.strip(), to_paise(body.amount), body.expected_date, int(body.active),
                                                               int(body.include_in_estimate), body.received_transaction_id, item_id))
    conn.commit()
    return _income(conn, item_id)


@router.delete("/income/{item_id}", status_code=204)
def delete_income(item_id: int, conn: sqlite3.Connection = Depends(get_conn)):
    if conn.execute("DELETE FROM expected_income WHERE id = ?", (item_id,)).rowcount == 0:
        raise HTTPException(404, "Not found")
    conn.commit()


@router.post("/income/{item_id}/include")
def include_income(item_id: int, body: IncludeIn, conn: sqlite3.Connection = Depends(get_conn)):
    _income(conn, item_id)
    conn.execute("UPDATE expected_income SET include_in_estimate = ? WHERE id = ?", (int(body.include), item_id))
    conn.commit()
    return _income(conn, item_id)


# ---- savings goals ---------------------------------------------------------------------------------

def _goal(conn, goal_id: int) -> dict:
    r = conn.execute("SELECT * FROM savings_goals WHERE id = ?", (goal_id,)).fetchone()
    if not r:
        raise HTTPException(404, "Not found")
    return to_api(r)


@router.get("/goals")
def list_goals(conn: sqlite3.Connection = Depends(get_conn)):
    return {"items": [to_api(r) for r in conn.execute("SELECT * FROM savings_goals ORDER BY active DESC, id")]}


def _goal_values(b: GoalIn) -> tuple:
    return (b.name.strip(), to_paise(b.target_amount), to_paise(b.saved_amount), to_paise(b.monthly_contribution), b.target_date, int(b.active))


@router.post("/goals", status_code=201)
def create_goal(body: GoalIn, conn: sqlite3.Connection = Depends(get_conn)):
    cur = conn.execute("INSERT INTO savings_goals (name, target_amount, saved_amount, monthly_contribution, target_date, active)"
                       " VALUES (?, ?, ?, ?, ?, ?)", _goal_values(body))
    conn.commit()
    return _goal(conn, cur.lastrowid)


@router.put("/goals/{goal_id}")
def update_goal(goal_id: int, body: GoalIn, conn: sqlite3.Connection = Depends(get_conn)):
    _goal(conn, goal_id)
    conn.execute("UPDATE savings_goals SET name = ?, target_amount = ?, saved_amount = ?, monthly_contribution = ?, target_date = ?,"
                 " active = ? WHERE id = ?", (*_goal_values(body), goal_id))
    conn.commit()
    return _goal(conn, goal_id)


@router.delete("/goals/{goal_id}", status_code=204)
def delete_goal(goal_id: int, conn: sqlite3.Connection = Depends(get_conn)):
    if conn.execute("DELETE FROM savings_goals WHERE id = ?", (goal_id,)).rowcount == 0:
        raise HTTPException(404, "Not found")
