app/routers/privacy.py:
"""Backup/restore, the app passcode and the Privacy page's facts. Backups and passphrases travel in request bodies only."""
import sqlite3

from fastapi import APIRouter, Depends, HTTPException
from pydantic import BaseModel, Field

from .. import backup, db, passcode, storage
from ..db import get_conn
from .data import DELETE_PHRASE

router = APIRouter(tags=["privacy"])


class RestoreIn(BaseModel):
    backup: dict
    confirm: bool = False


class PreviewIn(BaseModel):
    backup: dict


class NewPass(BaseModel):
    new: str = Field(max_length=128)
    current: str | None = Field(default=None, max_length=128)


class PassIn(BaseModel):
    passcode: str = Field(default="", max_length=128)


class ForgotIn(BaseModel):
    phrase: str = ""


def _backup_errors(fn, *a):
    try:
        return fn(*a)
    except backup.BackupError as e:
        raise HTTPException(e.status, str(e))


@router.post("/data/backup/export")
def export(conn: sqlite3.Connection = Depends(get_conn)):
    doc = backup.export(conn)
    backup.mark_exported(conn)
    return doc


@router.post("/data/backup/preview")
def preview(body: PreviewIn, conn: sqlite3.Connection = Depends(get_conn)):
    return _backup_errors(backup.preview, conn, body.backup)


@router.post("/data/backup/restore")
def restore(body: RestoreIn, conn: sqlite3.Connection = Depends(get_conn)):
    if not body.confirm:
        raise HTTPException(400, "Confirmation required")
    return _backup_errors(backup.restore, conn, body.backup)


def _pass(fn, *a, **k):
    try:
        return fn(*a, **k)
    except passcode.PasscodeError as e:
        raise HTTPException(e.status, str(e), headers={"Retry-After": str(e.wait)} if e.wait else None)


@router.get("/privacy/passcode")
def passcode_status(conn: sqlite3.Connection = Depends(get_conn)):
    return passcode.status(conn)


@router.post("/privacy/passcode/set")
def passcode_set(body: NewPass, conn: sqlite3.Connection = Depends(get_conn)):
    _pass(passcode.set_passcode, conn, body.new, body.current)
    return passcode.status(conn)


@router.post("/privacy/passcode/verify")
def passcode_verify(body: PassIn, conn: sqlite3.Connection = Depends(get_conn)):
    ok = _pass(passcode.verify, conn, body.passcode)
    if not ok:
        st = passcode.status(conn)
        wait = st["wait_seconds"]
        raise HTTPException(403, "That passcode is not right." + (f" Wait {wait} seconds before trying again." if wait else ""),
                            headers={"Retry-After": str(wait)} if wait else None)
    return {"ok": True}


@router.post("/privacy/passcode/remove")
def passcode_remove(body: PassIn, conn: sqlite3.Connection = Depends(get_conn)):
    _pass(passcode.remove, conn, body.passcode)
    return passcode.status(conn)


@router.post("/privacy/passcode/forgot")
def passcode_forgot(body: ForgotIn, conn: sqlite3.Connection = Depends(get_conn)):
    """No recovery exists. The only way back is to erase everything, with the same typed phrase as 'Delete everything'."""
    if body.phrase != DELETE_PHRASE:
        raise HTTPException(400, f"Type {DELETE_PHRASE} exactly to confirm")
    storage.delete_everything(conn)
    passcode.clear(conn)
    return {"erased": True}


def _backup_state(conn: sqlite3.Connection) -> dict:
    """For the backup indicator: when you last saved a backup, and whether a reminder is due (never nags an empty app)."""
    from datetime import datetime
    raw = storage.get_settings(conn)
    n = conn.execute("SELECT COUNT(*) FROM transactions WHERE is_sample = 0").fetchone()[0]
    last, days = raw["last_backup_at"], raw["backup_reminder_days"]
    age = None
    if last:
        try:
            age = (datetime.now() - datetime.fromisoformat(last)).days
        except ValueError:
            age = None
    due = bool(days) and n > 0 and (age is None or age >= days)
    return {"last": last or None, "days_ago": age, "reminder_days": days, "has_data": n > 0, "due": due}


@router.get("/privacy/summary")
def summary(conn: sqlite3.Connection = Depends(get_conn)):
    mode = db.mode()
    return {
        "mode": mode,
        "stored": ("In this browser's private storage (IndexedDB). It never leaves this device." if mode == "app"
                   else f"In a file on this computer: {db.db_path()}"),
        "external_requests": "None at runtime. Paisa makes no calls to other servers: no analytics, no fonts, no maps, no AI service.",
        "sent_to_anyone": False,
        "passcode": passcode.status(conn),
        "facts": [
            "Your transactions, tags, budgets and plans are stored only on this device.",
            "Nothing is uploaded. There is no account, no sign-in and no cloud copy.",
            "Amounts, merchants and search terms are never placed in web addresses and are not written to logs.",
            "Backups are files you choose to save. An encrypted backup needs its passphrase, which Paisa cannot recover.",
            "The optional passcode locks the screens. It is not encryption: someone with access to your files can still read the data.",
            "Paisa never asks for your UPI PIN, bank password or OTP, and never reads your messages without you pasting them in.",
        ],
        "last_backup_at": storage.get_settings(conn)["last_backup_at"],
        "backup": _backup_state(conn),
    }

