"""Reconciliation API. Wording: unmatched / not found in / doesn't add up / according to this imported file."""
import sqlite3
from datetime import date

from fastapi import APIRouter, Depends, HTTPException, Query
from pydantic import BaseModel

from .. import recon_service as svc
from ..db import get_conn

router = APIRouter(prefix="/recon", tags=["reconciliation"])


class SourceIn(BaseModel):
    kind: str          # 'batch' or 'own'
    id: int = 0


class PairIn(BaseModel):
    a: SourceIn
    b: SourceIn


class ResolveIn(BaseModel):
    action: str        # confirm | dismiss | merge | match | not_same | add_missing | use_imported | keep_mine
    keep_id: int | None = None
    drop_id: int | None = None
    a_id: int | None = None
    b_id: int | None = None
    fields: dict | None = None
    today: str | None = None


class MatchIn(BaseModel):
    a_id: int
    b_id: int
    same: bool = True


def _run(fn, *args, **kw):
    try:
        return fn(*args, **kw)
    except svc.ReconError as e:
        raise HTTPException(e.status, str(e))


def _pair(p: PairIn):
    for s in (p.a, p.b):
        if s.kind not in ("batch", "own"):
            raise HTTPException(400, "Source kind must be 'batch' or 'own'")
    return (p.a.kind, p.a.id if p.a.kind == "batch" else 0), (p.b.kind, p.b.id if p.b.kind == "batch" else 0)


@router.get("/summary")
def summary(conn: sqlite3.Connection = Depends(get_conn)):
    return svc.summary(conn)


@router.post("/refresh")
def refresh(conn: sqlite3.Connection = Depends(get_conn)):
    return svc.refresh(conn)


@router.get("/sources")
def sources(conn: sqlite3.Connection = Depends(get_conn)):
    return {"items": svc.sources(conn)}


@router.get("/issues")
def issues(group: str | None = None, state: str = "open", conn: sqlite3.Connection = Depends(get_conn)):
    if state not in ("open", "resolved", "dismissed"):
        raise HTTPException(400, "state must be open, resolved or dismissed")
    return {"items": svc.list_issues(conn, group, state)}


@router.post("/issues/{issue_id}/resolve")
def resolve(issue_id: int, body: ResolveIn, conn: sqlite3.Connection = Depends(get_conn)):
    today = date.fromisoformat(body.today) if body.today else date.today()
    return _run(svc.resolve, conn, issue_id, body.action, keep_id=body.keep_id, drop_id=body.drop_id, a_id=body.a_id, b_id=body.b_id,
                fields=body.fields, today=today)


@router.post("/issues/{issue_id}/reopen")
def reopen(issue_id: int, conn: sqlite3.Connection = Depends(get_conn)):
    return _run(svc.reopen, conn, issue_id)


@router.post("/compare")
def compare(body: PairIn, conn: sqlite3.Connection = Depends(get_conn)):
    """Compare two sources over the dates both cover. Changes nothing."""
    a, b = _pair(body)
    return _run(svc.compare_sources, conn, a, b)


@router.get("/comparisons")
def comparisons(conn: sqlite3.Connection = Depends(get_conn)):
    return {"items": svc.list_comparisons(conn)}


@router.post("/comparisons", status_code=201)
def track(body: PairIn, conn: sqlite3.Connection = Depends(get_conn)):
    """Keep comparing these two sources: their unmatched rows become tracked issues."""
    a, b = _pair(body)
    return _run(svc.track_comparison, conn, a, b)


@router.delete("/comparisons/{comparison_id}", status_code=204)
def untrack(comparison_id: int, conn: sqlite3.Connection = Depends(get_conn)):
    _run(svc.stop_tracking, conn, comparison_id)


@router.post("/match")
def match(body: MatchIn, conn: sqlite3.Connection = Depends(get_conn)):
    """Your decision that two rows are (or are not) the same payment."""
    return _run(svc.match_rows, conn, body.a_id, body.b_id, body.same)


@router.get("/balance-trail/{batch_id}")
def trail(batch_id: int, conn: sqlite3.Connection = Depends(get_conn)):
    return _run(svc.trail_for_batch, conn, batch_id)


@router.get("/opening")
def opening(conn: sqlite3.Connection = Depends(get_conn)):
    return {"opening": svc.opening_info(conn)}


@router.post("/changes/{change_id}/undo")
def undo(change_id: int, conn: sqlite3.Connection = Depends(get_conn)):
    """Undo an entry added from reconciliation."""
    return _run(svc.undo_add, conn, change_id)

