"""Safe-to-spend API. Everything here is an ESTIMATE from Paisa's own data (see safe_to_spend.py).

`today` is optional everywhere: the browser sends the device's local date so "today" is the user's today.
Amounts that the user types travel in request bodies, never in URLs."""
import sqlite3
from datetime import date

from fastapi import APIRouter, Depends, HTTPException, Query
from pydantic import BaseModel, Field

from .. import sts_service as svc
from ..db import get_conn, to_paise

router = APIRouter(prefix="/safe-to-spend", tags=["safe-to-spend"])


class BalanceIn(BaseModel):
    amount: float = Field(ge=0, le=100_00_00_000, description="Rupees")
    as_of: date                                  # the day this balance was true (end of that day)
    today: str | None = None


class AffordIn(BaseModel):
    amount: float = Field(gt=0, le=100_00_00_000, description="Rupees")
    today: str | None = None


class KeyIn(BaseModel):
    key: str


def _run(fn, *args, **kw):
    try:
        return fn(*args, **kw)
    except svc.StsError as e:
        raise HTTPException(e.status, str(e))


@router.get("")
def estimate(today: str | None = Query(None), conn: sqlite3.Connection = Depends(get_conn)):
    """The estimate, with how it was calculated, confidence, what is missing and alerts."""
    return _run(lambda: svc.estimate(conn, svc.parse_today(today)))


@router.put("/balance")
def set_balance(body: BalanceIn, conn: sqlite3.Connection = Depends(get_conn)):
    """Enter a starting balance with the date it was true. Transactions on or before that date stop counting."""
    _run(lambda: svc.set_balance(conn, to_paise(body.amount), body.as_of, svc.parse_today(body.today), "entered"))
    return _run(lambda: svc.estimate(conn, svc.parse_today(body.today)))


@router.post("/balance/use-import")
def use_import(body: dict | None = None, conn: sqlite3.Connection = Depends(get_conn)):
    """Use the newest balance printed on an imported statement as the starting balance."""
    today = svc.parse_today((body or {}).get("today"))
    _run(lambda: svc.use_import_balance(conn, today))
    return _run(lambda: svc.estimate(conn, today))


@router.delete("/balance", status_code=204)
def clear_balance(conn: sqlite3.Connection = Depends(get_conn)):
    svc.clear_balance(conn)


@router.post("/afford")
def afford(body: AffordIn, conn: sqlite3.Connection = Depends(get_conn)):
    """'Can I afford ₹X?': comfortably / yes but tight / not within your safe amount, with the arithmetic."""
