"""Settings API (Stage 4 uses it for the Safe-to-Spend settings; Stage 8 builds the full Settings screen on it).

Money settings are shown and accepted in rupees and stored as paise. The starting balance is deliberately NOT editable
here: it must be set together with its date and source through /safe-to-spend/balance."""
import sqlite3
from typing import Any

from fastapi import APIRouter, Depends, HTTPException

from ..db import get_conn, to_paise
from ..storage import ENUM_VALUES, SETTING_DEFAULTS, get_settings, set_settings

router = APIRouter(prefix="/settings", tags=["settings"])

LOCKED = {"starting_balance", "starting_balance_date", "starting_balance_source", "last_backup_at"}


def _view(raw: dict) -> dict:
    out = {}
    for k, v in raw.items():
        if k in LOCKED:
            continue
        out[k] = v / 100 if SETTING_DEFAULTS[k][1] == "paise" and v is not None else v
    return out


@router.get("")
def read(conn: sqlite3.Connection = Depends(get_conn)):
    return {"settings": _view(get_settings(conn)), "choices": {k: list(v) for k, v in ENUM_VALUES.items()}}


@router.put("")
def write(changes: dict[str, Any], conn: sqlite3.Connection = Depends(get_conn)):
    """Change one or more settings (all or nothing)."""
    bad = set(changes) & LOCKED
    if bad:
        raise HTTPException(400, f"Not editable here: {', '.join(sorted(bad))}")
    try:
        conv = {k: (to_paise(v) if k in SETTING_DEFAULTS and SETTING_DEFAULTS[k][1] == "paise" and v not in (None, "") else v)
                for k, v in changes.items()}
        out = {"settings": _view(set_settings(conn, conv))}
        from .. import recon_service
        recon_service.refresh(conn)                        # settings can change what Reconciliation derives
        return out
    except ValueError as e:
        raise HTTPException(400, str(e))

