"""Tags (create, rename, recolor, delete) and auto-tag rules."""
import sqlite3

from fastapi import APIRouter, Depends, HTTPException
from pydantic import BaseModel

from .. import tagging
from ..db import get_conn
from ..merchant_dictionary import DICTIONARY
from ..models import RuleIn, TagIn
from ..starter import STARTER_TAGS

router = APIRouter(tags=["tags"])


def _tag(conn: sqlite3.Connection, tag_id: int) -> dict:
    row = conn.execute(
        "SELECT g.id, g.name, g.color, COUNT(t.id) AS tx_count FROM tags g "
        "LEFT JOIN transactions t ON t.tag_id = g.id AND t.merged_into_id IS NULL WHERE g.id = ? GROUP BY g.id", (tag_id,)
    ).fetchone()
    if not row:
        raise HTTPException(404, "Tag not found")
    return dict(row)


def require_tag(conn: sqlite3.Connection, tag_id: int | None) -> None:
    """400 if a tag id is given but does not exist."""
    if tag_id is not None and not conn.execute("SELECT 1 FROM tags WHERE id = ?", (tag_id,)).fetchone():
        raise HTTPException(400, f"Tag {tag_id} does not exist")


@router.get("/tags")
def list_tags(conn: sqlite3.Connection = Depends(get_conn)):
    rows = conn.execute(
        "SELECT g.id, g.name, g.color, COUNT(t.id) AS tx_count FROM tags g "
        "LEFT JOIN transactions t ON t.tag_id = g.id AND t.merged_into_id IS NULL GROUP BY g.id ORDER BY g.name"
    ).fetchall()
    return [dict(r) for r in rows]


@router.post("/tags", status_code=201)
def create_tag(body: TagIn, conn: sqlite3.Connection = Depends(get_conn)):
    try:
        cur = conn.execute("INSERT INTO tags (name, color) VALUES (?, ?)", (body.name, body.color))
    except sqlite3.IntegrityError:
        raise HTTPException(409, f"A tag named '{body.name}' already exists")
    conn.commit()
    return _tag(conn, cur.lastrowid)


@router.put("/tags/{tag_id}")
def update_tag(tag_id: int, body: TagIn, conn: sqlite3.Connection = Depends(get_conn)):
    _tag(conn, tag_id)
    try:
        conn.execute("UPDATE tags SET name = ?, color = ? WHERE id = ?", (body.name, body.color, tag_id))
    except sqlite3.IntegrityError:
        raise HTTPException(409, f"A tag named '{body.name}' already exists")
    conn.commit()
    return _tag(conn, tag_id)


@router.delete("/tags/{tag_id}", status_code=204)
def delete_tag(tag_id: int, conn: sqlite3.Connection = Depends(get_conn)):
    """Transactions keep existing and become untagged; its rules and budget are removed."""
    _tag(conn, tag_id)
    conn.execute("DELETE FROM tags WHERE id = ?", (tag_id,))
    conn.commit()


# ---- starter tags and the built-in merchant list ----------------------------------

class StarterIn(BaseModel):
    keys: list[str] | None = None   # None = all of them


@router.get("/tags/starter")
def starter_preview(conn: sqlite3.Connection = Depends(get_conn)):
    """What "Add starter tags" would do: create each starter tag, or reuse the one you already have."""
    plan = tagging.starter_plan(conn)
    return {"items": plan, "missing": sum(1 for p in plan if p["action"] == "create")}


@router.post("/tags/starter")
def add_starter(body: StarterIn, conn: sqlite3.Connection = Depends(get_conn)):
    """Opt-in. Existing tags (same name or a known equivalent) are reused and never changed."""
    unknown = set(body.keys or []) - set(STARTER_TAGS)
    if unknown:
        raise HTTPException(400, f"Unknown starter tag: {', '.join(sorted(unknown))}")
    return tagging.add_starter_tags(conn, body.keys)


@router.get("/tags/dictionary")
def merchant_list(conn: sqlite3.Connection = Depends(get_conn)):
    """The built-in merchant list, by category, and which of YOUR tags each category files into (or none)."""
    out = []
    for key, entries in DICTIONARY.items():
        tag_id = tagging.resolve_role(conn, key)
        tag = conn.execute("SELECT name, color FROM tags WHERE id = ?", (tag_id,)).fetchone() if tag_id else None
        out.append({"key": key, "category": STARTER_TAGS[key][0], "tag": dict(tag) if tag else None,
                    "merchants": [e.split("|")[0].strip() for e in entries]})
    return {"items": out, "total": sum(len(i["merchants"]) for i in out)}


# ---- auto-tag rules ---------------------------------------------------------

RULE_SQL = ("SELECT r.id, r.pattern, r.tag_id, r.priority, g.name AS tag_name, g.color AS tag_color "
            "FROM tag_rules r JOIN tags g ON g.id = r.tag_id")


@router.get("/rules")
def list_rules(conn: sqlite3.Connection = Depends(get_conn)):
    return [dict(r) for r in conn.execute(RULE_SQL + " ORDER BY r.priority DESC, r.pattern")]


@router.post("/rules", status_code=201)
def create_rule(body: RuleIn, conn: sqlite3.Connection = Depends(get_conn)):
    require_tag(conn, body.tag_id)
    res = tagging.add_rule(conn, body.pattern, body.tag_id, body.priority)
    if res["status"] in ("exists", "conflict"):
        raise HTTPException(409, res["note"])      # never a duplicate rule
    conn.commit()
    return dict(conn.execute(RULE_SQL + " WHERE r.id = ?", (res["rule_id"],)).fetchone())


@router.put("/rules/{rule_id}")
def update_rule(rule_id: int, body: RuleIn, conn: sqlite3.Connection = Depends(get_conn)):
    require_tag(conn, body.tag_id)
    cur = conn.execute("UPDATE tag_rules SET pattern = ?, tag_id = ?, priority = ? WHERE id = ?",
                       (body.pattern, body.tag_id, body.priority, rule_id))
    if cur.rowcount == 0:
        raise HTTPException(404, "Rule not found")
    conn.commit()
    return dict(conn.execute(RULE_SQL + " WHERE r.id = ?", (rule_id,)).fetchone())


@router.delete("/rules/{rule_id}", status_code=204)
def delete_rule(rule_id: int, conn: sqlite3.Connection = Depends(get_conn)):
    if conn.execute("DELETE FROM tag_rules WHERE id = ?", (rule_id,)).rowcount == 0:
        raise HTTPException(404, "Rule not found")
    conn.commit()


@router.post("/rules/apply")
def apply_rules(conn: sqlite3.Connection = Depends(get_conn)):
    """Run your rules, then the built-in merchant list, over transactions that have no tag. Never changes a tag
    that is already set, and never guesses a category for a payment to a person."""
    ctx = tagging.TaggingContext(conn)
    untagged = conn.execute("SELECT id, payee, merchant_clean FROM transactions WHERE tag_id IS NULL AND merged_into_id IS NULL").fetchall()
    by_rule = by_dictionary = 0
    for r in untagged:
        d = ctx.decide(r["payee"], r["merchant_clean"])
        if d.tag_id is not None:
            conn.execute("UPDATE transactions SET tag_id = ?, tag_source = ?, tag_detail = ? WHERE id = ? AND tag_id IS NULL",
                         (d.tag_id, d.source, d.detail, r["id"]))
            by_rule += d.source == "rule"
            by_dictionary += d.source == "dictionary"
    conn.commit()
    tagged = by_rule + by_dictionary
    return {"tagged": tagged, "by_rule": by_rule, "by_dictionary": by_dictionary, "still_untagged": len(untagged) - tagged}

