app/sources/aa_json.py:
"""Account-Aggregator-style JSON file import. PURE parsing: file text -> transactions + rejected items. No database, no network.

This reads a FILE the user already has. It is NOT a connection to an Account Aggregator, and Paisa never holds consents or keys.
Layout (modelled on the Sahamati/ReBIT deposit "FIData" shape; see docs/samples/aa-sample.json and docs/FUTURE_INTEGRATIONS.md):

    { "ver": "1.1.2",
      "accounts": [                       // or a single {"account": {...}}, or a bare list of accounts
        { "maskedAccNumber": "XXXXXX1234", "type": "deposit",
          "summary": { "currentBalance": "24310.50", "currency": "INR" },
          "transactions": { "startDate": "2026-09-01", "endDate": "2026-09-30",
            "transaction": [ { "txnId": "T1", "type": "DEBIT", "mode": "UPI", "amount": "512.00", "currentBalance": "24310.50",
                               "transactionTimestamp": "2026-09-04T20:41:00+05:30", "valueDate": "2026-09-04",
                               "narration": "UPI/DR/427891234567/SWIGGY/okaxis/Payment", "reference": "427891234567" } ] } } ] }

Keys are matched ignoring case. Accounts are masked to their last four digits. Anything unreadable is listed with the reason, never guessed.
"""
import json
import re
from datetime import datetime
from decimal import Decimal, InvalidOperation

MAX_TXNS = 20_000
KIND = {"debit": "debit", "dr": "debit", "d": "debit", "credit": "credit", "cr": "credit", "c": "credit"}
MODES = {"upi": "upi", "card": "card", "atm": "other", "cash": "cash", "neft": "bank_transfer", "imps": "bank_transfer", "rtgs": "bank_transfer",
         "ft": "bank_transfer", "others": "other", "other": "other", "cheque": "bank_transfer", "ecs": "bank_transfer"}


class AAError(Exception):
    pass


def _get(d: dict, *names):
    low = {str(k).lower(): v for k, v in d.items()}
    for n in names:
        if n.lower() in low:
            return low[n.lower()]
    return None


def mask(acc) -> str | None:
    digits = re.sub(r"\D", "", str(acc or ""))
    return ("XXXX" + digits[-4:]) if len(digits) >= 4 else None


def _money(v) -> int | None:
    try:
        d = Decimal(str(v).replace(",", "").strip())
    except (InvalidOperation, AttributeError):
        return None
    return int((d * 100).to_integral_value())


def _when(ts, value_date) -> str | None:
    for raw in (ts, value_date):
        if not raw:
            continue
        s = str(raw).strip().replace("Z", "")
        try:
            return datetime.fromisoformat(s).replace(tzinfo=None, microsecond=0).isoformat(timespec="seconds")
        except ValueError:
            pass
        for fmt in ("%Y-%m-%d", "%d-%m-%Y", "%d/%m/%Y"):
            try:
                return datetime.strptime(s[:10], fmt).isoformat(timespec="seconds")
            except ValueError:
                pass
    return None


def accounts_of(doc) -> list[dict]:
    if isinstance(doc, list):
        return [a for a in doc if isinstance(a, dict)]
    if not isinstance(doc, dict):
        raise AAError("This isn't an account-aggregator style file: it should be a JSON object with an account list.")
    accs = _get(doc, "accounts")
    if isinstance(accs, list):
        return [a for a in accs if isinstance(a, dict)]
    acc = _get(doc, "account")
    if isinstance(acc, dict):
        return [acc]
    if _get(doc, "transactions") is not None:
        return [doc]
    raise AAError("No accounts found in this file. Expected an \"accounts\" list (see docs/samples/aa-sample.json).")


def parse(text: str) -> dict:
    """-> {"rows": [..], "rejected": [{"index", "reason"}], "accounts": [{"masked", "count", "balance_paise", "start", "end"}]}.
    Each row has the keys the import pipeline expects (date_time, paise, type, payee, ...)."""
    if len(text) > 5_000_000:
        raise AAError("That file is too large.")
    try:
        doc = json.loads(text)
    except ValueError:
        raise AAError("That file isn't valid JSON.")
    rows, rejected, summary = [], [], []
    n = 0
    for acc in accounts_of(doc):
        masked = mask(_get(acc, "maskedAccNumber", "maskedAccountNumber", "accountNumber", "accNumber")) or "account"
        tx_block = _get(acc, "transactions") or {}
        items = _get(tx_block, "transaction", "transactions") if isinstance(tx_block, dict) else tx_block
        if not isinstance(items, list):
            raise AAError(f"The {masked} account has no transaction list.")
        sm = _get(acc, "summary") or {}
        bal = _money(_get(sm, "currentBalance")) if isinstance(sm, dict) else None
        count = 0
        for i, t in enumerate(items, start=1):
            n += 1
            if n > MAX_TXNS:
                raise AAError("That file has more transactions than this version imports at once.")
            if not isinstance(t, dict):
                rejected.append({"index": n, "reason": "Not a transaction entry"})
                continue
            kind = KIND.get(str(_get(t, "type", "txnType", "drCr") or "").strip().lower())
            amount = _money(_get(t, "amount", "txnAmount"))
            when = _when(_get(t, "transactionTimestamp", "txnTimestamp", "timestamp"), _get(t, "valueDate", "txnDate"))
            if kind is None:
                rejected.append({"index": n, "reason": f"Can't tell debit from credit ('{_get(t, 'type')}')"})
            elif amount is None or amount <= 0:
                rejected.append({"index": n, "reason": f"Can't read the amount ('{_get(t, 'amount')}')"})
            elif when is None:
                rejected.append({"index": n, "reason": "Can't read the date"})
            else:
                narr = str(_get(t, "narration", "description", "remarks") or "").strip()
                ref = str(_get(t, "reference", "utr", "txnId", "transactionId") or "").strip() or None
                mode = str(_get(t, "mode") or "").strip().lower()
                rows.append({"date_time": when, "paise": amount, "type": kind, "narration": narr[:500], "reference_id": ref[:60] if ref else None,
                             "balance_after": _money(_get(t, "currentBalance", "balance")), "method": MODES.get(mode, "bank_transfer"),
                             "account": masked, "index": n})
                count += 1
        summary.append({"masked": masked, "count": count, "balance_paise": bal,
                        "start": _get(tx_block, "startDate") if isinstance(tx_block, dict) else None, "end": _get(tx_block, "endDate") if isinstance(tx_block, dict) else None})
    if not rows and not rejected:
        raise AAError("The file has accounts but no transactions in it.")
    return {"rows": rows, "rejected": rejected, "accounts": summary}

app/sources/service.py:
"""Preview and commit for pasted SMS and aggregator-style files, through the same import path CSV uses.

Both are two steps: a PREVIEW that writes nothing (what was understood, what was left out and why, which are duplicates), then a COMMIT that
adds what the user ticked as one import batch (viewable and deletable in Settings → Data like any import).
"""
import sqlite3
from datetime import date, datetime

from .. import importer
from . import aa_json, sms

SMS_SOURCE = "sms-paste"


class SourceError(Exception):
    def __init__(self, message: str, status: int = 400):
        super().__init__(message)
        self.status = status


def _sms_tx(p: sms.Parsed) -> dict:
    who = p.counterparty.strip()
    if who and who == who.lower():
        who = who.title()                       # a UPI handle like "swiggy" reads better as "Swiggy"
    note = f"Pasted SMS ({p.bank})" + (f" · account {p.account_tail}" if p.account_tail else "")
    return {"date_time": f"{p.date}T{p.time or '00:00:00'}", "paise": p.paise, "type": p.type, "payee": importer.clean_payee(who) if who else "Unknown",
            "payment_method": p.method, "note": note, "reference_id": p.reference, "balance_after": p.balance_paise, "txn_status": "success",
            "merchant_raw": who[:500] or None, "merchant_clean": importer.clean_payee(who) if who else None, "warnings": list(p.warnings)}


def _sms_results(conn: sqlite3.Connection, text: str, today: date) -> tuple[list[dict], list[sms.Parsed]]:
    if len(text) > 200_000:
        raise SourceError("That is more text than one paste can hold. Paste fewer messages at a time.")
    parsed = sms.parse_many(text, today)
    results = []
    for i, p in enumerate(parsed, start=1):
        if p.ok:
            results.append({"line": i, "status": "new", "reason": "", "tx": _sms_tx(p), "similar": 0})
        else:
            results.append({"line": i, "status": "invalid", "reason": p.reason, "tx": None, "similar": 0})
    return importer.classify(conn, results), parsed


def sms_preview(conn: sqlite3.Connection, text: str, today: date) -> dict:
    results, parsed = _sms_results(conn, text, today)
    items = []
    for r, p in zip(results, parsed):
        base = {"index": r["line"], "status": r["status"], "reason": r["reason"], "bank": p.bank, "snippet": p.snippet}
        if r["tx"]:
            t = r["tx"]
            base.update(date=t["date_time"][:10], time=p.time, amount_paise=t["paise"], type=t["type"], payee=t["payee"], method=t["payment_method"],
                        reference=t["reference_id"], balance_paise=t["balance_after"], account=p.account_tail, warnings=t["warnings"], similar=r["similar"])
        else:
            base.update(kind=p.kind)
        items.append(base)
    counts = {s: sum(1 for i in items if i["status"] == s) for s in ("new", "duplicate", "invalid")}
    return {"items": items, "counts": counts, "total": len(items),
            "kept": "Only the fields shown (date, amount, direction, who, reference, balance and the last four account digits) are saved. The message text is not stored."}


def sms_commit(conn: sqlite3.Connection, text: str, today: date, include: list[int] | None = None) -> dict:
    results, _ = _sms_results(conn, text, today)
    if include is not None:
        keep = set(include)
        for r in results:
            if r["status"] == "new" and r["line"] not in keep:
                r["status"], r["reason"] = "duplicate", "You unticked it"
        results = [r for r in results if r["status"] != "duplicate" or r["reason"] != "You unticked it"]
    if not any(r["status"] == "new" for r in results):
        raise SourceError("Nothing to add: no new transactions were selected.")
    name = f"Pasted SMS {datetime.now():%Y-%m-%d %H:%M}"
    return importer.insert_new(conn, results, name, True, source=SMS_SOURCE, batch_name=name)


# ---- Account Aggregator style file ----------------------------------------------------------------------------------------

def _aa_results(conn: sqlite3.Connection, text: str) -> tuple[list[dict], dict]:
    try:
        parsed = aa_json.parse(text)
    except aa_json.AAError as e:
        raise SourceError(str(e))
    results = []
    for r in parsed["rows"]:
        payee = importer.clean_payee(r["narration"]) if r["narration"] else "Unknown"
        tx = {"date_time": r["date_time"], "paise": r["paise"], "type": r["type"], "payee": payee, "payment_method": r["method"],
              "note": f"Account file · account {r['account']}", "reference_id": r["reference_id"], "balance_after": r["balance_after"],
              "txn_status": "success", "merchant_raw": r["narration"] or None, "merchant_clean": importer.clean_payee(r["narration"]) if r["narration"] else None,
              "warnings": []}
        results.append({"line": r["index"], "status": "new", "reason": "", "tx": tx, "similar": 0})
    for r in parsed["rejected"]:
        results.append({"line": r["index"], "status": "invalid", "reason": r["reason"], "tx": None, "similar": 0, "raw": {}})
    results.sort(key=lambda r: r["line"])
    return importer.classify(conn, results), parsed


def aa_preview(conn: sqlite3.Connection, text: str) -> dict:
    results, parsed = _aa_results(conn, text)
    counts = {s: sum(1 for r in results if r["status"] == s) for s in ("new", "duplicate", "invalid")}
    shown = [r for r in results if r["status"] == "invalid"][:30] + [r for r in results if r["status"] != "invalid"][:70]
    rows = []
    for r in sorted(shown, key=lambda r: r["line"]):
        t = r["tx"]
        rows.append({"index": r["line"], "status": r["status"], "reason": r["reason"],
                     **({"date": t["date_time"][:10], "amount_paise": t["paise"], "type": t["type"], "payee": t["payee"], "reference": t["reference_id"]} if t else {})})
    return {"counts": counts, "total": len(results), "rows": rows, "accounts": parsed["accounts"],
            "note": "This is a file import. Nothing was fetched from any bank or aggregator."}


def aa_commit(conn: sqlite3.Connection, text: str, filename: str) -> dict:
    results, _ = _aa_results(conn, text)
    if not any(r["status"] == "new" for r in results):
        raise SourceError("Nothing new to add: every transaction in this file is already in Paisa or couldn't be read.")
    base = importer.source_name(filename).split(":", 1)[1]
    return importer.insert_new(conn, results, filename, True, source=f"aa-file:{base}", batch_name=base)

app/sources/sms.py:
"""SMS paste parser: bank alert text -> a transaction, or a plain reason it was left out. PURE: no database, no network.

Only text the user pastes is ever read. The parser:
  * REJECTS one-time-password messages and promotional messages. They are not echoed back, not parsed and not stored.
  * MASKS account numbers to their last four digits (XXXX1234) before anything is shown or saved. The message body itself is never stored;
    only the extracted fields (date, amount, direction, counterparty, reference, balance) and the masked account tail are kept.
  * NEVER guesses: a message with no amount, no direction or no readable date becomes "not understood", with the reason.
Layouts covered: HDFC, SBI, ICICI, Axis, Kotak and a generic fallback (the generic rules read most other banks' alerts too).
Every example in the tests and the sample file is SYNTHETIC; no real account, name or reference appears anywhere.
"""
import re
from dataclasses import dataclass, field
from datetime import date, datetime
from decimal import Decimal

MONTHS = {m: i for i, m in enumerate(["jan", "feb", "mar", "apr", "may", "jun", "jul", "aug", "sep", "oct", "nov", "dec"], start=1)}

BANKS = [  # label, words that identify it in the message
    ("HDFC Bank", ("hdfc",)), ("SBI", ("sbi", "state bank")), ("ICICI Bank", ("icici",)), ("Axis Bank", ("axis",)), ("Kotak Bank", ("kotak",)),
]

OTP_WORDS = re.compile(r"\botp\b|one[\s-]*time[\s-]*(?:password|pin)|verification code|\bpasscode\b|\bdo not share\b|\bnever share\b|\b(?:cvv|mpin|upi pin)\b", re.I)
PROMO_WORDS = re.compile(r"\b(?:offer|cashback offer|pre[\s-]*approved|apply now|limited period|limited time|congratulations|you(?:'ve| have) won|"
                         r"win\b|lucky|free\b|discount|coupon|emi offer|upgrade|reward points|loan of|call now|click (?:here|to)|download the app|t&c|terms apply)\b", re.I)
DEBIT_WORDS = r"debited|debit|spent|sent|paid|withdrawn|withdrawal|purchase|payment of|transferred"
CREDIT_WORDS = r"credited|credit|received|deposited|deposit|refund(?:ed)?"
DIRECTION = re.compile(rf"\b(?P<d>{DEBIT_WORDS})\b|\b(?P<c>{CREDIT_WORDS})\b", re.I)
AMOUNT = re.compile(r"(?:rs\.?|inr|₹)\s*([\d,]+(?:\.\d{1,2})?)", re.I)
BALANCE = re.compile(r"(?:avl\.?|available|avail\.?|bal(?:ance)?|clear bal)[^\d₹]{0,25}(?:rs\.?|inr|₹)?\s*([\d,]+(?:\.\d{1,2})?)", re.I)
ACCOUNT = re.compile(r"(?:a/c|ac(?:ct)?\.?|account|card)(?:\s*(?:no\.?|number|ending|\bx+))?\s*[:\-]?\s*(?:[xX*•]+\s*)?(\d{3,})", re.I)
REFERENCE = re.compile(r"(?:upi(?:\s*ref(?:erence)?)?(?:\s*no\.?)?|ref(?:erence)?(?:\s*no\.?)?|refno|utr|rrn|txn(?:\s*id)?)\s*[:\-#/]?\s*(\d{9,16})", re.I)
UPI_PATH = re.compile(r"UPI/(?:P2[AMP]|DR|CR)/(\d{9,16})/([^/\s]+)", re.I)
DATE_PATTERNS = [
    re.compile(r"\b(\d{1,2})[-/](\d{1,2})[-/](\d{4}|\d{2})\b"),
    re.compile(r"\b(\d{1,2})[-\s]?([A-Za-z]{3})[a-z]*[-\s,]*(\d{4}|\d{2})\b"),
]
TIME = re.compile(r"\b(\d{1,2}):(\d{2})(?::(\d{2}))?\b")
LONG_DIGITS = re.compile(r"\d{8,}")


@dataclass
class Parsed:
    ok: bool
    bank: str = "Generic"
    reason: str = ""
    kind: str = ""                         # when not ok: otp | promo | not_transaction | no_amount | no_direction
    date: str = ""                         # YYYY-MM-DD
    time: str | None = None                # HH:MM:SS when the message has one
    paise: int = 0
    type: str = ""                         # debit | credit
    counterparty: str = ""
    reference: str | None = None
    balance_paise: int | None = None
    account_tail: str | None = None        # 'XXXX1234'
    method: str = "bank_transfer"
    warnings: list[str] = field(default_factory=list)
    snippet: str = ""                      # safe-to-show text: account numbers masked, OTP messages not echoed


def to_paise(s: str) -> int:
    return int((Decimal(s.replace(",", "")) * 100).to_integral_value())


def mask_account(digits: str) -> str:
    return "XXXX" + digits[-4:] if len(digits) >= 4 else "XX" + digits


def safe_snippet(text: str, limit: int = 140) -> str:
    """The message with account/card numbers reduced to their last four digits and other long digit runs partly hidden."""
    t = " ".join(text.split())
    t = ACCOUNT.sub(lambda m: m.group(0)[: m.start(1) - m.start(0)].rstrip("xX*• ") + " " + mask_account(m.group(1)), t)
    t = LONG_DIGITS.sub(lambda m: m.group(0) if len(m.group(0)) in range(9, 17) and "ref" in t[max(0, m.start() - 12):m.start()].lower() else "••••" + m.group(0)[-4:], t)
    return t[:limit] + ("…" if len(t) > limit else "")


def detect_bank(text: str) -> str:
    low = re.sub(r"\S+@\S+", " ", text.lower())          # a UPI handle like name@okicici says nothing about the sender's bank
    for label, words in BANKS:
        if any(w in low for w in words):
            return label
    return "Generic"


def _year(y: str) -> int:
    n = int(y)
    return 2000 + n if n < 100 else n


def find_date(text: str, today: date) -> tuple[date | None, str | None]:
    """The transaction date in the message, day first. Returns (date, problem)."""
    for pat in DATE_PATTERNS:
        for m in pat.finditer(text):
            try:
                if pat is DATE_PATTERNS[0]:
                    d = date(_year(m.group(3)), int(m.group(2)), int(m.group(1)))
                else:
                    mon = MONTHS.get(m.group(2).lower()[:3])
                    if not mon:
                        continue
                    d = date(_year(m.group(3)), mon, int(m.group(1)))
            except ValueError:
                continue
            if d > today:
                return None, f"The date {d.isoformat()} is in the future"
            return d, None
    return None, None


def _counterparty(text: str, direction: str) -> str:
    """Who the money went to / came from, as written in the message."""
    m = UPI_PATH.search(text)
    if m:
        return m.group(2).strip(".;,:")
    m = re.search(r"\bVPA\s+([\w.\-]+@[\w.\-]+)", text, re.I) or re.search(r"\b(?:to|from|by)\s+([\w.\-]+@[\w.\-]+)", text, re.I)
    if m:
        return m.group(1).split("@")[0].replace(".", " ").replace("_", " ")
    word = r"(?:to|at)" if direction == "debit" else r"(?:from|by)"
    m = re.search(rf"\b(?:trf|transfer(?:red)?)?\s*{word}\s+(?!a/c|acct|account|your|vpa\b)([A-Za-z][\w&.\- ]{{1,40}}?)(?=\s+(?:on|ref|upi|via|at|using|vpa|avl|bal|not|if|call|\(|\.|;|,|-)|[.;,(]|$)", text, re.I)
    if m:
        return m.group(1).strip()
    m = re.search(r";\s*([A-Za-z][\w&.\- ]{1,40}?)\s+(?:credited|debited)", text, re.I)      # ICICI: "debited ...; SWIGGY credited"
    if m:
        return m.group(1).strip()
    m = re.search(r"a/c\s+([A-Za-z][\w&.\- ]{1,40}?)\s+(?:credited|debited)", text, re.I)    # SBI: "and a/c SWIGGY credited"
    if m:
        return m.group(1).strip()
    m = re.search(r"info[:\-]\s*([A-Za-z][\w&.\- /]{1,40}?)(?=[.;,]|$|\s{2})", text, re.I)
    if m:
        return m.group(1).strip()
    return ""


def parse_one(text: str, today: date) -> Parsed:
    raw = text.strip()
    if not raw:
        return Parsed(False, reason="Empty message", kind="empty")
    bank = detect_bank(raw)
    if OTP_WORDS.search(raw) and not re.search(r"\b(?:debited|credited|spent|withdrawn)\b", raw, re.I):
        return Parsed(False, bank, "A one-time-password message. Paisa skips these: it was not read or kept.", "otp", snippet="(not shown)")
    if OTP_WORDS.search(raw):
        return Parsed(False, bank, "Mentions a one-time password or PIN, so it was skipped to be safe. It was not read or kept.", "otp", snippet="(not shown)")
    amounts = [m for m in AMOUNT.finditer(raw)]
    verbs = list(DIRECTION.finditer(raw))
    if PROMO_WORDS.search(raw) and not verbs:
        return Parsed(False, bank, "Looks like a promotional message, not a transaction.", "promo", snippet=safe_snippet(raw, 60))
    if not amounts:
        return Parsed(False, bank, "No rupee amount found.", "no_amount", snippet=safe_snippet(raw))
    if not verbs:
        why = "Looks like a promotional message, not a transaction." if PROMO_WORDS.search(raw) else "Can't tell if money went out or came in."
        return Parsed(False, bank, why, "promo" if PROMO_WORDS.search(raw) else "no_direction", snippet=safe_snippet(raw))
    first = verbs[0]
    direction = "debit" if first.group("d") else "credit"
    # the transaction amount is the first amount that is not a balance figure
    bal = BALANCE.search(raw)
    bal_span = bal.span(1) if bal else None
    amt = next((m for m in amounts if not (bal_span and bal_span[0] <= m.start(1) <= bal_span[1])), None)
    if amt is None:
        return Parsed(False, bank, "Only a balance figure found, no transaction amount.", "no_amount", snippet=safe_snippet(raw))
    try:
        paise = to_paise(amt.group(1))
    except Exception:
        return Parsed(False, bank, "The amount couldn't be read.", "no_amount", snippet=safe_snippet(raw))
    if paise <= 0:
        return Parsed(False, bank, "The amount is zero.", "no_amount", snippet=safe_snippet(raw))

    warnings: list[str] = []
    d, problem = find_date(raw, today)
    if problem:
        return Parsed(False, bank, problem + ", so it wasn't added.", "bad_date", snippet=safe_snippet(raw))
    if d is None:
        d = today
        warnings.append("The message has no date, so the day you pasted it was used")
    tm = TIME.search(raw)
    time = None
    if tm:
        h, mi, s = int(tm.group(1)), int(tm.group(2)), int(tm.group(3) or 0)
        if h < 24 and mi < 60 and s < 60:
            time = f"{h:02d}:{mi:02d}:{s:02d}"

    ref = None
    m = UPI_PATH.search(raw) or REFERENCE.search(raw)
    if m:
        ref = m.group(1)
    acc = ACCOUNT.search(raw)
    tail = mask_account(acc.group(1)) if acc else None
    who = _counterparty(raw, direction)
    if not who:
        warnings.append("Couldn't tell who the other party was")
    method = "upi" if re.search(r"\bupi\b|\bvpa\b", raw, re.I) else "card" if re.search(r"\bcard\b|\bpos\b", raw, re.I) else "bank_transfer"
    return Parsed(True, bank, "", "", d.isoformat(), time, paise, direction, who, ref,
                  to_paise(bal.group(1)) if bal else None, tail, method, warnings, safe_snippet(raw))


def split_messages(text: str) -> list[str]:
    """Several pasted messages -> one string each. Blank lines separate messages; if there are none, each line that looks like an alert is its own message."""
    text = text.replace("\r\n", "\n").strip()
    if not text:
        return []
    blocks = [b.strip() for b in re.split(r"\n\s*\n", text) if b.strip()]
    if len(blocks) == 1 and "\n" in blocks[0]:
        lines = [ln.strip() for ln in blocks[0].split("\n") if ln.strip()]
        if sum(1 for ln in lines if AMOUNT.search(ln) and DIRECTION.search(ln)) >= 2:
            return lines
    return [" ".join(b.split()) for b in blocks]


def parse_many(text: str, today: date, limit: int = 200) -> list[Parsed]:
    return [parse_one(m, today) for m in split_messages(text)[:limit]]


# Synthetic examples used by the "Use sample messages" button, the tests and docs/samples/sms-sample.txt. None is a real message.
SAMPLE = """HDFC Bank: Rs.512.00 debited from a/c XX1234 on 04-10-26 to VPA swiggy@okaxis (UPI Ref No 427891234567). Avl bal Rs.24,310.50. Not you? Call the number on your card.

Dear SBI Customer, your a/c XXXXXX5678 is debited by Rs.1,250.00 on 05Oct26 trf to ZEPTO Refno 427891234999. Available balance Rs.8,420.00

ICICI Bank Acct XX234 debited for Rs 899.00 on 06-Oct-26; BIGBASKET credited. UPI:427891235001. Call the number on the back of your card for dispute.

Rs 85,000.00 credited to Axis Bank A/c no. XX9012 on 01-10-26 by ACME TECHNOLOGIES SALARY. UPI/CR/427891235222/ACME. Avl Bal Rs 1,09,500.00

Sent Rs.250.00 from Kotak Bank AC X3456 to chaipoint@okicici on 07-10-26. UPI Ref 427891235333.

Your OTP for the transaction is 482913. Do not share it with anyone. Valid for 10 minutes.

Congratulations! You are pre-approved for a personal loan of Rs 5,00,000. Apply now and get a limited time offer on interest.

Hello, your parcel will arrive tomorrow between 10 and 12."""

app/sts_service.py:
"""Safe-to-spend service: load your data, run the pure calculation (safe_to_spend.py), handle the balance and alerts.

`today` is always passed in (the browser sends the device's local date; on a computer the server clock is the
device's clock), so every result is reproducible.
"""
import sqlite3
from datetime import date, timedelta

from . import safe_to_spend as sts
from .routers.budgets import budget_items
from .storage import get_settings, set_settings


class StsError(Exception):
    def __init__(self, message: str, status: int = 400):
        super().__init__(message)
        self.status = status


def parse_today(value: str | None) -> date:
    if not value:
        return date.today()
    try:
        return date.fromisoformat(value)
    except ValueError:
        raise StsError("today must be a date like 2026-03-14")


# ---- settings and the balance basis --------------------------------------------------

def load_settings(conn: sqlite3.Connection) -> tuple[sts.Settings, dict]:
    raw = get_settings(conn)
    return sts.Settings(
        month_start_day=raw["month_start_day"], emergency_reserve=raw["emergency_reserve"], include_goals=raw["sts_include_goals"],
        goal_mode=raw["sts_goal_mode"], goal_lump_day=raw["goal_lump_day"], include_nonessential=raw["sts_include_nonessential"],
        stale_days=raw["balance_stale_days"], low_balance_threshold=raw["low_balance_threshold"]), raw


def load_basis(raw: dict) -> sts.Basis | None:
    if raw["starting_balance"] is None or not raw["starting_balance_date"]:
        return None
    return sts.Basis(raw["starting_balance"], date.fromisoformat(raw["starting_balance_date"]), raw["starting_balance_source"] or "entered")


def import_balance_candidate(conn: sqlite3.Connection) -> dict | None:
    """The newest balance printed on an imported statement row (a statement figure, not a live bank balance)."""
    r = conn.execute(
        "SELECT t.id, t.date_time, t.balance_after, b.filename FROM transactions t LEFT JOIN import_batches b ON b.id = t.import_batch_id"
        " WHERE t.balance_after IS NOT NULL AND t.merged_into_id IS NULL AND t.txn_status = 'success'"
        " ORDER BY t.date_time DESC, t.id DESC LIMIT 1").fetchone()
    if not r:
        return None
    return {"tx_id": r["id"], "as_of": r["date_time"][:10], "balance_paise": r["balance_after"], "source": f"import:{r['filename'] or 'statement'}"}


def set_balance(conn: sqlite3.Connection, balance_paise: int, as_of: date, today: date, source: str = "entered") -> dict:
    """Make this the new basis. Transactions on or before `as_of` stop counting: they are assumed to be in the balance."""
    if as_of > today:
        raise StsError("The balance date can't be in the future")
    if balance_paise < 0:
        raise StsError("The balance can't be negative here (enter 0 if the account is empty)")
    out = set_settings(conn, {"starting_balance": balance_paise, "starting_balance_date": as_of.isoformat(), "starting_balance_source": source})
    _recon(conn)                                           # the opening-balance check depends on it
    return out


def use_import_balance(conn: sqlite3.Connection, today: date) -> dict:
    c = import_balance_candidate(conn)
    if not c:
        raise StsError("No imported statement has a balance column yet")
    return set_balance(conn, max(0, c["balance_paise"]), date.fromisoformat(c["as_of"]), today, c["source"])


def clear_balance(conn: sqlite3.Connection) -> None:
    set_settings(conn, {"starting_balance": None, "starting_balance_date": "", "starting_balance_source": ""})
    _recon(conn)


def _recon(conn: sqlite3.Connection) -> None:
    from . import recon_service          # imported here: recon_service also imports this module
    recon_service.refresh(conn)


# ---- loading the ledger and the plan -------------------------------------------------------

def _txs(conn: sqlite3.Connection, since: date) -> list[sts.Tx]:
    out = []
    for r in conn.execute("SELECT id, date_time, amount, type, payee, status, txn_status FROM transactions"
                          " WHERE merged_into_id IS NULL AND substr(date_time, 1, 10) >= ?", (since.isoformat(),)):
        try:
            day = date.fromisoformat(r["date_time"][:10])
        except ValueError:
            continue
        counts = r["status"] == "completed" and r["txn_status"] == "success"
        pending = not counts and (r["txn_status"] == "pending" or r["status"] == "pending")
        if counts or pending:                      # failed and reversed rows never move anything
            out.append(sts.Tx(r["id"], day, r["amount"], r["type"], r["payee"], counts, pending))
    return out


def _items(conn: sqlite3.Connection) -> tuple[list[sts.Item], list[sts.Item]]:
    bills, income = [], []
    for r in conn.execute("SELECT * FROM recurring_items WHERE active = 1 ORDER BY id"):
        it = sts.Item(r["id"], r["name"], r["amount"], r["cadence"], date.fromisoformat(r["next_due"]), bool(r["essential"]),
                      r["merchant"] or "", r["kind"], bool(r["include_in_estimate"]))
        (income if r["kind"] == "income" else bills).append(it)
    return bills, income


def load_inputs(conn: sqlite3.Connection, today: date) -> dict:
    settings, raw = load_settings(conn)
    basis = load_basis(raw)
    since = min(basis.day if basis else today, today - timedelta(days=75))
    bills, income = _items(conn)
    return dict(
        today=today, settings=settings, basis=basis, txs=_txs(conn, since), bills=bills, income=income,
        oneoffs=[sts.OneOff(r["id"], r["name"], r["amount"], date.fromisoformat(r["expected_date"]), bool(r["include_in_estimate"]), r["received_transaction_id"])
                 for r in conn.execute("SELECT * FROM expected_income WHERE active = 1 ORDER BY expected_date, id")],
        goals=[sts.Goal(r["id"], r["name"], r["monthly_contribution"], r["target_amount"], r["saved_amount"])
               for r in conn.execute("SELECT * FROM savings_goals WHERE active = 1 ORDER BY id")],
        marks={(r["item_id"], r["due_date"]): (r["state"], r["transaction_id"]) for r in conn.execute("SELECT * FROM bill_marks")})


def _with_rupees(obj):
    """Add a rupee twin for every `*_paise` integer (the paise stay: they are the exact values)."""
    if isinstance(obj, dict):
        out = {}
        for k, v in obj.items():
            out[k] = _with_rupees(v)
            if k.endswith("_paise") and isinstance(v, int):
                out[k[:-6]] = v / 100
        return out
    if isinstance(obj, list):
        return [_with_rupees(v) for v in obj]
    return obj


def estimate(conn: sqlite3.Connection, today: date) -> dict:
    """The full estimate for the screens: figures, how they were calculated, confidence, what's missing, alerts."""
    inputs = load_inputs(conn, today)
    from . import recon_service
    mismatch = recon_service.open_opening_mismatch(conn)     # an unresolved opening-balance difference lowers confidence
    result = sts.compute(**inputs, recon_notes=([f"The balance you entered differs from an imported statement by ₹{mismatch['difference_paise'] / 100:,.2f}. "
                                                 "Check it in Reconciliation."] if mismatch else []))
    if mismatch and result.get("confidence"):
        result["confidence"]["link"] = {"to": "/reconciliation", "label": "See the difference in Reconciliation"}
    raw = get_settings(conn)
    result["import_balance"] = import_balance_candidate(conn)
    result["settings"] = {
        "emergency_reserve_paise": raw["emergency_reserve"], "low_balance_threshold_paise": raw["low_balance_threshold"],
        "budget_alert_pct": raw["budget_alert_pct"], "month_start_day": raw["month_start_day"], "balance_stale_days": raw["balance_stale_days"],
        "include_goals": raw["sts_include_goals"], "goal_mode": raw["sts_goal_mode"], "goal_lump_day": raw["goal_lump_day"],
        "include_nonessential": raw["sts_include_nonessential"]}
    result["alerts"] = alerts(conn, today, result=result)
    return _with_rupees(result)


def afford_check(conn: sqlite3.Connection, amount_paise: int, today: date) -> dict:
    if amount_paise <= 0:
        raise StsError("Enter an amount above zero")
    return _with_rupees(sts.afford(sts.compute(**load_inputs(conn, today)), amount_paise))


# ---- alerts: low balance and budgets, dismissible, not repeating until things change ------------------

def _dismissed(conn: sqlite3.Connection) -> set[str]:
    return {r["insight_key"] for r in conn.execute("SELECT insight_key FROM dismissed_insights WHERE kind = 'alert'")}


def _forget(conn: sqlite3.Connection, prefix: str) -> None:
    conn.execute("DELETE FROM dismissed_insights WHERE kind = 'alert' AND insight_key LIKE ?", (prefix + "%",))


def alerts(conn: sqlite3.Connection, today: date, *, result: dict | None = None, include_dismissed: bool = False) -> list[dict]:
    """Why each alert fired is in `why`. Dismissing one hides it; it comes back only if the situation gets worse
    (a new severity, a new month, or after the problem went away and returned)."""
    from .trustledger import inr
    result = result or sts.compute(**load_inputs(conn, today))
    raw = get_settings(conn)
    gone = _dismissed(conn)
    out: list[dict] = []

    low = result.get("low_balance") or {}
    thr, funds = low.get("threshold_paise", 0), low.get("funds_paise", 0)
    if result.get("has_balance") and thr > 0 and funds < thr:
        sev = "negative" if funds <= 0 else "critical" if funds * 2 < thr else "low"
        out.append({"key": f"alert:low_balance:{sev}", "kind": "low_balance", "severity": sev, "title": "Low estimated balance",
                    "why": (f"Your estimated funds after pending payments are {inr(funds)}, below your alert level of {inr(thr)}. "
                            "This is an estimate from Paisa's data, not your bank balance. You can change the level in the Safe-to-Spend settings."),
                    "link": "/budgets"})
    else:
        _forget(conn, "alert:low_balance")      # the problem went away: a later return must alert again

    pct = raw["budget_alert_pct"]
    month = today.isoformat()[:7]
    for b in budget_items(conn, month, pct)["items"]:
        key_base = f"alert:budget:{b['tag_id']}:{month}"
        if b["level"] == "ok":
            _forget(conn, key_base)
            continue
        over = b["level"] == "over"
        out.append({"key": f"{key_base}:{b['level']}", "kind": "budget", "severity": b["level"], "tag_id": b["tag_id"],
                    "title": f"{b['tag_name']} budget {'is over' if over else 'is close to its limit'}",
                    "why": (f"You have spent {inr(int(round(b['spent'] * 100)))} of your {inr(int(round(b['limit'] * 100)))} {b['tag_name']} budget for {month} "
                            f"({b['percent']}%). " + ("It is over the limit." if over else f"You asked to be warned at {pct}%.")),
                    "link": "/budgets"})
    conn.commit()
    for a in out:
        a["dismissed"] = a["key"] in gone
    return out if include_dismissed else [a for a in out if not a["dismissed"]]


def dismiss_alert(conn: sqlite3.Connection, key: str) -> None:
    if not key.startswith("alert:"):
        raise StsError("Not an alert key")
    conn.execute("INSERT OR IGNORE INTO dismissed_insights (insight_key, kind) VALUES (?, 'alert')", (key,))
    conn.commit()


def restore_alerts(conn: sqlite3.Connection) -> int:
    n = conn.execute("DELETE FROM dismissed_insights WHERE kind = 'alert'").rowcount
    conn.commit()
    return n

app/tagging.py:
"""Tagging: who decides a transaction's tag, in what order, and how to explain it afterwards.

PRECEDENCE (tested, never reordered):
    1. a tag you picked by hand            -> source 'user'
    2. your own rules                      -> source 'rule'        ("Your rule: swiggy")
    3. the built-in merchant list          -> source 'dictionary'  ("Built-in merchant list: Swiggy")
    4. otherwise                           -> left Untagged (source None)
The built-in list never overrides a tag you chose, never overrides a rule of yours, and never guesses a
category for a payment to an individual (it only knows named merchants).

User rules keep their documented meaning, "payee contains <text>" (a substring test, so your rule `ola` would
also match `Hola`: you wrote it, you control it). Only the built-in list is restricted to whole words.
"""
import sqlite3
from dataclasses import dataclass

from .autotag import match_rule
from .merchant import MATCHER
from .starter import STARTER_TAGS, role_for_name


@dataclass(frozen=True)
class TagDecision:
    tag_id: int | None
    source: str | None        # user | rule | dictionary | None
    detail: str | None = None


# ---- roles: which of your tags plays each starter role -------------------------

def resolve_role(conn: sqlite3.Connection, key: str) -> int | None:
    """The id of your tag for a starter role, or None. First the remembered mapping (survives renames), then a
    tag whose name is the starter name or a well-known equivalent. Never creates or edits anything."""
    row = conn.execute("SELECT tag_id FROM tag_roles WHERE starter_key = ?", (key,)).fetchone()
    if row:
        return row["tag_id"]
    for t in conn.execute("SELECT id, name FROM tags ORDER BY id"):
        if role_for_name(t["name"]) == key:
            return t["id"]
    return None


def starter_plan(conn: sqlite3.Connection) -> list[dict]:
    """What "Add starter tags" would do for each starter: create it, or reuse one you already have."""
    out = []
    for key, (name, color, _aliases) in STARTER_TAGS.items():
        tag_id = resolve_role(conn, key)
        existing = conn.execute("SELECT name FROM tags WHERE id = ?", (tag_id,)).fetchone() if tag_id else None
        out.append({"key": key, "name": name, "color": color, "action": "reuse" if existing else "create",
                    "existing": existing["name"] if existing else None})
    return out


def add_starter_tags(conn: sqlite3.Connection, keys: list[str] | None = None) -> dict:
    """Create the starter tags that are missing and REUSE the ones that already exist (same name or a known
    equivalent). Existing tags are never renamed, recoloured or duplicated. Safe to run twice."""
    created, reused = [], []
    for item in starter_plan(conn):
        if keys is not None and item["key"] not in keys:
            continue
        if item["action"] == "reuse":
            tag_id = resolve_role(conn, item["key"])
            reused.append({"starter": item["name"], "existing": item["existing"]})
        else:
            tag_id = conn.execute("INSERT INTO tags (name, color) VALUES (?, ?)", (item["name"], item["color"])).lastrowid
            created.append(item["name"])
        conn.execute("INSERT OR IGNORE INTO tag_roles (starter_key, tag_id) VALUES (?, ?)", (item["key"], tag_id))
    conn.commit()
    return {"created": created, "reused": reused}


def find_equivalent_tag(conn: sqlite3.Connection, name: str) -> int | None:
    """An existing tag with this name, or a well-known equivalent ('Transport' for 'Travel'). Used so that loading
    sample data or adding starters never creates a second tag meaning the same thing."""
    row = conn.execute("SELECT id FROM tags WHERE name = ? COLLATE NOCASE", (name,)).fetchone()
    if row:
        return row["id"]
    role = role_for_name(name)
    return resolve_role(conn, role) if role else None


# ---- the decision ----------------------------------------------------------------

class TaggingContext:
    """Loads rules, roles and remembered renames once, then decides tags for many transactions quickly."""

    def __init__(self, conn: sqlite3.Connection):
        self.conn = conn
        self.rules = [(r["pattern"], r["tag_id"]) for r in conn.execute(
            "SELECT pattern, tag_id FROM tag_rules ORDER BY priority DESC, id DESC")]
        self.renames = {r["key"]: r["name"] for r in conn.execute("SELECT key, name FROM merchant_renames")}
        self._roles: dict[str, int | None] = {}

    def role_tag(self, key: str) -> int | None:
        if key not in self._roles:
            self._roles[key] = resolve_role(self.conn, key)
        return self._roles[key]

    def decide(self, payee: str, merchant_clean: str | None = None) -> TagDecision:
        """Your rules first, then the built-in list. (A hand-picked tag is handled by the caller: it never gets here.)"""
        for name in (payee, merchant_clean):
            if name:
                hit = match_rule(name, self.rules)
                if hit:
                    return TagDecision(hit[0], "rule", hit[1])
        found = MATCHER.match(payee, merchant_clean)
        if found:
            tag_id = self.role_tag(found[0])
            if tag_id:
                return TagDecision(tag_id, "dictionary", found[1])
        return TagDecision(None, None)

    def display_name(self, merchant_clean: str) -> str:
        """The name you asked Paisa to remember for this merchant, else the cleaned name."""
        return self.renames.get(merchant_clean.strip().casefold(), merchant_clean)


def user_decision(detail: str | None = None) -> TagDecision:
    """A tag the user chose themselves (the strongest source)."""
    return TagDecision(None, "user", detail)


# ---- explaining a tag ---------------------------------------------------------

def tag_origin(source: str | None, detail: str | None, has_tag: bool) -> dict:
    """How a transaction got its tag, in words, for the detail screen."""
    if not has_tag:
        return {"source": None, "label": "Untagged", "detail": None}
    if source == "user":
        return {"source": "user", "label": "You" + (f" ({detail})" if detail else ""), "detail": detail}
    if source == "rule":
        return {"source": "rule", "label": f"Your rule: “{detail}”", "detail": detail}
    if source == "dictionary":
        return {"source": "dictionary", "label": f"Built-in merchant list: {detail}", "detail": detail}
    if source == "legacy":
        return {"source": "legacy", "label": "Set before Paisa recorded how (by you or by a rule)", "detail": None}
    return {"source": source, "label": "Unknown", "detail": detail}


# ---- rules without duplicates ---------------------------------------------------

def add_rule(conn: sqlite3.Connection, pattern: str, tag_id: int, priority: int = 0, *, is_sample: int = 0,
             skip_if_covered: bool = False, update_if_conflict: bool = False) -> dict:
    """Create a rule unless it would duplicate one. Returns {"status", "rule_id", "note"}:
        exists   a rule with this pattern and tag is already there (nothing added)
        updated  a rule with this pattern pointed at another tag and `update_if_conflict` was set (tag changed)
        conflict a rule with this pattern points at another tag (nothing changed; caller decides)
        covered  (only if `skip_if_covered`) an existing broader rule already gives this tag
        created  a new rule was added
    Patterns compare case-insensitively."""
    pattern = pattern.strip()
    same = conn.execute("SELECT id, tag_id FROM tag_rules WHERE pattern = ? COLLATE NOCASE", (pattern,)).fetchone()
    if same and same["tag_id"] == tag_id:
        return {"status": "exists", "rule_id": same["id"], "note": f"A rule for “{pattern}” already exists."}
    if same:
        old = conn.execute("SELECT name FROM tags WHERE id = ?", (same["tag_id"],)).fetchone()["name"]
        if update_if_conflict:
            conn.execute("UPDATE tag_rules SET tag_id = ? WHERE id = ?", (tag_id, same["id"]))
            return {"status": "updated", "rule_id": same["id"], "old_tag_id": same["tag_id"],
                    "note": f"Your rule “{pattern}” used to tag as {old}; it now uses the new tag."}
        return {"status": "conflict", "rule_id": same["id"], "note": f"A rule for “{pattern}” already tags as {old}."}
    if skip_if_covered:
        rules = [(r["pattern"], r["tag_id"]) for r in conn.execute("SELECT pattern, tag_id FROM tag_rules ORDER BY priority DESC, id DESC")]
        hit = match_rule(pattern, rules)
        if hit and hit[0] == tag_id:
            return {"status": "covered", "rule_id": None, "note": f"Your rule “{hit[1]}” already covers this."}
    cur = conn.execute("INSERT INTO tag_rules (pattern, tag_id, priority, is_sample) VALUES (?, ?, ?, ?)",
                       (pattern, tag_id, priority, is_sample))
    return {"status": "created", "rule_id": cur.lastrowid, "note": f"Created a rule: “{pattern}”."}

app/trustledger.py:
"""TrustLedger: decide how much each transaction can be trusted, and find what needs a human look.

PURE FUNCTIONS. This module never touches the database: `evaluate()` takes plain data in and returns
plain data out, so it is easy to test and behaves identically on a computer and inside the browser.
`trust_service.py` loads the ledger, calls `evaluate()`, and saves the result.

Principles (the ones the tests check):
* Deterministic: the same ledger + the same decisions always give the same answer, whatever order the
  rows arrive in. It can be re-run at any time.
* Evidence only. `verification_status` reflects evidence found in the data. Your own "Confirm" is a
  separate flag (`user_confirmed`) shown as "Confirmed by you"; it never turns into "Verified".
* Never override a human decision: confirmed rows, dismissed flags, merged duplicates, unlinked pairs
  and resolved/dismissed issues are inputs that the engine respects, not things it recomputes.
* Never silently drop money: a possible duplicate still counts in totals until YOU merge it. Each issue
  says how your total would change if you did.
* An SMS or a typed entry on its own is never enough for Verified.

The three statuses (see docs/DATA_MODEL.md):
  verified      evidence-backed: a bank-statement row with a reference ID, or the same reference ID
                found in two different sources with matching amount/date/direction.
  needs_review  conflicting or incomplete data, a possible duplicate, an unmatched refund...
  unconfirmed   not enough evidence either way (typed in, SMS only, pending, imported with no reference).
"""
import re
from bisect import bisect_left, bisect_right
from collections import defaultdict
from dataclasses import dataclass, field
from datetime import date, datetime
from difflib import SequenceMatcher

# ---- input / output shapes ---------------------------------------------------


@dataclass(frozen=True)
class Tx:
    """The fields of a transaction the engine looks at. Amounts are paise."""
    id: int
    date_time: str
    amount: int
    type: str                      # 'debit' | 'credit'
    payee: str
    source: str
    txn_status: str                # success | pending | failed | reversed
    status: str                    # completed | pending
    reference_id: str | None = None
    merchant_raw: str | None = None
    merchant_clean: str | None = None
    note: str = ""
    user_confirmed: bool = False
    user_confirmed_at: str | None = None
    flag_dismissed: bool = False
    merged_into_id: int | None = None
    import_notes: tuple[str, ...] = ()   # problems noticed while reading the import file

    @property
    def counts(self) -> bool:
        """Does this row add into spend/income totals? (mirrors storage.COUNTS_IN_REPORTS)"""
        return self.status == "completed" and self.txn_status == "success" and self.merged_into_id is None


@dataclass
class Verdict:
    status: str                    # verified | needs_review | unconfirmed
    reasons: list[str]
    link_kind: str | None = None   # refund | reversal (engine-made links only)
    linked_id: int | None = None


@dataclass
class Issue:
    key: str                       # stable fingerprint, e.g. 'dup:12:57'. A decided issue is never re-raised.
    kind: str                      # duplicate_same_ref | duplicate_possible | ref_conflict | refund_unmatched
                                   # | reversal_unmatched | incomplete
    tx_id: int
    other_id: int | None
    impact: int                    # paise change to the headline total if the suggested fix is applied
    details: dict = field(default_factory=dict)   # title, summary, evidence, suggestion, impact_text, ...
    state: str = "open"            # open | resolved | dismissed (from the saved decisions)


@dataclass
class Evaluation:
    verdicts: dict[int, Verdict]
    issues: list[Issue]


# ---- small helpers -----------------------------------------------------------

REFUND_WORDS = re.compile(r"\b(refund(?:ed)?|reversal|reversed|returned|chargeback)\b", re.I)
_NOISE = {"upi", "dr", "cr", "pay", "payment", "payments", "ltd", "pvt", "private", "limited", "india",
          "the", "online", "store", "stores", "order"}
_MONTHS = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"]


def inr(paise: int) -> str:
    """12345650 -> '₹1,23,456.50' (lakh/crore grouping), done on integers only."""
    rupees, ps = divmod(abs(paise), 100)
    s = str(rupees)
    if len(s) > 3:
        head, tail = s[:-3], s[-3:]
        parts = []
        while len(head) > 2:
            parts.insert(0, head[-2:])
            head = head[:-2]
        if head:
            parts.insert(0, head)
        s = ",".join(parts) + "," + tail
    return f"{'-' if paise < 0 else ''}₹{s}.{ps:02d}"


def parse_dt(raw: str) -> datetime | None:
    try:
        return datetime.fromisoformat(raw)
    except (TypeError, ValueError):
        return None


def fdate(raw: str) -> str:
    d = parse_dt(raw)
    return f"{d.day} {_MONTHS[d.month - 1]} {d.year}" if d else "an unreadable date"


def short_ref(ref: str) -> str:
    return ref[:4] + "…" if len(ref) > 5 else ref


def is_bank(source: str) -> bool:
    """Sources that are an actual bank/aggregator statement (as opposed to typed, SMS or Pay screen)."""
    return source.startswith("csv-import:") or source.startswith("aa-file")


def src_label(source: str) -> str:
    if source.startswith("csv-import:"):
        return f"import '{source.split(':', 1)[1]}'"
    if source.startswith("aa-file"):
        return "an account-aggregator file"
    return {"manual": "a typed entry", "sms-paste": "a pasted SMS", "pay-flow": "the Pay screen",
            "legacy": "an older entry", "sample": "sample data"}.get(source, source)


def kind_phrase(source: str) -> str:
    """'bank statement' for statement rows, else the plain label."""
    return "bank statement" if is_bank(source) else src_label(source)


def _norm(name: str) -> str:
    words = re.sub(r"[^a-z0-9]+", " ", REFUND_WORDS.sub(" ", name.casefold())).split()
    return " ".join(w for w in words if w not in _NOISE)


def _names(t: Tx) -> frozenset[str]:
    return frozenset(n for n in (_norm(t.payee), _norm(t.merchant_clean or "")) if n)


def _sim(a: frozenset[str], b: frozenset[str]) -> float:
    """0..1 similarity between two sets of normalised merchant names (best pair wins)."""
    best = 0.0
    for x in a:
        for y in b:
            if x == y:
                return 1.0
            if len(x) >= 4 and len(y) >= 4 and (x in y or y in x):
                best = max(best, 0.9)
            else:
                best = max(best, SequenceMatcher(None, x, y).ratio())
    return best


def _prefer(t: Tx) -> tuple:
    """Which of several copies to KEEP: a bank row first, then one with a reference, then the oldest."""
    return (0 if is_bank(t.source) else 1, 0 if t.reference_id else 1, t.id)


def _day(t: Tx) -> date | None:
    d = parse_dt(t.date_time)
    return d.date() if d else None


def _pair_key(a: int, b: int) -> str:
    return f"{min(a, b)}:{max(a, b)}"


def _what(t: Tx) -> str:
    return f"{inr(t.amount)} {'paid to' if t.type == 'debit' else 'received from'} {t.payee} on {fdate(t.date_time)}"


# ---- the engine ---------------------------------------------------------------

def evaluate(txs: list[Tx], *, nolinks: set[str] | frozenset[str] = frozenset(),
             issue_states: dict[str, str] | None = None, today: date | None = None) -> Evaluation:
    """Compute a verdict for every live (not merged-away) transaction, and the list of issues.

    `nolinks`      pair keys the user unlinked ('nolink:12:57'); those pairs are never linked again.
    `issue_states` saved state per issue key ('resolved' / 'dismissed'); decided issues stay decided.
    `today`        only used to spot dates in the future, passed in so results are reproducible.
    """
    issue_states = issue_states or {}
    today = today or date.today()
    live = sorted((t for t in txs if t.merged_into_id is None), key=lambda t: t.id)
    live_ids = {t.id for t in live}
    children: dict[int, list[Tx]] = defaultdict(list)       # merged-away copies, by the record they sit under
    for t in sorted(txs, key=lambda t: t.id):
        if t.merged_into_id in live_ids:
            children[t.merged_into_id].append(t)
    by_id = {t.id: t for t in live}
    names = {t.id: _names(t) for t in live}
    issues: list[Issue] = []
    info: dict[int, list[str]] = defaultdict(list)           # reasons that never change the status
    evidence: dict[int, list[str]] = defaultdict(list)       # reasons that count as evidence
    links: dict[int, tuple[str, int]] = {}                   # id -> (kind, other id)

    def add_issue(key, kind, tx_id, other_id, impact, details):
        issues.append(Issue(key, kind, tx_id, other_id, impact, details, issue_states.get(key, "open")))

    def blocked(a: Tx, b: Tx) -> bool:
        return f"nolink:{_pair_key(a.id, b.id)}" in nolinks

    # --- 1. reversals: a charge and the credit that undid it ---
    paired: set[int] = set()
    rev_credits = [t for t in live if t.txn_status == "reversed" and t.type == "credit"]
    for d in (t for t in live if t.txn_status == "reversed" and t.type == "debit"):
        best = None
        for c in rev_credits:
            if c.id in paired or c.amount != d.amount or blocked(d, c):
                continue
            same_ref = bool(d.reference_id and d.reference_id == c.reference_id)
            dd, dc = _day(d), _day(c)
            gap = (dc - dd).days if dd and dc else 999
            if not same_ref and (_sim(names[d.id], names[c.id]) < 0.6 or not 0 <= gap <= 7):
                continue
            rank = (0 if same_ref else 1, abs(gap), c.id)
            if best is None or rank < best[0]:
                best = (rank, c, same_ref)
        if best:
            _, c, same_ref = best
            paired |= {d.id, c.id}
            links[d.id], links[c.id] = ("reversal", c.id), ("reversal", d.id)
            why = "the same reference ID" if same_ref else "the same merchant and amount within a week"
            info[d.id].append(f"Reversed: the {inr(d.amount)} charge and the matching credit on {fdate(c.date_time)} cancel out "
                              f"({why}). Neither counts in your totals.")
            info[c.id].append(f"Reversal of the {inr(d.amount)} charge on {fdate(d.date_time)} ({why}). "
                              "Neither counts in your totals.")
    for t in live:
        if t.txn_status == "reversed" and t.id not in paired:
            add_issue(f"reversal:{t.id}", "reversal_unmatched", t.id, None, 0, {
                "title": "Marked reversed, but no matching reversal found",
                "summary": f"{_what(t)} is marked as reversed, but there is no opposite entry of the same amount.",
                "evidence": [f"Status is 'reversed' in {src_label(t.source)}.", "No credit/debit of the same amount within a week."],
                "suggestion": "If the money came back, add or import that entry. If it did not, correct the status.",
                "impact_text": "Reversed entries are already left out of your totals.", "tx_ids": [t.id]})

    # --- 2. refunds: a credit that gives money back for an earlier purchase ---
    debits = sorted((t for t in live if t.type == "debit" and t.txn_status == "success"), key=lambda t: (_day(t) or date.min, t.id))
    debit_days = [(_day(t) or date.min).toordinal() for t in debits]
    debits_by_amount: dict[int, list[Tx]] = defaultdict(list)
    for t in debits:
        debits_by_amount[t.amount].append(t)
    claimed: set[int] = set()
    for c in sorted((t for t in live if t.type == "credit" and t.txn_status == "success" and t.id not in paired),
                    key=lambda t: (_day(t) or date.min, t.id)):
        cd = _day(c)
        if not cd:
            continue
        keyword = bool(REFUND_WORDS.search(f"{c.payee} {c.merchant_raw or ''} {c.note}"))
        if keyword:   # partial refunds allowed: scan the 90 days before it
            lo, hi = bisect_left(debit_days, cd.toordinal() - 90), bisect_right(debit_days, cd.toordinal())
            pool = debits[lo:hi]
        else:         # no wording to go on: only an exact-amount match within 60 days counts as a refund
            pool = [d for d in debits_by_amount.get(c.amount, []) if 0 <= (cd - (_day(d) or date.min)).days <= 60]
        best = None
        for d in pool:
            if d.id in claimed or blocked(c, d) or d.amount < c.amount or (not keyword and d.amount != c.amount):
                continue
            ref_match = bool(c.reference_id and c.reference_id == d.reference_id)
            sim = _sim(names[c.id], names[d.id])
            if not (ref_match or sim >= (0.6 if keyword else 0.8)):
                continue
            gap = (cd - (_day(d) or date.min)).days
            rank = (0 if d.amount == c.amount else 1, gap, d.id)
            if best is None or rank < best[0]:
                best = (rank, d, gap, ref_match)
        if best:
            _, d, gap, ref_match = best
            claimed.add(d.id)
            links[c.id], links[d.id] = ("refund", d.id), ("refund", c.id)
            how = "same reference ID" if ref_match else ("same merchant, same amount" if d.amount == c.amount else "same merchant")
            partial = "" if d.amount == c.amount else f" Partial refund: {inr(c.amount)} of {inr(d.amount)}."
            word = "Refund" if keyword else "Looks like a refund"
            info[c.id].append(f"{word} of the {inr(d.amount)} purchase at {d.payee} on {fdate(d.date_time)} "
                              f"({how}, {gap} day{'s' if gap != 1 else ''} earlier).{partial}")
            info[d.id].append(f"Refunded by the {inr(c.amount)} credit on {fdate(c.date_time)}.{partial}")
        elif keyword:
            add_issue(f"refund:{c.id}", "refund_unmatched", c.id, None, 0, {
                "title": "Refund with no matching purchase",
                "summary": f"{_what(c)} looks like a refund, but no earlier purchase from that merchant matches.",
                "evidence": [f"The entry mentions a refund/reversal ({src_label(c.source)}).",
                             "No purchase from a similar merchant in the 90 days before it, for this amount or more."],
                "suggestion": "Check the original purchase is in Paisa (import an older statement or add it). "
                              "If this isn't a refund, confirm it as ordinary income.",
                "impact_text": f"It currently counts as {inr(c.amount)} received. Nothing changes until you link or correct it.",
                "tx_ids": [c.id]})

    # --- 3. same reference ID on several rows ---
    by_ref: dict[tuple[str, str], list[Tx]] = defaultdict(list)
    for t in live:
        if t.reference_id and t.id not in paired:
            by_ref[(t.reference_id, t.type)].append(t)
    ref_dup_pairs: set[frozenset[int]] = set()
    cross_source: dict[int, list[Tx]] = {}                  # id -> other rows agreeing on the reference
    in_conflict: set[int] = set()
    for (ref, _type), rows in sorted(by_ref.items()):
        if len(rows) < 2:
            continue
        days = [d for d in (_day(t) for t in rows) if d]
        consistent = len({t.amount for t in rows}) == 1 and days and (max(days) - min(days)).days <= 3
        if not consistent:
            ids = [t.id for t in rows]
            in_conflict |= set(ids)
            amounts = ", ".join(f"{inr(t.amount)} on {fdate(t.date_time)} ({src_label(t.source)})" for t in rows)
            add_issue(f"conflict:{ref}:{_type}", "ref_conflict", ids[0], ids[1], 0, {
                "title": "Same reference ID, different details",
                "summary": f"Reference {short_ref(ref)} appears on {len(rows)} entries that disagree: {amounts}.",
                "evidence": [f"Reference ID {ref} is shared.", "The amounts or dates differ by more than a rounding error."],
                "suggestion": "Open each entry, work out which is right, correct the other, or confirm both if they are genuinely different.",
                "impact_text": "All of these currently count in your totals.", "tx_ids": ids})
            continue
        rows = sorted(rows, key=_prefer)
        primary = rows[0]
        for other in rows[1:]:
            ref_dup_pairs.add(frozenset((primary.id, other.id)))
            same_source = primary.source == other.source
            counts_now = other.counts
            impact = -other.amount if counts_now else 0
            add_issue(f"dup:{_pair_key(primary.id, other.id)}", "duplicate_same_ref", primary.id, other.id, impact, {
                "title": "Same transaction recorded twice" if same_source else "Same transaction in two sources",
                "summary": f"{_what(primary)} is recorded in {src_label(primary.source)} and in {src_label(other.source)} "
                           f"with the same reference ID {short_ref(ref)}.",
                "evidence": [f"Identical reference ID ({ref}).", f"Same amount ({inr(primary.amount)}) and direction.",
                             "Dates are within 3 days."],
                "suggestion": f"These are one payment. Merge them; Paisa suggests keeping the record from {src_label(primary.source)}.",
                "impact_text": (f"Both currently count. If merged, your total {'spent' if primary.type == 'debit' else 'received'} "
                                f"changes by {inr(impact)}.") if counts_now else
                               "No change to totals: the second record isn't counted right now.",
                "keep_id": primary.id, "drop_id": other.id, "tx_ids": [primary.id, other.id], "same_source": same_source})
            if not same_source:
                cross_source.setdefault(primary.id, []).append(other)
                cross_source.setdefault(other.id, []).append(primary)
    for pid, kids in children.items():       # copies already merged under a record still count as evidence
        for k in kids:
            if k.reference_id and pid in by_id and k.reference_id == by_id[pid].reference_id and k.source != by_id[pid].source:
                cross_source.setdefault(pid, []).append(k)

    # --- 4. possible duplicates when there is no reference to go on ---
    buckets: dict[tuple[str, int], list[Tx]] = defaultdict(list)
    for t in live:
        if t.txn_status in ("success", "pending"):
            buckets[(t.type, t.amount)].append(t)
    for (_type, _amount), rows in sorted(buckets.items()):
        if len(rows) < 2:
            continue
        parent = {t.id: t.id for t in rows}

        def find(x):
            while parent[x] != x:
                parent[x] = parent[parent[x]]
                x = parent[x]
            return x
        reasons_for: dict[frozenset[int], list[str]] = {}
        for i, a in enumerate(rows):
            for b in rows[i + 1:]:
                if (a.reference_id and b.reference_id) or _sim(names[a.id], names[b.id]) < 0.8:
                    continue          # two different references = two different payments
                da, db = parse_dt(a.date_time), parse_dt(b.date_time)
                if not da or not db:
                    continue
                if a.source == b.source:
                    # Same file or same source: identical rows are normally genuine repeat purchases. Only a
                    # double-tap on a hand-entered source within minutes is suspicious.
                    if a.source not in ("manual", "sms-paste", "pay-flow") or abs((da - db).total_seconds()) > 600:
                        continue
                    when = f"entered {int(abs((da - db).total_seconds()) // 60)} minutes apart in the same source"
                elif abs((da.date() - db.date()).days) <= 1:
                    when = "dates are " + ("the same day" if da.date() == db.date() else "one day apart")
                else:
                    continue
                parent[find(a.id)] = find(b.id)
                reasons_for[frozenset((a.id, b.id))] = [when]
        comps: dict[int, list[Tx]] = defaultdict(list)
        for t in rows:
            comps[find(t.id)].append(t)
        for comp in comps.values():
            if len(comp) < 2:
                continue
            comp.sort(key=_prefer)
            primary = comp[0]
            for other in comp[1:]:
                if frozenset((primary.id, other.id)) in ref_dup_pairs or (
                        primary.reference_id and other.reference_id and primary.reference_id == other.reference_id):
                    continue
                counts_now = other.counts
                impact = -other.amount if counts_now else 0
                when = reasons_for.get(frozenset((primary.id, other.id))) or ["close in time"]
                add_issue(f"dup:{_pair_key(primary.id, other.id)}", "duplicate_possible", primary.id, other.id, impact, {
                    "title": "Possible duplicate",
                    "summary": f"{_what(primary)} ({src_label(primary.source)}) and {_what(other)} ({src_label(other.source)}) may be one payment.",
                    "evidence": [f"Same amount ({inr(primary.amount)}) and direction ({'spent' if primary.type == 'debit' else 'received'}).",
                                 f"Merchant names look alike: '{primary.payee}' and '{other.payee}'.", f"Timing: {when[0]}.",
                                 "At least one of them has no reference ID, so Paisa can't be sure."],
                    "suggestion": f"If it is one payment, merge them (Paisa suggests keeping {src_label(primary.source)}). "
                                  "If you really paid twice, choose 'Not a duplicate'.",
                    "impact_text": (f"Both currently count. If merged, your total {'spent' if primary.type == 'debit' else 'received'} "
                                    f"changes by {inr(impact)}.") if counts_now else
                                   "No change to totals: the second record isn't counted right now.",
                    "keep_id": primary.id, "drop_id": other.id, "tx_ids": [primary.id, other.id], "same_source": False})

    # --- 5. incomplete data ---
    for t in live:
        missing = []
        if not t.payee.strip() or _norm(t.payee) in ("unknown", "unknown merchant"):
            missing.append("merchant name")
        d = parse_dt(t.date_time)
        if d is None:
            missing.append("a readable date")
        elif d.date() > today and (d.date() - today).days > 1:
            missing.append("a date that isn't in the future")
        if missing or t.import_notes:
            parts = ([f"it is missing {' and '.join(missing)}"] if missing else []) +                     ([f"the import file had a problem: {'; '.join(t.import_notes)}"] if t.import_notes else [])
            add_issue(f"incomplete:{t.id}", "incomplete", t.id, None, 0, {
                "title": "Incomplete or unclear record",
                "summary": "This entry needs a look: " + " and ".join(parts) + ".",
                "evidence": ([f"Checked: merchant, date. Missing: {', '.join(missing)}."] if missing else []) + list(t.import_notes),
                "suggestion": "Open it and fill in the missing detail, or confirm it as it is.",
                "impact_text": "It counts in your totals as it is.", "tx_ids": [t.id]})

    # --- 6. verdicts ---
    open_by_tx: dict[int, list[Issue]] = defaultdict(list)
    for i in issues:
        if i.state == "open":
            for tid in i.details.get("tx_ids", [i.tx_id]):
                open_by_tx[tid].append(i)

    verdicts: dict[int, Verdict] = {}
    for t in live:
        flags: list[str] = []
        suppressed = t.user_confirmed or t.flag_dismissed      # a human already looked at the flags
        for i in open_by_tx.get(t.id, []):
            if i.kind == "duplicate_same_ref" and not i.details.get("same_source"):
                continue                                       # evidence match, shown as a duplicate indicator only
            flags.append(f"{i.details['title']}: {i.details['summary']}")
        # evidence
        ev: list[str] = []
        if is_bank(t.source) and t.reference_id and t.txn_status != "pending":
            ev.append(f"Bank statement row in {src_label(t.source)} with reference {short_ref(t.reference_id)}.")
        for o in cross_source.get(t.id, []):
            ev.append(f"Matches {kind_phrase(o.source)} ref {short_ref(t.reference_id or '')} in {src_label(o.source)}"
                      f"{' (merged copy)' if o.merged_into_id is not None else ''}.")
        for i in open_by_tx.get(t.id, []):
            if i.kind == "duplicate_same_ref" and not i.details.get("same_source"):
                info[t.id].append(f"The same payment is also recorded in {src_label(by_id[i.other_id if i.tx_id == t.id else i.tx_id].source)}; "
                                  "merge them so it isn't counted twice.")
        kids = children.get(t.id, [])
        if kids:
            info[t.id].append(f"{len(kids)} duplicate record{'s' if len(kids) != 1 else ''} merged into this one "
                              f"({', '.join(src_label(k.source) for k in kids)}).")

        if flags and not suppressed:
            status, reasons = "needs_review", flags + ev
        elif ev:
            status, reasons = "verified", ev
        else:
            status, reasons = "unconfirmed", [_base_reason(t)]
        reasons = reasons + info.get(t.id, [])
        if t.txn_status == "failed":
            reasons.append("The payment failed, so it is not counted in your spending.")
        elif t.txn_status == "pending":
            reasons.append("Pending payments are not counted until they settle.")
        if t.flag_dismissed:
            reasons.append("You dismissed the review flag on this transaction.")
        if t.user_confirmed:
            when = f" on {fdate(t.user_confirmed_at)}" if t.user_confirmed_at else ""
            reasons.append(f"You confirmed this{when}. That is your own check, not bank evidence, so the status above is unchanged.")
        kind, other = links.get(t.id, (None, None))
        verdicts[t.id] = Verdict(status, reasons, kind, other)
    issues.sort(key=lambda i: (i.key))
    return Evaluation(verdicts, issues)


def _base_reason(t: Tx) -> str:
    """Why a transaction with no evidence is 'unconfirmed', in plain English."""
    s = t.source
    if t.txn_status == "pending":
        return ("Waiting for you to confirm the payment went through. Paisa can't see your bank, so it can't tell."
                if s == "pay-flow" else "The payment is still pending.")
    if s == "manual":
        return "Typed in by you. Nothing outside Paisa (a bank record with a matching reference) backs it up yet."
    if s == "sms-paste":
        return ("Came from a pasted text message" + (" with no reference ID" if not t.reference_id else "") +
                ". A message alone isn't proof; it needs a bank statement row with the same reference.")
    if s == "pay-flow":
        return ("You marked this payment as not gone through." if t.txn_status == "failed" else
                "Recorded from the Pay screen after you said it went through. That is your word, not bank evidence.")
    if is_bank(s):
        return (f"Imported from {src_label(s)}, but the row has no reference ID, so it can't be matched to anything else."
                if not t.reference_id else f"Imported from {src_label(s)}, but the bank row is not settled.")
    if s == "legacy":
        return "Added before Paisa recorded where entries came from, so there is nothing to check it against."
    if s == "sample":
        return "Sample data."
    return "Not enough evidence either way."
